/* Funzioni di utilità: formattazione, numeri, date, escape HTML */

function fmt(n, dec=0){
  return Number(n).toLocaleString(langLocale(),{minimumFractionDigits:dec,maximumFractionDigits:dec});
}

/* Locale dell'interfaccia: formato di numeri, prezzi, date e giorni segue la lingua scelta */
const LOCALES = {it:'it-IT', en:'en-GB', fr:'fr-FR', de:'de-DE', es:'es-ES'};

function langLocale(){ return LOCALES[STATE.settings.language] || 'it-IT'; }

/* ---------------- PREZZI DI VENDITA ----------------
   Il prezzo di una configurazione (grammatura, variante, topping…) non si mostra né si fa pagare al
   centesimo: si arrotonda per eccesso ai 10 centesimi (€10,88 → €10,90), così il margine non scende
   mai; da €2 in su, se l'arrotondamento arriva all'euro tondo, diventa ,90 (€10,95 → €10,90: prezzo psicologico).
   Un prezzo già tondo del listino (€2,00) non si tocca. Vale per
   ogni porzione: 2 porzioni = 2 × il prezzo pulito di una. Lo stesso calcolo lo fa il server dei
   pagamenti (server/supabase/functions/_shared/pricing.js): tools/check_pricing.js verifica che coincidano. */
function sellPrice(v){
  const c = Math.round((+v || 0) * 100);
  if(c <= 0) return 0;
  let r = Math.ceil(c / 10) * 10;
  if(r >= 200 && r % 100 === 0 && r !== c) r -= 10;   // ,90 solo se l'arrotondamento è salito all'euro tondo: un prezzo già tondo (bevande €2,00) resta com'è
  return r / 100;
}

/* Prezzo pulito di n porzioni uguali (price = totale grezzo delle n porzioni) */
function sellPriceOf(price, portions = 1){
  const n = Math.max(1, portions || 1);
  return Math.round(sellPrice(price / n) * n * 100) / 100;
}

/* Sconto in percentuale: arrotondato ai 10 centesimi a favore del cliente, così anche il totale resta pulito */
function sellDiscount(total, pct){
  const c = Math.round((+total || 0) * 100);
  return pct > 0 ? Math.min(c, Math.ceil(c * pct / 10 - 1e-9) * 10) / 100 : 0;
}

function fmtPrice(n){
  if(n < 0) return '−' + fmtPrice(-n);   // −€5,00 (non €-5,00)
  const s = fmt(n, 2);
  return ['fr','de','es'].includes(STATE.settings.language) ? s+'\u00a0€' : '€'+s;
}

/* Vibrazione leggera come conferma (aggiunto al carrello, giornata centrata). La supportano i telefoni
   Android; su iPhone il browser non la offre e semplicemente non succede nulla. Mai con "riduci movimento". */
function haptic(pattern){
  try{
    if(!navigator.vibrate || (window.matchMedia && matchMedia('(prefers-reduced-motion: reduce)').matches)) return;
    if(navigator.userActivation && !navigator.userActivation.isActive) return;   // serve un tocco recente dell'utente
    navigator.vibrate(pattern);
  }catch{ /* non supportata o bloccata: nessun problema */ }
}

function calcForGrams(food, grams){
  const r = grams/100;
  return {
    kcal: food.kcal*r, p: food.p*r, c: food.c*r, f: food.f*r,
    fib: (food.fib||0)*r, price: (food.price||0)*r
  };
}

/* Alimenti a pezzi (le uova): l'utente sceglie quanti sono, il calcolo resta in grammi (unit.g per pezzo).
   qtyLabel dà «2 uova» oppure «150 g»; qtyHtml lo stesso con l'unità in piccolo (schermata Match). */
function qtyLabel(food, grams){
  if(!food || !food.unit) return grams + ' g';
  const n = Math.round(grams / food.unit.g);
  return n + ' ' + tUnit(food, n);
}

function qtyHtml(food, grams){
  if(!food || !food.unit) return `${grams}<small>g</small>`;
  const n = Math.round(grams / food.unit.g);
  return `${n} <small>${tUnit(food, n)}</small>`;
}

/* Quantità di un ingrediente in milligrammi scritta come «600 mg» o «1,6 g» */
function doseText(mg){
  return mg >= 1000 ? fmt(mg/1000, mg % 1000 ? 1 : 0) + ' g' : mg + ' mg';
}

/* Testo di un suggerimento: «150g di Pollo» oppure, per gli alimenti a pezzi, «2 uova» */
function suggQtyText(food, grams){
  return food.unit ? qtyLabel(food, grams) : `${grams}g ${uiT('common.of','di')} ${tName(food)}`;
}

/* Valori di UNA porzione. Bevande, verdure, frutta e salse sono espressi per
   100 g/ml e vanno scalati sulla porzione; piatti, dolci e integratori hanno
   già i valori per porzione. */
const PER_100_CATS = ['drink','veg','fruit','sauce'];

function portionValues(f){
  const r = PER_100_CATS.includes(f.cat) ? (f.portion||100)/100 : 1;
  return {kcal:f.kcal*r, p:f.p*r, c:f.c*r, f:f.f*r};
}

/* Numeri digitati in un campo: intero (si tengono solo le cifre) o decimale (virgola o punto); vuoto o zero → null */
function intFromInput(v){ return parseInt(String(v).replace(/[^0-9]/g,''),10) || null; }
function floatFromInput(v){ return parseFloat(String(v).replace(',','.')) || null; }

function clamp(v,min,max){ return Math.max(min, Math.min(max, v)); }

/* Ogni testo scritto dall'utente (o arrivato da fonti esterne: geolocalizzazione,
   OpenFoodFacts) va escapato prima di finire in innerHTML o in un attributo. */
function esc(s){
  return String(s==null?'':s).replace(/[&<>"']/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
}

function todayKey(d){
  const x = d || new Date();
  return x.getFullYear()+'-'+String(x.getMonth()+1).padStart(2,'0')+'-'+String(x.getDate()).padStart(2,'0');
}

function shiftDate(key, days){
  const [y,m,d] = key.split('-').map(Number);
  const dt = new Date(y, m-1, d);
  dt.setDate(dt.getDate()+days);
  return todayKey(dt);
}

/* Minuscolo per i sostantivi tradotti: in tedesco vanno sempre scritti con la maiuscola */
function lcT(s){ return STATE.settings.language==='de' ? s : String(s).toLowerCase(); }

function prettyDate(key){
  if(key === todayKey()) return uiT('common.today','Oggi');
  if(key === shiftDate(todayKey(),-1)) return uiT('common.yesterday','Ieri');
  if(key === shiftDate(todayKey(),1)) return uiT('common.tomorrow','Domani');
  const [y,m,d] = key.split('-').map(Number);
  return new Date(y, m-1, d).toLocaleDateString(langLocale(), {day:'numeric', month:'short', year:'numeric'});
}

/* Etichetta corta per selettori a 7 giorni (programmazione ordini/piano
   pasti): oggi/domani per esteso, altrimenti giorno della settimana
   abbreviato + numero, per restare leggibile in una fascia di chip strette. */
function shortDayLabel(key){
  if(key === todayKey()) return uiT('common.today','Oggi');
  if(key === shiftDate(todayKey(),1)) return uiT('common.tomorrow','Domani');
  const [y,m,d] = key.split('-').map(Number);
  const dt = new Date(y, m-1, d);
  const idx = (dt.getDay()+6)%7; // 0=lunedì
  return `${weekDayName(idx).slice(0,3)} ${d}`;
}

/* Azioni dei pulsanti: ogni schermata dichiara le proprie con defineActions(), un solo ascoltatore di click le smista */

const ACTIONS = Object.create(null);

function defineActions(map){
  Object.keys(map).forEach(name=>{
    if(ACTIONS[name]) throw new Error('Azione duplicata: ' + name);
    ACTIONS[name] = map[name];
  });
}

document.addEventListener('click', e=>{
  const el = e.target.closest('[data-action]');
  const handler = el && ACTIONS[el.dataset.action];
  if(handler) handler(el, e);
});

/* Da tastiera: Invio o Spazio su un elemento cliccabile che non è un pulsante (card alimento, metodo di
   pagamento... resi raggiungibili da a11yEnhance) fanno esattamente quello che fa il clic */
document.addEventListener('keydown', e=>{
  if(e.key !== 'Enter' && e.key !== ' ') return;
  const el = e.target;
  if(!el || !el.dataset || !el.dataset.action || ['BUTTON','A','INPUT','SELECT','TEXTAREA'].includes(el.tagName)) return;
  e.preventDefault();
  el.click();
});

/* Campi di testo: ogni schermata dichiara i propri gestori con defineFieldHandlers(evento, [[selettore, gestore], ...]);
   il gestore riceve il campo e l'evento. Si eseguono tutti quelli il cui selettore corrisponde al campo. */
const FIELD_HANDLERS = {input:[], change:[], keydown:[], blur:[], compositionend:[]};

function defineFieldHandlers(type, handlers){
  FIELD_HANDLERS[type].push(...handlers);
}

Object.keys(FIELD_HANDLERS).forEach(type=>{
  // blur non risale nel DOM: si ascolta in fase di cattura
  document.addEventListener(type, e=>{
    const field = e.target;
    if(!field || !field.matches) return;
    FIELD_HANDLERS[type].forEach(([selector, handler])=>{ if(field.matches(selector)) handler(field, e); });
    if(type === 'keydown') enterKey(field, e);
  }, type === 'blur');
});

/* Invio («Vai», «Fine» sulla tastiera del telefono) nei campi di testo. L'app non usa <form>: senza questo Invio non faceva
   nulla. Nei moduli qui sotto passa al campo successivo e sull'ultimo preme il pulsante del modulo; negli altri campi
   passa al campo successivo della schermata o, sull'ultimo, chiude la tastiera. */
const ENTER_FORMS = [
  [['#auth-name', '#auth-email', '#auth-password'], 'auth-submit'],
  [['#modal-input'], 'modal-confirm'],
  [['#voucher-code'], 'redeem-voucher'],
  [['#referral-code-input'], 'referral-redeem'],
  [['#ean-input'], 'ean-lookup'],
  [['#table-input'], 'table-manual'],
  [['#man-name', '#man-kcal', '#man-c', '#man-p', '#man-f'], 'diary-manual'],
  [['#biz-company', '#biz-email', '#biz-people'], 'business-lead-submit'],
];
const ENTER_TEXT_TYPES = /^(text|email|tel|password|search|number|url)$/;

function enterKey(field, e){
  if(e.key !== 'Enter' || e.isComposing || e.defaultPrevented || field.tagName !== 'INPUT' || !ENTER_TEXT_TYPES.test(field.type || 'text')) return;
  const scope = field.closest('#modal-root') || field.closest('#view');
  if(!scope) return;
  const form = ENTER_FORMS.find(([ids])=> ids.some(id=> field.matches(id)));
  const inputs = form
    ? form[0].map(id=> scope.querySelector(id)).filter(Boolean)
    : [...scope.querySelectorAll('input')].filter(i=> ENTER_TEXT_TYPES.test(i.type || 'text') && !i.disabled && !i.readOnly && i.offsetParent !== null);
  const next = inputs[inputs.indexOf(field) + 1];
  e.preventDefault();
  if(next){ next.focus(); return; }
  const btn = form && scope.querySelector(`[data-action="${form[1]}"]`);
  if(btn && !btn.disabled) btn.click();
  else field.blur();   // ultimo campo senza un pulsante da premere: si chiude la tastiera
}

/* Accessibilità dei controlli: nomi per gli screen reader e uso da tastiera */

/* Dopo ogni ridisegno completa i controlli che non si leggono da soli, senza cambiare nulla di quello
   che fanno:
   - elementi cliccabili che non sono pulsanti (card alimento, «Vedi il menu», metodo di pagamento...):
     ruolo di pulsante e raggiungibili con Tab; Invio/Spazio li attivano come un clic (actions.js);
   - pulsanti con sola icona (cerca, carrello, indietro, preferiti, −/+...): un nome da leggere;
   - campi con un'etichetta visibile accanto ma non collegata: la stessa etichetta come nome;
   - tab della barra in basso: quella attiva è segnalata come pagina corrente. */
const A11Y_NATIVE = ['BUTTON', 'A', 'INPUT', 'SELECT', 'TEXTAREA', 'LABEL'];

function a11yActionLabel(el){
  const a = el.dataset.action, d = +el.dataset.delta;
  const view = el.dataset.view;
  const less = uiT('a11y.less', 'Diminuisci'), more = uiT('a11y.more', 'Aumenta');
  switch(a){
    case 'tab': return ({home:'Home', menu:'Menu', match:'Match', diary:uiT('nav.diary','Diario'), profile:uiT('nav.profile','Profilo')})[view] || tViewTitle(view);
    case 'nav': return view === 'search' ? uiT('a11y.search', 'Cerca') : view === 'cart' ? uiT('a11y.cart', 'Carrello') : tViewTitle(view);
    case 'back': return uiT('a11y.back', 'Indietro');
    case 'fav': return uiT('a11y.fav', 'Preferiti');
    case 'modal-close': return uiT('common.close', 'Chiudi');
    case 'remove-cart': return uiT('a11y.remove', 'Rimuovi');
    case 'share-food': case 'share-order': case 'share-meal': return uiT('a11y.share', 'Condividi');
    case 'diary-day': return d < 0 ? uiT('a11y.prevDay', 'Giorno precedente') : uiT('a11y.nextDay', 'Giorno successivo');
    case 'gr-dec': case 'serv-dec': return less;
    case 'gr-inc': case 'serv-inc': return more;
  }
  if(el.dataset.delta !== undefined) return d < 0 ? less : more;   // cart-qty, water, topping-qty, portion-qty...
  return el.getAttribute('title') || '';
}

function a11yEnhance(root){
  if(!root || !root.querySelectorAll) return;
  root.querySelectorAll('[data-action]').forEach(el=>{
    if(!A11Y_NATIVE.includes(el.tagName) && !el.classList.contains('modal-backdrop') && !el.closest('button')){
      if(!el.hasAttribute('role')) el.setAttribute('role', 'button');
      if(!el.hasAttribute('tabindex')) el.tabIndex = 0;
    }
    if(!el.hasAttribute('aria-label') && !(el.textContent || '').trim()){
      const label = a11yActionLabel(el);
      if(label) el.setAttribute('aria-label', label);
    }
    if(el.dataset.action === 'tab' && el.classList.contains('nav-item')){
      if(el.classList.contains('active')) el.setAttribute('aria-current', 'page'); else el.removeAttribute('aria-current');
      if(!el.hasAttribute('aria-label')) el.setAttribute('aria-label', a11yActionLabel(el));
    }
  });
  root.querySelectorAll('input:not([type=hidden]), select, textarea').forEach(inp=>{
    if(inp.hasAttribute('aria-label') || inp.closest('label') || (inp.id && root.querySelector(`label[for="${inp.id}"]`))) return;
    let lab = inp.previousElementSibling;
    if(!lab || lab.tagName !== 'LABEL') lab = inp.parentElement && inp.parentElement.querySelector(':scope > label, :scope > .qty-label, :scope > .ab-label');
    if(!lab){ const box = inp.closest('.qty-block, .match-field, .field-group > div'); lab = box && box.querySelector('label, .qty-label, .ms-name, .mr-name'); }
    const text = lab && (lab.textContent || '').trim();
    if(text) inp.setAttribute('aria-label', text);
  });
}

/* Stato dell'app e persistenza in localStorage */

/* ---------------- PERSISTENZA ----------------
   Salva i dati dell'utente nel browser, così profilo, diario, preferiti e
   ordini restano al ricaricamento. Tutto protetto da try/catch: se lo
   storage non è disponibile (modalità privata, iframe con restrizioni)
   l'app continua a funzionare tenendo i dati solo in memoria. */
const STORAGE_KEY = 'macros_app_v1';

let storageOK = true;

/* Foto progresso e diario sono i dati più pesanti. Il diario viene salvato
   senza i giorni vuoti (getDay() ne crea uno anche solo leggendo una data);
   se la quota di localStorage (~5 MB) si esaurisce si salva comunque tutto il
   resto senza foto, invece di disattivare del tutto la persistenza. */
function buildSnapshot(withPhotos){
  const diary = {};
  Object.keys(STATE.diary).forEach(k=>{
    const d = STATE.diary[k];
    if(!isPlainObj(d)) return;
    const hasMeals = MEAL_SLOTS.some(s=>d[s.key] && d[s.key].length);
    if(hasMeals || d.water>0 || d.steps>0 || d.trainingDay || d.cheatDay) diary[k] = d;
  });
  return {
    auth: {loggedIn:STATE.auth.loggedIn, method:STATE.auth.method, disclaimer:STATE.auth.disclaimer, name:STATE.auth.name, firstName:STATE.auth.firstName, lastName:STATE.auth.lastName, email:STATE.auth.email,
           registered:STATE.auth.registered, birthDate:STATE.auth.birthDate, photo: withPhotos ? STATE.auth.photo : ''},
    signup: (STATE.auth.registered || !STATE.signup) ? null
      : {step:STATE.signup.step, draft: withPhotos ? STATE.signup.draft : {...STATE.signup.draft, photo:''}},
    profile: STATE.profile,
    nutriProfile: STATE.nutriProfile,
    weightLog: STATE.weightLog,
    favorites: [...STATE.favorites],
    diary,
    orders: STATE.orders,
    orderCounter: STATE.orderCounter,
    cart: STATE.cart,
    build: STATE.build,
    orderMode: STATE.orderMode,
    tableNumber: STATE.tableNumber,
    delivery: STATE.delivery,
    settings: STATE.settings,
    subscription: STATE.subscription,
    consult: STATE.consult,
    consultTrain: STATE.consultTrain,
    chats: STATE.chats,
    vouchers: STATE.vouchers,
    activeVoucher: STATE.activeVoucher,
    autoVouchers: STATE.autoVouchers,
    businessLead: STATE.businessLead,
    loyalty: STATE.loyalty,
    referral: STATE.referral,
    challenges: STATE.challenges,
    achievements: STATE.achievements,
    progressPhotos: withPhotos ? STATE.progressPhotos : [],
    dietary: STATE.dietary,
    savedCombos: STATE.savedCombos,
    goals: STATE.goals,
    group: STATE.group,
    groupJoin: STATE.groupJoin,
    engineVersion: ENGINE_VERSION,
  };
}

/* localOnly: salva solo sul dispositivo (senza programmare il salvataggio online, cloud.js).
   storageOK diventa false solo se il browser non dà accesso a localStorage (vedi loadState): uno spazio esaurito
   non spegne i salvataggi per tutta la sessione, li riprova al tocco successivo e lo dice una volta. */
function saveState(localOnly){
  if(!localOnly) cloudSchedulePush();
  if(!storageOK || stateStale) return;   // stateStale: un'altra scheda ha dati più nuovi, non si sovrascrivono
  try{
    localStorage.setItem(STORAGE_KEY, JSON.stringify(buildSnapshot(true)));
    return;
  }catch{}
  try{
    localStorage.setItem(STORAGE_KEY, JSON.stringify(buildSnapshot(false)));
    if(!saveState.warned){
      saveState.warned = true;
      toast(uiT('toast.storageFull','Spazio esaurito: le foto progresso non vengono salvate'));
    }
    return;
  }catch{}
  if(!saveState.failWarned){
    saveState.failWarned = true;
    toast(uiT('toast.storageSaveFailed','Spazio esaurito: le ultime modifiche non sono state salvate su questo dispositivo'));
  }
}

/* Dopo un tocco: il salvataggio parte subito dopo, non mentre il telefono deve mostrare la risposta (con il
   diario di mesi e le foto progresso lo stato pesa, e riscriverlo a ogni tocco rallentava). Più tocchi
   ravvicinati = un salvataggio solo. Mai perso: si salva comunque appena l'app va in background o si chiude. */
let stateDirty = false;
function saveStateSoon(){
  if(stateSkipNextSave){ stateSkipNextSave = false; return; }
  stateDirty = true;
  stateGuardUnload(true);
  setTimeout(flushStateSave, 250);
}
function flushStateSave(){
  stateGuardUnload(false);
  if(!stateDirty) return;
  stateDirty = false;
  saveState();
}
/* Chiusura della scheda con un salvataggio ancora in attesa: in Firefox una modifica scritta solo al pagehide a volte non
   restava (verificato nei test di chiusura). beforeunload arriva prima, a pagina ancora intera. L'ascoltatore c'è solo
   finché c'è qualcosa da salvare: uno fisso toglierebbe in Firefox la cache «indietro/avanti» della pagina. */
let stateUnloadGuard = false;
function stateGuardUnload(on){
  if(on === stateUnloadGuard || typeof window === 'undefined' || !window.addEventListener || !window.removeEventListener) return;
  stateUnloadGuard = on;
  if(on) window.addEventListener('beforeunload', flushStateSave);
  else window.removeEventListener('beforeunload', flushStateSave);
}

/* Due schede (o la demo della landing e l'app) sullo stesso dispositivo condividono lo stesso salvataggio. Quando
   l'altra scheda salva, questa smette di scrivere (i suoi dati sono vecchi) e appena è in primo piano ricarica quelli
   nuovi: altrimenti al tocco successivo li riscriverebbe sopra, cancellando le modifiche fatte nell'altra. */
let stateStale = false, stateSkipNextSave = false;
function stateReloadFromStorage(){
  let raw = null;
  try{ raw = localStorage.getItem(STORAGE_KEY); }catch{ return; }
  if(!raw){ location.reload(); return; }   // l'altra scheda ha azzerato i dati: si riparte puliti anche qui
  stateStale = false;   // anche se i dati dell'altra scheda non si leggono: questa non deve smettere di salvare
  try{ applySnapshot(JSON.parse(raw)); }catch(e){ console.error("MACRO'S: dati dell'altra scheda non leggibili", e); return; }
  syncUidCounter();
  stateSkipNextSave = true;   // il ridisegno non riscrive i dati appena letti (con due schede aperte si rimbalzerebbero)
  render();
}

if(typeof document !== 'undefined' && document.addEventListener){
  document.addEventListener('visibilitychange', ()=>{
    if(document.visibilityState === 'hidden') flushStateSave();
    else if(stateStale) stateReloadFromStorage();
  });
  if(window.addEventListener){
    window.addEventListener('pagehide', flushStateSave);
    window.addEventListener('storage', e=>{
      if(e.key !== STORAGE_KEY && e.key !== null) return;   // null: l'altra scheda ha svuotato tutto
      stateStale = true;
      stateDirty = false;
      if(document.visibilityState === 'visible') stateReloadFromStorage();
    });
  }
}

/* Un salvataggio illeggibile (scrittura interrotta, dati modificati a mano, versione diversa) non deve spegnere i
   salvataggi: si tiene una copia del testo originale (STORAGE_KEY + '_backup', per poterlo recuperare), si parte
   con quello che si riesce a leggere e lo si dice all'utente appena l'app è aperta (stateLoadNotice). */
let stateLoadProblem = false;
function loadState(){
  let raw = null;
  try{ raw = localStorage.getItem(STORAGE_KEY); }
  catch{ storageOK = false; return; }   // localStorage non disponibile (navigazione privata, riquadro con restrizioni)
  if(raw){
    try{ applySnapshot(JSON.parse(raw)); }
    catch(e){
      console.error("MACRO'S: salvataggio non leggibile", e);
      stateLoadProblem = true;
      try{ localStorage.setItem(STORAGE_KEY + '_backup', raw); }catch{ /* spazio esaurito: la copia non entra */ }
    }
  }
  syncUidCounter();
}

function stateLoadNotice(){
  if(!stateLoadProblem) return;
  stateLoadProblem = false;
  toast(uiT('toast.storageCorrupt','Alcuni dati salvati non erano leggibili: abbiamo ripristinato quelli validi'));
}

/* Solo oggetti veri (non null, non array): i dati salvati possono arrivare da versioni vecchie o essere stati alterati */
function isPlainObj(v){ return !!v && typeof v === 'object' && !Array.isArray(v); }
function objList(v){ return Array.isArray(v) ? v.filter(isPlainObj) : null; }

/* Giorni del diario: solo oggetti, con le voci di ogni pasto che siano oggetti (getDay ripara i campi mancanti) */
function cleanDiary(d){
  const out = {};
  Object.keys(d).forEach(k=>{
    const day = d[k];
    if(!/^\d{4}-\d{2}-\d{2}$/.test(k) || !isPlainObj(day)) return;
    MEAL_SLOTS.forEach(s=>{ if(Array.isArray(day[s.key])) day[s.key] = day[s.key].filter(isPlainObj); });
    out[k] = day;
  });
  return out;
}

/* Applica allo stato un salvataggio (quello del dispositivo o quello scaricato dal salvataggio online, cloud.js).
   Ogni campo si prende solo se ha la forma giusta: un campo rovinato si scarta, gli altri restano. */
function applySnapshot(s){
    if(!isPlainObj(s)) throw new Error('salvataggio non valido');
    // chi ha già un profilo calcolato (versioni precedenti) non deve rifare l'iscrizione
    if(isPlainObj(s.auth)) Object.assign(STATE.auth, {loggedIn:!!s.auth.loggedIn, method:s.auth.method||null, disclaimer:(isPlainObj(s.auth.disclaimer) && s.auth.disclaimer.v) ? s.auth.disclaimer : null, name:String(s.auth.name||''), firstName:String(s.auth.firstName||''), lastName:String(s.auth.lastName||''), email:String(s.auth.email||''),
      photo:String(s.auth.photo||''), birthDate:String(s.auth.birthDate||''), registered: s.auth.registered!==undefined ? !!s.auth.registered : !!s.nutriProfile});
    if(isPlainObj(s.signup) && isPlainObj(s.signup.draft) && !STATE.auth.registered){
      signupStart();
      Object.assign(STATE.signup.draft, s.signup.draft);
      ['firstName','lastName','email','phone','birthDate'].forEach(k=>{ if(typeof STATE.signup.draft[k] !== 'string') STATE.signup.draft[k] = ''; });
      if(!isPlainObj(STATE.signup.draft.diet)) STATE.signup.draft.diet = {vegetarian:false, vegan:false, allergies:{}};
      if(!isPlainObj(STATE.signup.draft.diet.allergies)) STATE.signup.draft.diet.allergies = {};
      if(!isPlainObj(STATE.signup.draft.nutritionPref)) STATE.signup.draft.nutritionPref = {protein:null, carbs:null, fat:null};
      STATE.signup.step = clamp(parseInt(s.signup.step,10)||1, 1, signupSeq(STATE.signup.draft).length);
    }
    if(isPlainObj(s.profile))      Object.assign(STATE.profile, s.profile);
    if(isPlainObj(s.nutriProfile)) STATE.nutriProfile = s.nutriProfile;
    if(Array.isArray(s.weightLog)) STATE.weightLog = s.weightLog.filter(e=>isPlainObj(e) && typeof e.date === 'string' && isFinite(+e.kg));
    if(Array.isArray(s.favorites)) STATE.favorites = new Set(s.favorites.filter(x=>typeof x === 'string'));
    if(isPlainObj(s.diary))        STATE.diary = cleanDiary(s.diary);
    if(Array.isArray(s.orders))    STATE.orders = s.orders.filter(o=>isPlainObj(o) && typeof o.num === 'number');
    if(typeof s.orderCounter === 'number') STATE.orderCounter = s.orderCounter;
    if(Array.isArray(s.cart))      STATE.cart = objList(s.cart).filter(cartItemKnown);
    if(isPlainObj(s.build)){
      STATE.build = {carb:null, protein:null, fat:null, ...s.build};
      ['carb','protein','fat'].forEach(k=>{ const b = STATE.build[k]; if(b && !(isPlainObj(b) && findFood(b.foodId))) STATE.build[k] = null; });
      STATE.build.extras = Array.isArray(STATE.build.extras) ? STATE.build.extras : [];
      STATE.build.drinks = Array.isArray(STATE.build.drinks) ? STATE.build.drinks : [];
    }
    if(s.orderMode && ORDER_MODES[s.orderMode]) STATE.orderMode = s.orderMode;
    if(isPlainObj(s.delivery))     Object.assign(STATE.delivery, s.delivery);
    if(isPlainObj(s.settings))     Object.assign(STATE.settings, s.settings, {notifications: eduNotifClean({orderStatus:true, promos:true, diaryReminder:false, mealTip:true, ...(isPlainObj(s.settings.notifications) ? s.settings.notifications : {})})});
    if(isPlainObj(s.subscription) && SUB_PLANS[s.subscription.plan] && isPlainObj(s.subscription.week)) STATE.subscription = s.subscription;
    else if(s.subscription === null) STATE.subscription = null;
    const booking = b=> isPlainObj(b) && CONSULT_MODES[b.mode] && typeof b.date === 'string' && typeof b.time === 'string';
    if(booking(s.consult) || s.consult === null) STATE.consult = s.consult;
    if(booking(s.consultTrain) || s.consultTrain === null) STATE.consultTrain = s.consultTrain;
    if(isPlainObj(s.chats)){ STATE.chats = {}; Object.keys(s.chats).forEach(k=>{ const l = objList(s.chats[k]); if(l) STATE.chats[k] = l; }); }
    if(Array.isArray(s.vouchers))  STATE.vouchers = s.vouchers.filter(v=>isPlainObj(v) && typeof v.code === 'string');
    if(s.activeVoucher === null || (isPlainObj(s.activeVoucher) && typeof s.activeVoucher.code === 'string')) STATE.activeVoucher = s.activeVoucher;
    if(isPlainObj(s.autoVouchers)) Object.assign(STATE.autoVouchers, s.autoVouchers);
    if(s.businessLead === null || isPlainObj(s.businessLead)) STATE.businessLead = s.businessLead;
    if(typeof s.tableNumber === 'number' || s.tableNumber === null) STATE.tableNumber = s.tableNumber;
    if(isPlainObj(s.loyalty)) Object.assign(STATE.loyalty, s.loyalty);
    if(!(isFinite(+STATE.loyalty.points))) STATE.loyalty.points = 0;
    if(isPlainObj(s.referral)) Object.assign(STATE.referral, s.referral);
    ['redeemed','friendsUsed'].forEach(k=>{ if(!Array.isArray(STATE.referral[k])) STATE.referral[k] = []; });
    if(isPlainObj(s.challenges)) Object.assign(STATE.challenges, s.challenges);
    migrateChallengeClaims();
    if(isPlainObj(s.achievements)) Object.assign(STATE.achievements, s.achievements);
    STATE.achievements.unlocked = objList(STATE.achievements.unlocked) || [];
    if(Array.isArray(s.progressPhotos)) STATE.progressPhotos = s.progressPhotos.filter(p=>isPlainObj(p) && typeof p.dataUrl === 'string' && p.dataUrl.startsWith('data:image/'));
    if(isPlainObj(s.dietary)){ Object.assign(STATE.dietary, s.dietary, {allergies: {...STATE.dietary.allergies, ...(isPlainObj(s.dietary.allergies) ? s.dietary.allergies : {})}}); }
    if(Array.isArray(s.savedCombos)) STATE.savedCombos = s.savedCombos.filter(c=>isPlainObj(c) && Array.isArray(c.items)).map(c=>({...c, name:String(c.name||''), items:objList(c.items)}));
    if(isPlainObj(s.goals)) Object.assign(STATE.goals, s.goals);
    if(isPlainObj(s.group) && Array.isArray(s.group.people)) STATE.group = s.group;
    if(isPlainObj(s.groupJoin)) STATE.groupJoin = s.groupJoin;
    // il motore di calcolo è cambiato (NASEM 2023, macro su peso di riferimento): chi non ha macro manuali li ricalcola una volta
    if(s.engineVersion !== ENGINE_VERSION && STATE.nutriProfile && !STATE.profile.manual) applyComputedTargets();
}

/* Tutte le chiavi dell'app sul dispositivo (dati, schermata da riprendere, salvataggio online, copia di un salvataggio rovinato) */
const STATE_ALL_KEYS = () => [STORAGE_KEY, STORAGE_KEY + '_backup', NAV_RESUME_KEY, CLOUD_SESSION_KEY, CLOUD_SYNC_KEY, CLOUD_DIRTY_KEY, CLOUD_PAY_KEY];

/* Notifiche educative (js/features/curiosity.js): frequenza, fascia oraria (minuti, 9-21) e categorie (null = tutte) */
const EDU_NOTIF_DEFAULTS = {educational:false, eduFrequency:'daily', eduStart:540, eduEnd:1260, eduCategories:null};
function eduNotifClean(n){
  const ok = ['3w', '5w', 'daily'].includes(n.eduFrequency) && Number.isInteger(n.eduStart) && Number.isInteger(n.eduEnd)
    && n.eduStart >= 360 && n.eduEnd <= 1380 && n.eduEnd - n.eduStart >= 120;
  const cats = Array.isArray(n.eduCategories) ? n.eduCategories.filter(c=> typeof c === 'string').slice(0, 50) : null;
  return {...n, educational: n.educational === true, ...(ok ? {} : {eduFrequency:'daily', eduStart:540, eduEnd:1260}), eduCategories: cats && cats.length ? cats : null};
}

function resetState(){
  stateDirty = false;   // un salvataggio in sospeso non deve riscrivere i dati appena cancellati
  stateStale = true;    // e nemmeno un ridisegno prima del ricaricamento
  STATE_ALL_KEYS().forEach(k=>{ try{ localStorage.removeItem(k); }catch{} });
  if(typeof navHistoryStop === 'function') navHistoryStop();   // la finestra di conferma che si chiude non deve annullare il ricaricamento
  location.reload();
}

