let uidCounter = 1;

/* Dopo il caricamento dello stato salvato il contatore va portato sopra il
   massimo id già in uso (parte numerica finale di 'u12', 'd7', 'combo3', 'c5',
   'ph2'): ripartendo da 1 le nuove voci avrebbero lo stesso uid di quelle
   salvate e «Rimuovi» ne toglierebbe più di una. Gli id non numerici si ignorano. */
function syncUidCounter(){
  let max = 0;
  const note = id=>{
    const m = /(\d+)$/.exec(String(id));
    const n = m ? parseInt(m[1], 10) : 0;
    if(Number.isSafeInteger(n) && n > max) max = n;
  };
  const each = (list, key)=>{ if(Array.isArray(list)) list.forEach(o=>{ if(o) note(o[key]); }); };
  each(STATE.cart, 'uid');
  Object.values(STATE.diary || {}).forEach(day=>{
    if(day) MEAL_SLOTS.forEach(sl=>each(day[sl.key], 'uid'));
  });
  each(STATE.savedCombos, 'id');
  each(STATE.progressPhotos, 'id');
  [STATE.consult, STATE.consultTrain].forEach(b=>{ if(b) note(b.id); });   // prenotazioni: 'c'+n
  uidCounter = Math.max(uidCounter, max + 1);
}

