function foodIcon(food, size){
  const cat = food.cat==='meal' ? 'meal' : food.cat;
  const colorVar = {carb:'var(--carb)', protein:'var(--protein)', fat:'var(--fat)', meal:'var(--accent)', veg:'var(--veg)', fruit:'var(--fruit)', sauce:'var(--sauce)', drink:'var(--carb)', dessert:'var(--protein)', supplement:'var(--supplement)'}[cat] || 'var(--ink)';
  return foodIconSvg(food.id, colorVar, size);
}

/* Etichetta di categoria in alto a sinistra sulla scheda (solo se la categoria ha un nome tradotto) */
const CAT_LABELS_IT = {carb:'Carboidrati', protein:'Proteine', fat:'Grassi', veg:'Verdura', fruit:'Frutta', sauce:'Salse', drink:'Bevande', meal:'Piatti pronti', supplement:'Integratori', dessert:'Dolci'};

function catLabel(cat){ return CAT_LABELS_IT[cat] ? uiT('cat.'+cat, CAT_LABELS_IT[cat]) : ''; }

function heroCatChip(cat){
  if(cat === 'supplement') return `<span class="hero-cat"><i></i>Elevate Nutrition</span>`;   // integratori: marchio proprietario
  return CAT_LABELS_IT[cat] ? `<span class="hero-cat"><i></i>${catLabel(cat)}</span>` : '';
}

function flameIconSvg(){
  return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 2c1 3-2 4-2 7a4 4 0 0 0 8 0c0-1-.5-2-1-2 1 4-1 5-2 5-1.5 0-2-1.2-2-2.5C13 7 14 5 12 2Z"/><path d="M7 14a5 5 0 0 0 10 0c0-2-1-3-1.5-4"/></svg>`;
}

/* Cuore "grande" della scheda alimento: bottone rotondo a sfondo bianco,
   stessa convenzione di colore usata per i cuori piccoli nel resto
   dell'app (ink quando non è nei preferiti, protein quando lo è) — path
   perfettamente simmetrico, nessun colore inventato. */
function heartLgIconSvg(active){
  const path = 'M12 21.35l-1.45-1.32C5.4 15.36 2 12.28 2 8.5 2 5.42 4.42 3 7.5 3c1.74 0 3.41.81 4.5 2.09C13.09 3.81 14.76 3 16.5 3 19.58 3 22 5.42 22 8.5c0 3.78-3.4 6.86-8.55 11.54L12 21.35z';
  return active
    ? `<svg viewBox="0 0 24 24" fill="currentColor" stroke="currentColor" stroke-width="1" stroke-linejoin="round"><path d="${path}"/></svg>`
    : `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="${path}"/></svg>`;
}

