    let t = `<path d="${shape}" fill="rgba(70,60,40,.22)" transform="translate(1.6 2.6)"/><path d="${shape}" fill="${o.fill}" stroke="${o.edge}" stroke-width=".9"/>`;
    for(let i = 0; i < 6; i++) t += `<path d="M${-20 + i * 8} -8Q${-16 + i * 8} 0 ${-20 + i * 8} 8" stroke="${o.edge}" stroke-width=".7" fill="none" opacity=".55"/>`;
