         + artEll(x - r * .3, y - r * .35, r * .38, r * .2, '#fff', -25, ' opacity=".9"') + artEll(x + r * .25, y + r * .3, r * .4, r * .18, '#EFEBDD', 20, ' opacity=".8"');
