const artCache = {};

/* Il disegno di un alimento (stringa SVG), o vuoto se non c'è: la scena è sempre la stessa, quindi si calcola una volta sola.
   Se l'alimento ha varianti (la cottura delle uova) e per la variante scelta c'è un disegno («id/variante») si usa quello. */
function foodArtSvg(id, opt){
  const key = opt && ART_OF[id + '/' + opt] ? id + '/' + opt : id;
  const spec = ART_OF[key];
  if(!spec) return '';
  if(!artCache[key]) artCache[key] = `<svg class="fp-art" viewBox="0 0 ${ART_SIZE} ${ART_SIZE}" aria-hidden="true">${ART_SCENES[spec[0]](spec[1], artRng(artSeed(key)))}</svg>`;
  return artCache[key];
}

/* Anteprima del prodotto nelle schede: la foto se c'è, altrimenti il disegno, altrimenti l'icona */
function foodPreview(food, chosen){
  const opt = chosen || defaultOptFor(food);   // senza una scelta si mostra la variante predefinita
  const photo = foodPhoto(food.id, opt);
  if(photo) return `<img class="fp-img" src="${photoThumb(photo)}" alt="" draggable="false" data-fallback="card" data-food="${food.id}"${opt ? ` data-opt="${opt}"` : ''}>`;
  return foodArtSvg(food.id, opt) || `<span class="fp-icon">${foodIcon(food, 56)}</span>`;
}

/* Foto che non si carica: al suo posto il disegno (delegato, senza onerror inline) */
document.addEventListener('error', e=>{
  const img = e.target;
  if(!img || img.tagName !== 'IMG') return;
  // senza rete e mai vista prima: niente icona dell'immagine rotta (le schede e il dettaglio mettono il disegno)
  if(!img.dataset.fallback){ img.style.visibility = 'hidden'; return; }
  if(img.dataset.fallback !== 'card') return;
  const food = findFood(img.dataset.food);
  if(food) img.outerHTML = foodArtSvg(food.id, img.dataset.opt) || `<span class="fp-icon">${foodIcon(food, 56)}</span>`;
}, true);

/* Modali di conferma/inserimento e toast */

/* ---------------- MODALE INTERNO ----------------
   confirm()/prompt() del browser possono essere bloccati quando l'app gira
   dentro un frame incorporato: uso un modale interno, sempre affidabile. */
let modalOnConfirm = null;

/* Sul computer Esc chiude la finestra aperta, come toccare fuori (quelle obbligatorie, senza chiusura, restano) */
document.addEventListener('keydown', e=>{
  if(e.key !== 'Escape') return;
  const close = document.querySelector('#modal-root [data-action="modal-close"]');
  if(close){ e.preventDefault(); close.click(); }
});

function showConfirm(title, message, confirmLabel, onConfirm){
  modalOnConfirm = onConfirm;
  const el = document.getElementById('modal-root');
  el.innerHTML = `
    <div class="modal-backdrop" data-action="modal-close">
      <div class="modal-card" data-stop="1">
        <div class="modal-title">${title}</div>
        <div class="modal-msg">${message}</div>
        <div class="modal-actions">
          <button class="btn btn-ghost" data-action="modal-close">${uiT('common.cancel','Annulla')}</button>
          <button class="btn btn-primary" style="flex:1;" data-action="modal-confirm">${confirmLabel}</button>
        </div>
      </div>
    </div>`;
}

/* allowZero: per i valori che si possono riportare a zero (i passi di oggi) */
function showPromptNumber(title, message, initial, unit, onConfirm, limitKey, allowZero){
  modalOnConfirm = ()=>{
    const v = parseFloat((document.getElementById('modal-input').value||'').replace(',','.'));
    if(isNaN(v) || v<0 || (v===0 && !allowZero) || (limitKey && !inLimits(v, limitKey))){ toast(uiT('toast.invalidValue','Valore non valido')); return false; }
    onConfirm(v);
    return true;
  };
  const el = document.getElementById('modal-root');
  el.innerHTML = `
    <div class="modal-backdrop" data-action="modal-close">
      <div class="modal-card" data-stop="1">
        <div class="modal-title">${title}</div>
        <div class="modal-msg">${message}</div>
        <div style="display:flex;align-items:center;gap:10px;margin-top:14px;">
          <input class="text-input" id="modal-input" type="text" inputmode="decimal" value="${initial}" style="flex:1;">
          <span style="color:var(--muted);font-size:13px;font-weight:700;">${unit}</span>
        </div>
        <div class="modal-actions">
          <button class="btn btn-ghost" data-action="modal-close">${uiT('common.cancel','Annulla')}</button>
          <button class="btn btn-primary" style="flex:1;" data-action="modal-confirm">${uiT('common.save','Salva')}</button>
        </div>
      </div>
    </div>`;
  setTimeout(()=>{ const i=document.getElementById('modal-input'); if(i){ i.focus(); i.select(); } },0);
}

function showPromptText(title, message, initial, placeholder, onConfirm){
  modalOnConfirm = ()=>{
    const v = (document.getElementById('modal-input').value||'').trim();
    if(!v){ toast(uiT('toast.invalidValue','Valore non valido')); return false; }
    onConfirm(v);
    return true;
  };
  const el = document.getElementById('modal-root');
  el.innerHTML = `
    <div class="modal-backdrop" data-action="modal-close">
      <div class="modal-card" data-stop="1">
        <div class="modal-title">${title}</div>
        <div class="modal-msg">${message}</div>
        <div style="margin-top:14px;">
          <input class="text-input" id="modal-input" type="text" value="${esc(initial)}" placeholder="${esc(placeholder)}" style="width:100%;" maxlength="40">
        </div>
        <div class="modal-actions">
          <button class="btn btn-ghost" data-action="modal-close">${uiT('common.cancel','Annulla')}</button>
          <button class="btn btn-primary" style="flex:1;" data-action="modal-confirm">${uiT('common.save','Salva')}</button>
        </div>
      </div>
    </div>`;
  setTimeout(()=>{ const i=document.getElementById('modal-input'); if(i){ i.focus(); i.select(); } },0);
}

/* Finestre accessibili, per tutte (conferme, prompt, foto, condivisione, avvertenza): si annunciano come finestra
   (role=dialog, aria-modal, titolo), il focus entra nella finestra e Tab resta dentro; chiusa la finestra il focus torna
   dove era. Un solo osservatore su #modal-root invece di ripeterlo in ogni finestra. */
let modalReturnFocus = null;
function modalA11y(){
  const root = document.getElementById('modal-root');
  const card = root && root.querySelector('.modal-card');
  if(!card){
    const back = modalReturnFocus;
    modalReturnFocus = null;
    if(back && back.isConnected && document.activeElement && (document.activeElement === document.body || !document.activeElement.isConnected)) back.focus({preventScroll:true});
    return;
  }
  if(card.dataset.a11y) return;
  card.dataset.a11y = '1';
  card.setAttribute('role', 'dialog');
  card.setAttribute('aria-modal', 'true');
  const title = card.querySelector('.modal-title');
  if(title){ title.id = title.id || 'modal-title'; card.setAttribute('aria-labelledby', title.id); }
  if(!modalReturnFocus && document.activeElement && document.activeElement !== document.body && !root.contains(document.activeElement)) modalReturnFocus = document.activeElement;
  // il primo campo (i prompt lo selezionano già da soli) oppure la finestra stessa
  if(!card.contains(document.activeElement)){
    const first = card.querySelector('input:not([type=hidden]):not([disabled]), textarea');
    if(first) first.focus({preventScroll:true});
    else { card.tabIndex = -1; card.focus({preventScroll:true}); }
  }
}
if(typeof document !== 'undefined' && window.MutationObserver){
  const root = document.getElementById('modal-root');
  if(root) new MutationObserver(modalA11y).observe(root, {childList:true});
}
document.addEventListener('keydown', e=>{
  if(e.key !== 'Tab') return;
  const card = document.querySelector('#modal-root .modal-card');
  if(!card) return;
  const items = [...card.querySelectorAll('button:not([disabled]), input:not([disabled]):not([type=hidden]), textarea, select, a[href], [tabindex]:not([tabindex="-1"])')].filter(el=> el.offsetParent !== null);
  if(!items.length){ e.preventDefault(); return; }
  const first = items[0], last = items[items.length - 1];
  if(e.shiftKey && (document.activeElement === first || !card.contains(document.activeElement))){ e.preventDefault(); last.focus(); }
  else if(!e.shiftKey && (document.activeElement === last || !card.contains(document.activeElement))){ e.preventDefault(); first.focus(); }
});

function closeModal(){
  modalOnConfirm = null;
  selfieStop();
  photoEd = null;   // l'editor della foto (la sua immagine fino a 1600 px) non resta in memoria a finestra chiusa
  const el = document.getElementById('modal-root');
  if(el) el.innerHTML = '';
}

function toast(msg){
  const t = document.getElementById('toast');
  t.innerHTML = iconSvg('check').replace('<svg','<svg style="width:14px;height:14px"') + '<span>'+esc(msg)+'</span>';
  t.classList.add('show');
  clearTimeout(toast._t);
  toast._t = setTimeout(()=>t.classList.remove('show'), 1800);
}

/* Azioni dei pulsanti (data-action) */
defineActions({
  'modal-close'(el, e){
    // clic sullo sfondo: chiude. Clic dentro la card: ignora.
    if(el.classList.contains('modal-backdrop') && e.target.closest('[data-stop]')) return;
    closeModal();
  },
  'modal-confirm'(){
    const fn = modalOnConfirm;
    if(fn){ const ok = fn(); if(ok === false) return; }
    closeModal();
  },
});

/* Rete: indicazione discreta quando manca, controllo prima delle funzioni che ne hanno bisogno */

/* Senza rete l'app funziona quasi tutta (menu, carrello, diario, profilo stanno sul telefono). Servono
   internet: accesso con Google/Apple, pagamento online, ricerca di un prodotto dal codice a barre, indirizzo
   dalla posizione, mappa del rider. Lì un messaggio chiaro invece di un errore generico. */
function netOffline(){ return navigator.onLine === false; }

function netRequire(){
  if(!netOffline()) return true;
  toast(uiT('net.required','Serve una connessione a internet: riprova quando torni online'));
  return false;
}

/* Pillola «Sei offline» in cima, sopra il logo: compare da sola quando la rete cade e sparisce quando
   torna. Non si tocca e non copre i tocchi (pointer-events: none). */
function netRenderPill(){
  let pill = document.getElementById('net-pill');
  if(!netOffline()){ if(pill) pill.remove(); return; }
  if(!pill){
    pill = document.createElement('div');
    pill.id = 'net-pill';
    pill.className = 'net-pill';
    pill.setAttribute('role', 'status');
    document.body.appendChild(pill);
  }
  pill.innerHTML = `<span class="net-dot"></span>${uiT('net.offline','Sei offline')}`;
}

function netStart(){
  if(!window.addEventListener) return;
  window.addEventListener('offline', netRenderPill);
  window.addEventListener('online', ()=>{
    netRenderPill();
    // tornata la rete: la schermata dell'ordine riprova a mostrare la mappa del rider
    if(STATE.auth.loggedIn && current().view === 'confirm') render();
  });
  netRenderPill();
}

/* Interruttori on/off: markup e animazione quando cambiano stato */

/* L'interruttore sta dentro un pulsante con data-action che ne cambia lo stato e ridisegna la schermata.
   Il ridisegno crea un interruttore nuovo, già nello stato finale: una transizione CSS non avrebbe niente da
   animare. Per questo setViewHtml() confronta gli interruttori prima e dopo il ridisegno causato da un clic
   e a quelli che hanno cambiato stato aggiunge .ts-turn-on / .ts-turn-off, che fanno partire l'animazione
   (stili in styles.css). Vale anche per un interruttore che cambia per effetto di un altro (giorno di
   allenamento e giorno libero si escludono a vicenda: uno si accende mentre l'altro si spegne). */
function toggleSwitchHtml(on){
  return `<span class="toggle-switch ${on?'on':''}"><span class="ts-fill"></span><span class="ts-knob"></span></span>`;
}

/* Il clic su un pulsante che contiene un interruttore apre una «finestra» che dura quanto l'evento; dentro
   la finestra il primo stato degli interruttori è quello di partenza, anche se il gestore ridisegna più volte.
   Cambi di stato senza clic (altro giorno del diario, altro passo dell'iscrizione) non animano. */
let toggleTick = null;

document.addEventListener('click', e=>{
  const host = e.target.closest && e.target.closest('[data-action]');
  if(!host || !host.querySelector('.toggle-switch')) return;
  const tick = toggleTick = {before:null};
  setTimeout(()=>{ if(toggleTick === tick) toggleTick = null; }, 0);
}, true);   // in fase di cattura: prima del gestore delle azioni

/* Stato di ogni interruttore, riconosciuto dal pulsante che lo contiene (azione + data-*) e dalla posizione tra quelli uguali */
function toggleStates(root){
  const seen = {}, states = new Map();
  root.querySelectorAll('.toggle-switch').forEach(el=>{
    const host = el.closest('[data-action]');
    const id = host ? host.dataset.action + '|' + Object.keys(host.dataset).sort().map(k=>k+'='+host.dataset[k]).join('&') : '';
    seen[id] = (seen[id] || 0) + 1;
    states.set(id + '#' + seen[id], {el, on: el.classList.contains('on')});
  });
  return states;
}

/* Sostituisce il contenuto della schermata; se il ridisegno è la conseguenza di un clic su un interruttore,
   fa partire l'animazione di quelli che hanno cambiato stato. viewKey (facoltativo) è il nome della vista
   corrente: se diverso dall'ultima renderizzata, la schermata nuova entra con una lieve dissolvenza. */
function setViewHtml(html, viewKey){
  const view = document.getElementById('view');
  if(!toggleTick){ view.innerHTML = html; animateViewChange(view, viewKey); return; }
  if(!toggleTick.before) toggleTick.before = toggleStates(view);
  view.innerHTML = html;
  toggleStates(view).forEach((now, key)=>{
    const was = toggleTick.before.get(key);
    if(was && was.on !== now.on) now.el.classList.add(now.on ? 'ts-turn-on' : 'ts-turn-off');
  });
  animateViewChange(view, viewKey);
}

/* Dissolvenza leggera SOLO quando cambia davvero la schermata, non ad ogni ridisegno sullo stesso
   schermo (grammature/topping/opzioni in detail.js passano di qui molto spesso — con la stessa
   viewKey della volta prima, quindi restano senza animazione: un fade ad ogni tocco non sarebbe
   "sobrio", lo è solo quando l'utente vede davvero una schermata diversa). */
let lastViewKey = null;
let viewJustEntered = true;   // letto da initFoodRings (core/food-ring.js): anima anelli/numeri solo entrando in una schermata nuova
function animateViewChange(view, viewKey){
  const changed = viewKey !== undefined && viewKey !== lastViewKey;
  lastViewKey = viewKey;
  viewJustEntered = changed;
  // come nelle app: entrando in una schermata (un piatto, il carrello...) arriva da destra, con «indietro» da
  // sinistra; tab, categorie e il resto con la dissolvenza leggera di sempre (navDirection: core/navigation.js)
  const dir = navDirection;
  navDirection = null;
  if(!changed || viewTransitionRunning) return;
  if(window.matchMedia && matchMedia('(prefers-reduced-motion: reduce)').matches) return;
  view.classList.remove('view-enter', 'view-push', 'view-pop');
  void view.offsetWidth;   // forza il reflow: senza, il browser fonde remove+add e non c'è nulla da (ri)animare
  view.classList.add(dir === 'forward' ? 'view-push' : dir === 'back' ? 'view-pop' : 'view-enter');
}

/* Navigazione tra schermate */

function navigateTo(view, params={}){
  // i dolci hanno la loro scheda (gusto, coppetta, pezzi, topping): ci si arriva anche dalle card di
  // ricerca, preferiti e Home, che aprono 'detail' — lì il topping non finiva nel carrello
  if(view === 'detail' && params.id && (findFood(params.id) || {}).cat === 'dessert') view = 'dessert';
  if(view === 'detail' && params.id && (findFood(params.id) || {}).jar) view = 'jar';   // proteine in barattolo: gusto e formato
  if(current()) navScroll.set(current(), window.scrollY || 0);
  navDirection = 'forward';
  STATE.stack.push({view, ...params});
  render();
  window.scrollTo({top:0});
}

/* keepScroll: per le schermate che restano le stesse e cambia solo un parametro (una
   grammatura, un topping, un'opzione, un campo di ricerca mentre si scrive...) non si deve
   saltare in cima — l'utente sta guardando proprio il controllo che ha appena toccato, più in
   basso. Resta false (si torna in cima) per i cambi che sono un vero passaggio di sezione
   (cambio di categoria del menu, cambio di fascia oraria degli integratori). */
function replaceView(view, params={}, keepScroll=false){
  STATE.stack[STATE.stack.length-1] = {view, ...params};
  render();
  if(!keepScroll) window.scrollTo({top:0});
}

/* Dopo un'aggiunta riporto l'utente nella categoria da cui è arrivato. Se è arrivato da Home, ricerca o
   preferiti torna lì, non all'ultima categoria del menu visitata (magari molto prima). */
function backToMenu(){
  const m = STATE.lastMenu;
  const prev = STATE.stack[STATE.stack.length-2];
  if(!m || (prev && !['menu','family','supplements'].includes(prev.view))){ goBack(); return; }
  navDirection = 'back';   // si torna alla categoria: la schermata arriva da sinistra (ma dall'alto, vedi render)
  if(m.view==='family'){
    // sotto la famiglia rimetto il menu della sua categoria: così "indietro" ha dove tornare
    const fam = familyById(m.fam);
    STATE.stack = [{view:'menu', cat: fam ? fam.cat : 'carb'}, {...m}];
  } else {
    STATE.stack = [{...m}];
  }
  render();
}

/* Indietro (freccia in alto, tasto o gesto del telefono): si torna alla schermata di prima nel punto in cui la si
   era lasciata, come nelle app. Schermate nuove, cambi di tab e il ritorno dopo un'aggiunta al carrello partono
   invece dall'alto. navScroll: la posizione di ogni schermata lasciata andando avanti (solo in memoria). */
const navScroll = new WeakMap();
/* Verso della prossima schermata, per l'animazione (letto e azzerato da animateViewChange, core/toggles.js) */
let navDirection = null;
function goBack(){
  if(STATE.stack.length>1){ STATE.stack.pop(); navDirection = 'back'; }
  render();
  window.scrollTo(0, navScroll.get(current()) || 0);
}

function goToTab(view){
  STATE.stack = [{view}];
  render();
  window.scrollTo({top:0});
}

/* Dalla card di un alimento alla sua scheda: la foto "vola" nel cerchio in cima alla scheda (View Transitions
   del browser). Dove non ci sono, o con "riduci movimento", si entra con la dissolvenza di sempre. */
let viewTransitionRunning = false;   // letto da animateViewChange: durante il volo niente dissolvenza in più
function navigateWithHero(fromEl, view, params){
  const reduce = window.matchMedia && matchMedia('(prefers-reduced-motion: reduce)').matches;
  if(!document.startViewTransition || reduce){ navigateTo(view, params); return; }
  fromEl.style.viewTransitionName = 'food-hero';
  const t = document.startViewTransition(()=>{
    fromEl.style.viewTransitionName = '';
    viewTransitionRunning = true;
    navigateTo(view, params);
    viewTransitionRunning = false;
    const hero = document.querySelector('.hero-photo-circle');
    if(hero) hero.style.viewTransitionName = 'food-hero';
  });
  // la transizione può essere interrotta (due tocchi rapidi, pagina in background): la navigazione avviene comunque,
  // l'animazione no — senza questi catch resterebbe un errore non gestito
  t.ready.catch(()=>{});
  t.finished.catch(()=>{}).then(()=>{ const hero = document.querySelector('.hero-photo-circle'); if(hero) hero.style.viewTransitionName = ''; });
}

function current(){ return STATE.stack[STATE.stack.length-1]; }

/* ---- Tasto e gesto «indietro» del telefono e del browser ----
   L'app è una pagina sola: senza questo, «indietro» su Android chiudeva l'app (o usciva dal sito) anche
   da una scheda prodotto. Finché dentro l'app c'è dove tornare (una schermata precedente, una tab diversa
   dalla Home, una finestra aperta) nella cronologia del browser resta una voce in più: «indietro» la
   consuma e l'app fa il suo passo indietro. Dalla Home la voce non c'è e «indietro» esce, come un'app vera.
   Solo nella pagina principale (nell'anteprima dell'artefatto, dentro claude.ai, si lascia stare la
   cronologia della pagina che la contiene). */
const NAV_HISTORY = {on:false, armed:false, pending:0, timer:0};

function navCanGoBack(){
  const modal = document.getElementById('modal-root');
  if(modal && modal.firstElementChild) return true;
  if(!STATE.auth.loggedIn || !STATE.auth.registered) return false;
  return STATE.stack.length > 1 || current().view !== 'home';
}

/* Allinea la voce in più allo stato dell'app (dopo ogni ridisegno e quando si apre o chiude una finestra) */
function navSyncHistory(){
  // un «indietro» chiesto dall'app (sotto) non è ancora arrivato: history.back() è asincrono, e aggiungere una voce
  // prima che arrivi le faceva accumulare fino a far uscire dall'app con tocchi rapidi tra Home e un'altra schermata.
  // Ci si allinea appena arriva (navOnPopState) o, se non arriva, dopo poco.
  if(!NAV_HISTORY.on || NAV_HISTORY.pending) return;
  const want = navCanGoBack();
  if(want && !NAV_HISTORY.armed){
    NAV_HISTORY.armed = true;
    history.pushState({macros:'back'}, '');
    navManualScroll();
  } else if(!want && NAV_HISTORY.armed){
    // tornati alla Home da soli (tab, logo): la voce non serve più, se no il primo «indietro» non farebbe nulla
    NAV_HISTORY.armed = false;
    NAV_HISTORY.pending++;
    history.back();
    clearTimeout(NAV_HISTORY.timer);
    NAV_HISTORY.timer = setTimeout(()=>{ if(NAV_HISTORY.pending){ NAV_HISTORY.pending = 0; navSyncHistory(); } }, 1500);
  }
}

/* La posizione nella pagina la rimette l'app (goBack): quella del browser la riporterebbe in cima. Vale per
   ogni voce della cronologia, quindi va ridetta per ogni voce nuova e per quella a cui si torna */
function navManualScroll(){ if('scrollRestoration' in history) history.scrollRestoration = 'manual'; }

function navOnPopState(){
  navManualScroll();
  if(NAV_HISTORY.pending){ NAV_HISTORY.pending--; navSyncHistory(); return; }
  NAV_HISTORY.armed = false;
  const modal = document.getElementById('modal-root');
  if(modal && modal.firstElementChild){
    // una finestra aperta si chiude come toccando fuori; quelle obbligatorie (avvertenza) restano
    const close = modal.querySelector('[data-action="modal-close"]');
    if(close) close.click();
    navSyncHistory();
    return;
  }
  if(!STATE.auth.loggedIn || !STATE.auth.registered) return;
  if(STATE.stack.length > 1) goBack();
  else if(current().view !== 'home') goToTab('home');
  navSyncHistory();
}

/* ---- Riapertura ----
   Se il telefono chiude l'app mentre è in background (si passa a WhatsApp, si blocca lo schermo) e la si riapre
   entro 30 minuti, si riparte dalla schermata in cui si era invece che dalla Home. La posizione si salva solo
   quando l'app va in background; fotocamera (scansioni) esclusa: lì si riparte dalla schermata prima. */
const NAV_RESUME_KEY = 'macros_nav_v1', NAV_RESUME_MS = 30 * 60e3;
const NAV_NO_RESUME = ['diary-scan', 'table-scan'];
/* Schermate che vivono di una bozza tenuta solo in memoria (non salvata): dopo la chiusura la bozza non c'è più, quindi
   si riparte dalla schermata prima (la porzione di un prodotto scansionato, la Weekly Box in configurazione, la
   prenotazione di una consulenza). Con un abbonamento attivo le pagine della Weekly Box lavorano su quello. */
const NAV_NEEDS = {
  'diary-portion': c=> !c.scanned || !!STATE.scanResult,
  'sub-plan': ()=> !!STATE.subDraft, 'sub-builder': ()=> !!STATE.subDraft,
  'sub-pick': ()=> !!(STATE.subscription || STATE.subDraft), 'sub-logistics': ()=> !!(STATE.subscription || STATE.subDraft),
  'meal-plan-pick': ()=> !!(STATE.subscription || STATE.subDraft), 'meal-plan-extras': ()=> !!(STATE.subscription || STATE.subDraft),
  'nutri-book': ()=> !!STATE.consultDraft,
};

function navSaveResume(){
  if(!STATE.auth.loggedIn || !STATE.auth.registered) return;
  try{ localStorage.setItem(NAV_RESUME_KEY, JSON.stringify({at:Date.now(), stack:STATE.stack})); }catch{ /* spazio esaurito: si riparte dalla Home */ }
}

function navRestoreResume(){
  if(window.top !== window) return;
  let r = null;
  try{ r = JSON.parse(localStorage.getItem(NAV_RESUME_KEY) || 'null'); localStorage.removeItem(NAV_RESUME_KEY); }catch{ return; }
  if(!r || !Array.isArray(r.stack) || !(Date.now() - r.at < NAV_RESUME_MS)) return;
  if(!STATE.auth.loggedIn || !STATE.auth.registered) return;
  const stack = r.stack.filter(x=>x && typeof x.view === 'string' && VIEW_RENDERERS[x.view]);
  const cut = stack.findIndex(x=>NAV_NO_RESUME.includes(x.view) || (NAV_NEEDS[x.view] && !NAV_NEEDS[x.view](x)));
  if(cut >= 0) stack.length = cut;
  if(stack.length) STATE.stack = stack;
}

/* Prima di ricaricare la pagina: la voce in più della cronologia non si tocca più. Chiudere una finestra subito dopo
   location.reload() (es. la conferma «Crea nuovo account») faceva partire history.back(), che annullava il ricaricamento */
function navHistoryStop(){
  NAV_HISTORY.on = false;
  clearTimeout(NAV_HISTORY.timer);
}

function navHistoryStart(){
  if(window.top !== window || !window.history || !history.pushState) return;
  NAV_HISTORY.on = true;
  navManualScroll();
  window.addEventListener('popstate', navOnPopState);
  document.addEventListener('visibilitychange', ()=>{ if(document.visibilityState === 'hidden') navSaveResume(); });
  window.addEventListener('pagehide', navSaveResume);
  const modal = document.getElementById('modal-root');
  if(modal && window.MutationObserver) new MutationObserver(()=>navSyncHistory()).observe(modal, {childList:true});
  navSyncHistory();
}

/* Azioni dei pulsanti (data-action) */
defineActions({
  'tab'(el){
    goToTab(el.dataset.view);
    // se la voce indica anche una categoria, apro il menu direttamente lì
    if(el.dataset.view==='menu' && el.dataset.cat) replaceView('menu', {cat:el.dataset.cat});
  },
  'nav'(el){
    const params = {};
    if(el.dataset.id) params.id = el.dataset.id;
    if(el.dataset.cat) params.cat = el.dataset.cat;
    if(el.dataset.slot) params.slot = el.dataset.slot;
    if(el.dataset.fam) params.fam = el.dataset.fam;
    if(el.dataset.opt) params.opt = el.dataset.opt;
    if(el.dataset.flavor) params.flavor = el.dataset.flavor;
    if(el.dataset.view==='detail' && current().buildSlot){
      params.mode = 'build';
      params.slot = current().buildSlot;
    }
    const photo = el.dataset.view === 'detail' && el.querySelector('.fp');
    if(photo) navigateWithHero(photo, el.dataset.view, params);
    else navigateTo(el.dataset.view, params);
  },
  'back'(){ goBack(); },
  'reload-app'(){ navHistoryStop(); location.reload(); },
});

/* Anello dei macro e righe dei macro */

/* ---------------- ANELLO DEI MACRO DEGLI ALIMENTI (animato) ----------------
   Solo per le schede alimento. All'apertura i tre archi (carboidrati, proteine, grassi) si disegnano
   uno dopo l'altro mentre l'anello ruota in posizione. I numeri sono «contachilometri»: ogni cifra è
   una colonna 0-9 che scorre verticalmente fino alla cifra giusta, da sinistra a destra. Quando cambi
   la quantità gli archi si adattano con una transizione morbida e solo le cifre che cambiano scorrono.
   Toccando un riquadro (carbo/proteine/grassi) l'arco corrispondente si evidenzia e al centro compare
   la sua quota di calorie. Con «riduci movimento» attivo tutto avviene senza animazioni. */
const FR_KEYS = ['c','p','f'];

function foodRingShares(p,c,f){
  const en = {c:c*4, p:p*4, f:f*9}, total = en.c+en.p+en.f;
  return {en, total, pct: k=> total>0 ? Math.round(en[k]/total*100) : 0};
}

/* Geometria degli archi: capsule separate da uno spazio fisso; un arco troppo corto per essere leggibile non si disegna */
function foodRingArcs(p,c,f,size,sw){
  const r = size/2 - sw/2 - 2, circ = 2*Math.PI*r, gapVis = 3.4;
  const {en, total} = foodRingShares(p,c,f);
  let start = 0;
  return {r, circ, arcs: FR_KEYS.map(k=>{
    const seg = (total>0 ? en[k]/total : 0) * circ, dash = seg - gapVis - sw;
    const arc = {k, dash: Math.max(dash, 0.01), off: -(start + gapVis/2 + sw/2), show: dash > 0.5};
    start += seg;
    return arc;
  })};
}

function foodRingHtml(p,c,f,kcal,opts={}){
  const size = opts.size || 88, sw = opts.sw || 9, cx = size/2;
  const g = foodRingArcs(p,c,f,size,sw);
  const names = {c:uiT('cat.carb','Carboidrati'), p:uiT('cat.protein','Proteine'), f:uiT('cat.fat','Grassi')};
  return `<svg class="fring ${opts.still?'':'fr-in'} ${opts.static?'fr-static':''}" ${opts.still?'':'data-init="1"'} ${opts.static?'':'data-action="ring-focus" data-key=""'} data-size="${size}" data-sw="${sw}"
      data-kcal="${Math.round(kcal)}" data-p="${p}" data-c="${c}" data-f="${f}" width="${size}" height="${size}" viewBox="0 0 ${size} ${size}" role="img"
      aria-label="${Math.round(kcal)} kcal · ${names.c} ${Math.round(c)} g · ${names.p} ${Math.round(p)} g · ${names.f} ${Math.round(f)} g">
    <circle class="fr-track" cx="${cx}" cy="${cx}" r="${g.r}" stroke-width="${sw}"/>
    <g class="fr-arcs">
      ${g.arcs.map((a,i)=>`<circle class="fr-arc fr-${a.k}" data-k="${a.k}" cx="${cx}" cy="${cx}" r="${g.r}" stroke-width="${sw}"
        style="--circ:${g.circ};--dash:${a.dash};--d:${i*0.13}s;stroke-dasharray:${a.dash} ${g.circ};stroke-dashoffset:${a.off};${a.show?'':'visibility:hidden;'}"/>`).join('')}
    </g>
  </svg>
  ${opts.noCenter ? '' : `<div class="fr-center" aria-hidden="true"><div class="fr-num">${fmt(kcal)}</div><div class="fr-sub">kcal</div></div>`}`;
}

/* ---- Numeri con «caduta a molla» ----
   Ogni cifra entra dall'alto con un piccolo rimbalzo e uscendo dalla sfocatura, una dopo l'altra da sinistra a destra.
   Quando il valore cambia si sostituiscono solo le cifre diverse: la vecchia scivola in basso e svanisce mentre la nuova
   cade al suo posto. Se le cifre cambiano troppo in fretta (slider trascinato) si aggiornano senza effetto, per non
   creare uno sfarfallio. Se il numero cambia forma (più o meno cifre) la fila si ricostruisce con l'ingresso completo. */
function rollSet(el, text, o={}){
  text = String(text);
  const chars = [...text], sig = chars.map(ch=> /\d/.test(ch) ? '#' : ch).join('');
  el.setAttribute('aria-label', text);
  const delay = o.delay || 0;
  if(el._rnSig !== sig){
    el.innerHTML = chars.map((ch,i)=> /\d/.test(ch)
      ? (o.still ? `<span class="pd">${ch}</span>` : `<span class="pd pd-in" style="animation-delay:${delay + i*75}ms">${ch}</span>`)
      : `<span class="pc">${ch===' ' ? '&nbsp;' : ch}</span>`).join('');
    el._rnSig = sig; el._rnTxt = text;
    return;
  }
  const prev = [...(el._rnTxt || '')];
  el._rnTxt = text;
  const now = performance.now(), fast = el._rnAt && now - el._rnAt < 90;
  el._rnAt = now;
  chars.forEach((ch,i)=>{
    if(!/\d/.test(ch) || prev[i] === ch) return;
    const n = el.children[i], old = n.textContent;
    n.classList.remove('pd-in', 'pd-swap');
    n.style.animationDelay = '';
    n.textContent = ch;                       // toglie anche l'eventuale cifra fantasma precedente
    if(fast) return;
    const ghost = document.createElement('span');
    ghost.className = 'pd-old'; ghost.textContent = old;
    ghost.addEventListener('animationend', ()=> ghost.remove());
    n.appendChild(ghost);
    void n.offsetWidth;
    n.style.animationDelay = (i*40) + 'ms';
    n.classList.add('pd-swap');
  });
}

/* Dopo ogni render: prepara anelli e numeri appena comparsi. L'animazione d'ingresso (anello che
   ruota e si disegna, cifre che cadono) parte SOLO quando si è appena entrati in una schermata
   diversa (viewJustEntered, impostato da animateViewChange in core/toggles.js): se il ridisegno
   avviene sulla stessa schermata — «Trova il mio pasto», un topping scelto, l'acqua aggiunta… —
   anelli e numeri compaiono già fermi, altrimenti rifarebbero l'ingresso a ogni tocco. */
function initFoodRings(){
  const animate = typeof viewJustEntered === 'undefined' || viewJustEntered;
  document.querySelectorAll('.fring[data-init]').forEach(svg=>{
    delete svg.dataset.init;
    if(!animate) svg.classList.remove('fr-in');
    const num = svg.parentNode.querySelector('.fr-num');
    if(num) rollSet(num, fmt(+svg.dataset.kcal), animate ? {delay:250} : {still:true});
  });
  document.querySelectorAll('[data-count]').forEach(el=>{
    if(el._rnSig!==undefined) return;
    const dec = +el.dataset.dec||0, v = +el.dataset.count;
    rollSet(el, (dec ? fmt(v,dec) : fmt(Math.round(v))) + (el.dataset.suffix||''), animate ? {delay:250} : {still:true});
  });
}

function foodRingRefreshCenter(svg){
  const box = svg.parentNode, num = box.querySelector('.fr-num'), sub = box.querySelector('.fr-sub'), k = svg.dataset.focus;
  if(!num) return;   // anello senza numero al centro (Match)
  const p = +svg.dataset.p, c = +svg.dataset.c, f = +svg.dataset.f;
  if(k){
    const names = {c:uiT('cat.carb','Carboidrati'), p:uiT('cat.protein','Proteine'), f:uiT('cat.fat','Grassi')};
    rollSet(num, foodRingShares(p,c,f).pct(k)+'%');
    sub.textContent = lcT(names[k]);
  } else {
    sub.textContent = 'kcal';
    rollSet(num, fmt(+svg.dataset.kcal));
  }
}

/* Nuova quantità: archi e cifre si adattano senza ridisegnare l'anello */
function updateFoodRing(n, sel){
  const svg = document.querySelector(sel || '#n-ring .fring');
  if(!svg) return;
  const g = foodRingArcs(n.p, n.c, n.f, +svg.dataset.size, +svg.dataset.sw);
  g.arcs.forEach(a=>{
    const el = svg.querySelector('.fr-'+a.k);
    el.style.strokeDasharray = a.dash+' '+g.circ; el.style.strokeDashoffset = a.off; el.style.visibility = a.show ? '' : 'hidden';
  });
  Object.assign(svg.dataset, {kcal:Math.round(n.kcal), p:n.p, c:n.c, f:n.f});
  foodRingRefreshCenter(svg);
}

function foodNutriCardHtml(n){
  const stat = (k, label, val, id)=>`<button class="nutri-stat ${k}" data-action="ring-focus" data-key="${k}" aria-pressed="false">
        <div class="val" id="${id}" data-count="${val}" data-dec="1" data-suffix=" g">${fmt(val,1)} g</div><div class="lbl">${label}</div></button>`;
  return `<div class="nutri-card">
      <div class="nutri-stats">
        <button class="nutri-stat kcal on" data-action="ring-focus" data-key="" aria-pressed="true">
          <div class="val" id="n-kcal" data-count="${Math.round(n.kcal)}" data-dec="0">${fmt(n.kcal)}</div><div class="lbl"><span class="ns-ic">${flameIconSvg()}</span>${uiT('macro.kcal','Calorie')}</div></button>
        ${stat('c', uiT('cat.carb','Carboidrati'), n.c, 'n-c')}
        ${stat('p', uiT('cat.protein','Proteine'), n.p, 'n-p')}
        ${stat('f', uiT('cat.fat','Grassi'), n.f, 'n-f')}
      </div>
      <div class="ring-wrap" id="n-ring">${foodRingHtml(n.p, n.c, n.f, n.kcal)}</div>
    </div>`;
}

/* Indicatore di percentuale (corrispondenza del Match) nello STESSO stile del ring dei macro:
   stessa traccia, stesso arco a estremità arrotondate con ombra colorata, numero al centro. */
function pctRingHtml(pct, size=46, sw=5){
  const cx = size/2, r = size/2 - sw/2 - 2, circ = 2*Math.PI*r;
  const dash = Math.max(0.01, Math.min(100, pct)/100 * circ);
  return `<div class="ring-wrap pct-ring" style="width:${size}px;height:${size}px" role="img" aria-label="${pct}% ${uiT('match.corr','di corrispondenza')}">
    <svg class="fring fr-static" width="${size}" height="${size}" viewBox="0 0 ${size} ${size}" aria-hidden="true">
      <circle class="fr-track" cx="${cx}" cy="${cx}" r="${r}" stroke-width="${sw}"/>
      <g class="fr-arcs"><circle class="fr-arc fr-pct" cx="${cx}" cy="${cx}" r="${r}" stroke-width="${sw}" style="stroke-dasharray:${dash} ${circ}"/></g>
    </svg>
    <div class="fr-center"><div class="fr-num">${pct}</div></div>
  </div>`;
}

/* Quanto un macro si discosta dall'obiettivo: «in linea» entro il 3% (almeno 2 g), altrimenti +/− grammi. */
function matchDeltaHtml(actual, target){
  const delta = actual - target;
  const tol = Math.max(2, target*0.03);
  if(Math.abs(delta) <= tol) return `<span class="md md-ok">${uiT('match.onTrack','in linea')}</span>`;
  const sign = delta>0 ? '+' : '-';
  return `<span class="md ${delta>0?'md-over':'md-under'}">${sign}${fmt(Math.abs(delta))}g</span>`;
}

/* Riga di un macro nel suo colore (pallino, nome, etichetta a destra, grammi, «/ obiettivo»
   facoltativo, barra): usata dal riepilogo pasto qui sotto e dal riepilogo del Diario. */
function macroRowHtml(k, label, val, goal, barPct, rightHtml){
  const w = Math.max(0, Math.min(100, barPct||0));
  return `<div class="mms-row mms-${k}">
      <div class="mms-rh"><span class="mms-dot"></span><span class="mms-nm">${label}</span>${rightHtml||''}</div>
      <div class="mms-val"><b>${fmt(val)} g</b>${goal!=null ? `<span>/ ${fmt(goal)} g</span>` : ''}</div>
      <div class="mms-track"><i style="width:${w.toFixed(1)}%"></i></div>
    </div>`;
}

/* Riepilogo di un pasto, unico in tutto il sito (Match, Crea il tuo pasto, pianificatore
   dell'abbonamento): in alto il ring dei macro con le kcal al centro, a fianco un'etichetta e
   un dato principale; sotto, una riga per macro nel suo colore con barra.
   - con o.pct (Match): dato principale = % di corrispondenza + barra, prezzo in un riquadro a destra;
     righe con «/ obiettivo», scostamento e barra verso l'obiettivo (o.targets).
   - senza (composizione libera): dato principale = prezzo; righe con la quota di kcal del macro. */
function mealSummaryHtml(t, o={}){
  const kP = t.p*4, kC = t.c*4, kF = t.f*9, kTot = (kP+kC+kF) || 1;
  const share = {c:kC/kTot*100, p:kP/kTot*100, f:kF/kTot*100};
  const tg = o.targets;
  const row = (k, label, val)=> macroRowHtml(k, label, val,
    tg ? tg[k] : null,
    tg ? (tg[k] > 0 ? val/tg[k]*100 : 0) : share[k],
    tg ? matchDeltaHtml(val, tg[k]) : `<span class="md md-share">${Math.round(share[k])}% kcal</span>`);
  const hasPct = o.pct != null;
  return `
    <div class="mms-card"${o.style?` style="${o.style}"`:''}>
      <div class="mms-top">
        <div class="ring-wrap mms-ring">${foodRingHtml(t.p, t.c, t.f, t.kcal, {size:104, sw:10, static:true, still:true})}</div>
        <div class="mms-info">
          <span class="cm-badge">${o.badge || uiT('match.yourMeal','Il tuo pasto')}</span>
          ${hasPct
            ? `<div class="mms-pct"><b>${o.pct}%</b> ${uiT('match.corr','di corrispondenza')}</div>
               <div class="mms-bar" role="img" aria-label="${o.pct}% ${uiT('match.corr','di corrispondenza')}"><i style="width:${o.pct}%"></i></div>`
            : `<div class="mms-pct mms-pricebig"><b>${fmtPrice(sellPrice(t.price||0))}</b></div>
               <div class="mms-note">${uiT('common.price','Prezzo')}</div>`}
        </div>
        ${hasPct ? `<div class="mms-price"><b>${fmtPrice(sellPrice(t.price||0))}</b><span>${uiT('common.price','Prezzo')}</span></div>` : ''}
      </div>
      <div class="mms-macros">
        ${row('c', uiT('cat.carb','Carboidrati'), t.c)}
        ${row('p', uiT('cat.protein','Proteine'), t.p)}
        ${row('f', uiT('cat.fat','Grassi'), t.f)}
      </div>
    </div>`;
}

/* Macro in una riga: le lettere hanno i colori dei macro, i valori restano neutri */
function macroLineHtml(c, p, f){
  return `<span class="mline"><span class="c"><b>C</b> ${fmt(c,1)}</span><span class="p"><b>P</b> ${fmt(p,1)}</span><span class="f"><b>G</b> ${fmt(f,1)}</span></span>`;
}

/* Azioni dei pulsanti (data-action) */
defineActions({
  'ring-focus'(el){
    const svg = document.querySelector('.fring');
    if(!svg) return;
    const k = el.dataset.key || '', next = k && svg.dataset.focus!==k ? k : '';   // Calorie (chiave vuota) riporta sempre l'anello sul totale
    if(next) svg.dataset.focus = next; else delete svg.dataset.focus;
    document.querySelectorAll('.nutri-stat[data-key]').forEach(b=>{ const on = b.dataset.key ? b.dataset.key===next : !next; b.classList.toggle('on', on); b.setAttribute('aria-pressed', on ? 'true' : 'false'); });
    foodRingRefreshCenter(svg);
  },
});

/* Grafici di peso e calorie */

/* ---------------- GRAFICI TREND PIÙ LUNGHI (mese/trimestre/tutto) ----------------
   Il grafico peso e il mini-grafico kcal dello storico diario condividono lo
   stesso intervallo scelto dall'utente: 1 mese, 3 mesi o l'intero storico. */
const RANGE_DAYS = { '1m': 30, '3m': 90, 'all': Infinity };

function filterByRange(entries, rangeKey, dateOf){
  const days = RANGE_DAYS[rangeKey] || 30;
  if(days === Infinity) return entries;
  const cutoff = shiftDate(todayKey(), -days);
  return entries.filter(e => dateOf(e) >= cutoff);
}

function rangeSegControl(action, current){
  const opts = [['1m', uiT('trend.1m','1 mese')], ['3m', uiT('trend.3m','3 mesi')], ['all', uiT('trend.all','Tutto')]];
  return `<div class="seg-control" style="margin-top:12px;">
    ${opts.map(([k,l])=>`<button class="seg-btn ${current===k?'active':''}" data-action="${action}" data-range="${k}">${l}</button>`).join('')}
  </div>`;
}

function weightChart(log){
  const pts = log;
  if(pts.length < 2) return '';
  const kgs = pts.map(p=>p.kg);
  const min = Math.min(...kgs), max = Math.max(...kgs);
  const range = (max-min) || 1;
  const W = 300, H = 90, pad = 8;
  const coords = pts.map((p,i)=>{
    const x = pad + i*(W-pad*2)/(pts.length-1);
    const y = pad + (1-(p.kg-min)/range)*(H-pad*2);
    return [x,y];
  });
  const line = coords.map(([x,y],i)=>`${i?'L':'M'}${x.toFixed(1)},${y.toFixed(1)}`).join(' ');
  const area = `${line} L${coords[coords.length-1][0].toFixed(1)},${H} L${coords[0][0].toFixed(1)},${H} Z`;
  const showDots = pts.length <= 20;
  return `<div class="weight-chart">
    <div class="wc-head"><span>${uiT('weight.trend','Andamento')}</span><span>${fmt(min,1)} – ${fmt(max,1)} kg</span></div>
    <svg viewBox="0 0 ${W} ${H}" preserveAspectRatio="none" style="width:100%;height:90px;display:block;">
      <path d="${area}" fill="var(--accent-dim)"/>
      <path d="${line}" fill="none" stroke="var(--accent)" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/>
      ${showDots ? coords.map(([x,y])=>`<circle cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="3" fill="var(--accent)"/>`).join('') : ''}
    </svg>
  </div>`;
}

/* Mini-grafico kcal giornaliere per lo storico diario: stessa logica del
   grafico peso, ma sull'asse Y usa le kcal totali di ogni giornata registrata. */
function kcalTrendChart(days){
  const pts = days.slice().sort((a,b)=>a.key<b.key?-1:1);
  if(pts.length < 2) return '';
  const kcals = pts.map(p=>p.kcal);
  const min = Math.min(...kcals), max = Math.max(...kcals);
  const range = (max-min) || 1;
  const W = 300, H = 80, pad = 8;
  const coords = pts.map((p,i)=>{
    const x = pad + i*(W-pad*2)/(pts.length-1);
    const y = pad + (1-(p.kcal-min)/range)*(H-pad*2);
    return [x,y];
  });
  const line = coords.map(([x,y],i)=>`${i?'L':'M'}${x.toFixed(1)},${y.toFixed(1)}`).join(' ');
  const area = `${line} L${coords[coords.length-1][0].toFixed(1)},${H} L${coords[0][0].toFixed(1)},${H} Z`;
  return `<div class="weight-chart">
    <div class="wc-head"><span>${uiT('trend.kcalTrend','Andamento kcal')}</span><span>${fmt(min)} – ${fmt(max)} kcal</span></div>
    <svg viewBox="0 0 ${W} ${H}" preserveAspectRatio="none" style="width:100%;height:80px;display:block;">
      <path d="${area}" fill="var(--accent-dim)"/>
      <path d="${line}" fill="none" stroke="var(--accent)" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/>
    </svg>
  </div>`;
}

/* Fotocamera: scanner di codici a barre e QR */

let camStop = null;
let camSession = 0;   // ogni avvio (e ogni stop) ha il suo numero: un avvio superato da un altro non accende nulla

function stopCamera(){
  camSession++;
  if(camStop){ try{ camStop(); }catch{} camStop = null; }
}

/* Librerie di lettura caricate solo quando servono, come ripiego per i
   browser (Safari/iOS) che non hanno il lettore di codici integrato:
   jsQR per i QR, ZXing per i codici a barre EAN/UPC dei prodotti.
   Una richiesta per volta per ogni libreria: due chiamate ravvicinate (due render della mappa, due tocchi su
   «Attiva fotocamera») aspettano lo stesso caricamento invece di aggiungere lo script due volte. */
const scriptLoads = {};
/* Impronte (Subresource Integrity) delle librerie da CDN, versioni esatte: se il file servito cambia il browser non lo
   esegue (la mappa o il lettore mostrano il loro ripiego). crossorigin: le risposte sono leggibili (CORS), così anche il
   service worker le può tenere in cache senza risposte «opache». */
const CDN_INTEGRITY = {
  'https://cdn.jsdelivr.net/npm/leaflet@1.9.4/dist/leaflet.js': 'sha384-cxOPjt7s7Iz04uaHJceBmS+qpjv2JkIHNVcuOrM+YHwZOmJGBXI00mdUXEq65HTH',
  'https://cdn.jsdelivr.net/npm/leaflet@1.9.4/dist/leaflet.css': 'sha384-sHL9NAb7lN7rfvG5lfHpm643Xkcjzp4jFvuavGOndn6pjVqS6ny56CAt3nsEVT4H',
  'https://cdn.jsdelivr.net/npm/jsqr@1.4.0/dist/jsQR.js': 'sha384-b5Ya4Bq3qCyz39m2ISh+4DxjAIljdeFwK/BsXLuj9gugaNwAcj/ia15fxNZL9Nlx',
  'https://cdn.jsdelivr.net/npm/@zxing/browser@0.1.5/umd/zxing-browser.min.js': 'sha384-ylLhng89kD62+PVK1cjm4rAYg69zDlGrbbSfAE2Eb8Xqf8RoAQCMcRoUXZh7pAPC',
  'https://cdnjs.cloudflare.com/ajax/libs/lottie-web/5.12.2/lottie_light.min.js': 'sha384-Vtbz3QbtSBqleuQry6kQy5smig1gPZCXUoTFN7RmN9QW47xpEDsV/J1w0Pw0rDJu',
};
function cdnAttrs(el, src){
  el.crossOrigin = 'anonymous';
  if(CDN_INTEGRITY[src]) el.integrity = CDN_INTEGRITY[src];
}
function loadScript(src, check){
  if(check()) return Promise.resolve(true);
  if(scriptLoads[src]) return scriptLoads[src];
  return scriptLoads[src] = new Promise(res=>{
    const s = document.createElement('script');
    cdnAttrs(s, src);
    s.src = src;
    s.onload = ()=>{ delete scriptLoads[src]; res(check()); };
    s.onerror = ()=>{ delete scriptLoads[src]; s.remove(); res(false); };   // senza rete: al prossimo tentativo si riprova
    document.head.appendChild(s);
  });
}

function loadJsQR(){
  return loadScript('https://cdn.jsdelivr.net/npm/jsqr@1.4.0/dist/jsQR.js', ()=>!!window.jsQR);
}

function loadZXing(){
  return loadScript('https://cdn.jsdelivr.net/npm/@zxing/browser@0.1.5/umd/zxing-browser.min.js',
                    ()=>!!(window.ZXingBrowser && window.ZXingBrowser.BrowserMultiFormatReader));
}

/* Avvio della fotocamera: parte solo da un tocco dell'utente.
   onCode riceve il contenuto letto. */
async function startCamera(videoId, statusId, formats, onCode){
  const setStatus = (t)=>{ const el = document.getElementById(statusId); if(el) el.textContent = t; };
  const video = document.getElementById(videoId);
  if(!video) return;

  if(!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia){
    setStatus(uiT('cam.notAvailable','Fotocamera non disponibile su questo browser'));
    return;
  }
  if(!window.isSecureContext){
    setStatus(uiT('cam.needsHttps','La fotocamera richiede una connessione sicura (https)'));
    return;
  }

  stopCamera();   // un secondo tocco su «Attiva fotocamera» riparte da capo: niente due flussi né due cicli di lettura
  const session = camSession;
  const live = ()=> session === camSession;
  let stream;
  setStatus(uiT('cam.requestingAccess','Richiesta accesso alla fotocamera...'));
  try{
    stream = await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}}, audio:false});
  }catch(err){
    setStatus(err && err.name==='NotAllowedError'
      ? uiT('cam.permissionDenied','Permesso negato: consenti la fotocamera dalle impostazioni del browser')
      : uiT('cam.cannotOpen','Impossibile aprire la fotocamera: inserisci il codice a mano'));
    return;
  }

  // l'utente può aver lasciato la pagina mentre il browser chiedeva il permesso:
  // senza questo controllo lo stream resterebbe acceso senza nessuno che lo fermi
  if(!video.isConnected || !live()){ stream.getTracks().forEach(t=>t.stop()); return; }
  video.srcObject = stream;
  video.setAttribute('playsinline','');
  video.muted = true;
  try{ await video.play(); }catch{}
  camStop = ()=>{ stream.getTracks().forEach(t=>t.stop()); video.srcObject = null; };

  const nativo = ('BarcodeDetector' in window);
  let detector = null;
  if(nativo){
    try{ detector = new BarcodeDetector({formats}); }catch{ detector = null; }
  }
  let jsqrOk = false, zxingReader = null;
  if(!detector){
    setStatus(uiT('cam.preparingReader','Preparazione lettore...'));
    if(formats.includes('qr_code')){
      jsqrOk = await loadJsQR();
      if(!live()) return;
      if(!jsqrOk){ setStatus(uiT('cam.readerUnavailable','Lettore non disponibile: inserisci il codice a mano')); return; }
    } else {
      // codici a barre dei prodotti: uso ZXing, che copre EAN e UPC
      const ok = await loadZXing();
      if(!live()) return;
      if(!ok){ setStatus(uiT('cam.readerUnavailable','Lettore non disponibile: inserisci il codice a mano')); return; }
      try{
        zxingReader = new window.ZXingBrowser.BrowserMultiFormatReader();
        zxingReader.decodeFromVideoElement(video, (result)=>{
          if(result && camStop){
            const text = result.getText ? result.getText() : String(result);
            try{ zxingReader.reset(); }catch{}
            stopCamera();
            onCode(text);
          }
        });
        setStatus(uiT('cam.frameCode','Inquadra il codice...'));
        camStop = (()=>{ const prev = camStop; return ()=>{ try{ zxingReader.reset(); }catch{} prev && prev(); }; })();
        return;   // ZXing gestisce da sé il ciclo di lettura
      }catch{
        setStatus(uiT('cam.readerUnavailable','Lettore non disponibile: inserisci il codice a mano'));
        return;
      }
    }
  }
  setStatus(uiT('cam.frameCode','Inquadra il codice...'));

  const canvas = document.createElement('canvas');
  const ctx = canvas.getContext('2d', {willReadFrequently:true});
  const tick = async ()=>{
    if(!live()) return;   // fotocamera fermata o riavviata: questo ciclo finisce qui
    if(!document.getElementById(videoId)){ stopCamera(); return; }
    try{
      if(detector){
        const codes = await detector.detect(video);
        if(!live()) return;
        if(codes.length){ stopCamera(); onCode(codes[0].rawValue); return; }
      } else if(jsqrOk && video.videoWidth){
        canvas.width = video.videoWidth; canvas.height = video.videoHeight;
        ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
        const img = ctx.getImageData(0, 0, canvas.width, canvas.height);
        const res = window.jsQR(img.data, img.width, img.height);
        if(res && res.data){ stopCamera(); onCode(res.data); return; }
      }
    }catch{}
    requestAnimationFrame(tick);
  };
  requestAnimationFrame(tick);
}

/* Azioni dei pulsanti (data-action) */
defineActions({
  'cam-start'(el){
    if(el.dataset.kind==='qr'){
      startCamera('qr-video', 'qr-status', ['qr_code'], (raw)=>{
        const n = parseTableFromQr(raw);
        if(n) setTable(n);
        else { const s=document.getElementById('qr-status'); if(s) s.textContent = uiT('tablescan.notRecognized','QR non riconosciuto come tavolo MACRO\'S'); }
      });
    } else {
      const slot = el.dataset.slot || 'lunch';
      startCamera('scan-video', 'scan-status', ['ean_13','ean_8','upc_a','upc_e'], (raw)=>handleBarcode(raw, slot));
    }
  },
});

/* Mappa di tracking in tempo reale del delivery */

/* Leaflet + tile OpenStreetMap: stesso ecosistema gratuito e senza chiave già usato per
   geolocalizzazione/reverse geocoding in checkout.js. Caricata solo quando serve davvero (un
   ordine delivery non ancora consegnato), stesso schema di camera.js per jsQR/ZXing. */
function loadLeafletCss(){
  if(document.getElementById('leaflet-css')) return;
  const link = document.createElement('link');
  link.id = 'leaflet-css'; link.rel = 'stylesheet';
  cdnAttrs(link, 'https://cdn.jsdelivr.net/npm/leaflet@1.9.4/dist/leaflet.css');
  link.href = 'https://cdn.jsdelivr.net/npm/leaflet@1.9.4/dist/leaflet.css';
  document.head.appendChild(link);
}
/* Con un timeout: in un contesto di anteprima/sandbox che blocca lo script CDN senza nemmeno far
   scattare l'evento "error" (silenzioso), la Promise di loadScript resterebbe in sospeso per
   sempre e la mappa non comparirebbe MAI, senza nessun messaggio — peggio che dire chiaramente
   "non disponibile qui". Dopo 5s si arrende e si passa al ripiego testuale. */
function loadLeaflet(){
  loadLeafletCss();
  const load = loadScript('https://cdn.jsdelivr.net/npm/leaflet@1.9.4/dist/leaflet.js', ()=>!!window.L);
  const timeout = new Promise(res=> setTimeout(()=>res(false), 5000));
  return Promise.race([load, timeout]);
}

/* Origine del tragitto: questo prototipo non ha un indirizzo reale del locale, quindi parto da
   un punto a distanza breve e plausibile (1,2-2,5 km) dalla destinazione, in una direzione
   stabile per numero d'ordine — la stessa scena ad ogni ridisegno, non salta a caso. */
function demoRestaurantOrigin(dest, orderNum){
  const angle = (orderNum * 47) % 360 * Math.PI / 180;
  const distKm = 1.2 + (orderNum % 5) * 0.25;
  const dLat = (distKm / 111) * Math.cos(angle);
  const dLng = (distKm / (111 * Math.cos(dest.lat * Math.PI / 180))) * Math.sin(angle);
  return {lat: dest.lat + dLat, lng: dest.lng + dLng};
}

/* Ricerche in corso, per indirizzo: più preparazioni della stessa mappa (ridisegni ravvicinati della conferma) aspettano
   la stessa risposta invece di mandare ognuna la sua richiesta (Nominatim ne accetta una al secondo) */
const dmGeocoding = new Map();

/* Coordinate di consegna per la mappa: se il cliente non ha usato "Usa la mia posizione" in
   checkout, l'ordine non le ha già — provo a ricavarle geocodificando l'indirizzo scritto a
   mano (Nominatim, la stessa API già usata al contrario per il reverse geocoding), una volta
   sola, salvando il risultato sull'ordine. Se anche questo fallisce (offline, indirizzo non
   riconosciuto) la mappa semplicemente non compare: meglio ammetterlo che inventare un punto. */
function resolveDeliveryLatLng(order){
  if(order.deliveryLatLng) return Promise.resolve(order.deliveryLatLng);
  const a = order.address;
  if(!a || !a.street) return Promise.resolve(null);
  const q = [a.street, a.civic, a.zip, a.city].filter(Boolean).join(', ');
  if(!dmGeocoding.has(q)) dmGeocoding.set(q, geocodeAddress(order, q).finally(()=> dmGeocoding.delete(q)));
  return dmGeocoding.get(q);
}

async function geocodeAddress(order, q){
  try{
    const res = await fetch('https://nominatim.openstreetmap.org/search?format=jsonv2&limit=1&q='+encodeURIComponent(q), {headers:{'Accept':'application/json'}});
    if(!res.ok) return null;   // limite di richieste (429) o servizio non disponibile: niente mappa, si riprova al prossimo ordine
    const data = await res.json();
    if(data && data[0] && isFinite(+data[0].lat) && isFinite(+data[0].lon)){
      order.deliveryLatLng = {lat:+data[0].lat, lng:+data[0].lon};
      saveState();   // una volta sola per ordine: le coordinate restano sull'ordine
      return order.deliveryLatLng;
    }
  }catch{ /* offline o indirizzo non trovato: niente mappa, non un errore bloccante */ }
  return null;
}

/* Percorso stradale reale via OSRM (server dimostrativo pubblico, gratuito, senza chiave —
   stesso spirito delle altre integrazioni di questa app). Ripiego su una linea dritta se il
   servizio non risponde: onesto (non è la strada vera) ma il rider si muove comunque verso il
   cliente invece di restare fermo. */
async function fetchRoute(origin, dest){
  try{
    const url = `https://router.project-osrm.org/route/v1/driving/${origin.lng},${origin.lat};${dest.lng},${dest.lat}?overview=full&geometries=geojson`;
    const res = await fetch(url);
    const data = res.ok ? await res.json() : null;
    const coords = data && data.routes && data.routes[0] && data.routes[0].geometry.coordinates;
    if(coords && coords.length > 1) return coords.map(([lng,lat])=>[lat,lng]);
  }catch{ /* rete assente/instabile: ripiego sotto */ }
  return [[origin.lat, origin.lng], [dest.lat, dest.lng]];
}

/* Punto lungo il percorso alla frazione data (0-1), interpolato sulla distanza cumulativa reale
   dei tratti — non sul solo indice dell'array: con OSRM i punti hanno spaziatura irregolare
   (tanti in curva, pochi sui rettilinei) e muoverebbero il rider a scatti. */
function pointAlongRoute(route, frac){
  if(route.length===1) return route[0];
  const segLens = [];
  let total = 0;
  for(let i=1;i<route.length;i++){
    const d = Math.hypot(route[i][0]-route[i-1][0], route[i][1]-route[i-1][1]);
    segLens.push(d); total += d;
  }
  if(total===0) return route[0];
  let target = frac*total, acc = 0;
  for(let i=0;i<segLens.length;i++){
    if(acc+segLens[i] >= target){
      const t = segLens[i]===0 ? 0 : (target-acc)/segLens[i];
      return [route[i][0] + (route[i+1][0]-route[i][0])*t, route[i][1] + (route[i+1][1]-route[i][1])*t];
    }
    acc += segLens[i];
  }
  return route[route.length-1];
}

function cssVar(name){ return getComputedStyle(document.documentElement).getPropertyValue(name).trim(); }

let dmState = null;   // {orderNum, map, marker}
let dmGen = 0;        // numero della preparazione in corso: una preparazione superata (altro render, schermata lasciata) si ferma
let dmPending = null; // {orderNum, el}: preparazione in corso per quell'ordine in quel riquadro

/* Ferma la mappa e la distrugge: chiamata quando si lascia la schermata di conferma, quando
   l'ordine tracciato cambia, o quando la consegna è conclusa. Ferma anche una preparazione ancora in corso. */
function stopDeliveryMap(){
  dmGen++;
  dmPending = null;
  if(!dmState) return;
  try{ dmState.map.remove(); }catch{}
  dmState = null;
}

/* Crea (o lascia stare, se già attiva per lo stesso ordine e contenitore) la mappa con
   l'origine (MACRO'S), la destinazione (il cliente) e il percorso — visibile fin dal primo
   istante dell'ordine, non solo quando il rider parte davvero: il segnaposto del rider resta
   fermo all'origine finché la fase non è "in consegna" (orderRouteProgress se ne occupa).
   Idempotente: richiamata ad ogni giro del poll di stato in router.js. */
async function ensureDeliveryMap(containerId, order){
  const el = document.getElementById(containerId);
  if(!el){ stopDeliveryMap(); return; }
  if(dmState && dmState.orderNum===order.num && el.querySelector('.leaflet-container')) return;
  // la stessa mappa è già in preparazione (due render ravvicinati della conferma): non se ne prepara una seconda
  if(dmPending && dmPending.orderNum===order.num && dmPending.el===el) return;
  stopDeliveryMap();
  const gen = dmGen;
  dmPending = {orderNum: order.num, el};
  // dopo ogni attesa si prosegue solo se nessuno l'ha fermata e il riquadro è ancora quello di partenza
  const stillWanted = ()=> gen === dmGen && document.getElementById(containerId) === el;
  const unavailable = ()=>{ if(stillWanted()){ dmPending = null; el.innerHTML = `<p class="note-box">${uiT('tracker.mapUnavailable',"Posizione non disponibile per la mappa in tempo reale: il rider è comunque in arrivo.")}</p>`; } };

  const dest = await resolveDeliveryLatLng(order);
  if(!stillWanted()) return;   // l'utente ha cambiato schermata durante l'attesa
  if(!dest){ unavailable(); return; }
  const ok = await loadLeaflet();
  if(!stillWanted()) return;
  // Libreria non caricata (offline, o un'anteprima/sandbox che blocca lo script esterno):
  // meglio dirlo chiaramente che lasciare il riquadro vuoto senza spiegazione.
  if(!ok){ unavailable(); return; }

  const origin = demoRestaurantOrigin(dest, order.num);
  const route = await fetchRoute(origin, dest);
  if(!stillWanted()) return;
  dmPending = null;

  try{
    el.innerHTML = '<div class="delivery-map-canvas"></div>';
    // attribuzione dei dati OpenStreetMap: la richiede la licenza (ODbL) e la policy dei server delle mappe
    const map = L.map(el.querySelector('.delivery-map-canvas'), {zoomControl:false, attributionControl:true, scrollWheelZoom:false});
    map.attributionControl.setPrefix(false);
    L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {maxZoom:19, subdomains:'abc', attribution:'© OpenStreetMap'}).addTo(map);
    map.fitBounds(L.latLngBounds(route), {padding:[30,30]});

    L.polyline(route, {color:cssVar('--accent')||'#5CB85C', weight:4, opacity:.85, dashArray:'1,10', lineCap:'round'}).addTo(map);
    const dot = (bg)=> L.divIcon({className:'', html:`<span class="dmap-pin" style="background:${bg}"></span>`, iconSize:[14,14]});
    L.marker(origin, {icon:dot(cssVar('--ink')||'#24252A')}).addTo(map)
      .bindTooltip("MACRO'S", {permanent:true, direction:'top', offset:[0,-8], className:'dmap-tooltip'});
    L.marker(dest, {icon:dot(cssVar('--accent')||'#5CB85C')}).addTo(map)
      .bindTooltip(uiT('tracker.yourHome','Casa tua'), {permanent:true, direction:'top', offset:[0,-8], className:'dmap-tooltip'});
    const riderIcon = L.divIcon({className:'', html:`<span class="dmap-rider">${riderPersona(order).vehicle}</span>`, iconSize:[30,30], iconAnchor:[15,15]});
    const marker = L.marker(pointAlongRoute(route, orderRouteProgress(order)), {icon:riderIcon, zIndexOffset:1000}).addTo(map);

    dmState = {orderNum: order.num, map, marker, route};
  }catch{
    // Qualunque errore imprevisto di Leaflet (raro, ma un riquadro vuoto senza spiegazione è
    // peggio di un messaggio): stesso ripiego testuale degli altri casi.
    if(el.isConnected) el.innerHTML = `<p class="note-box">${uiT('tracker.mapUnavailable',"Posizione non disponibile per la mappa in tempo reale: il rider è comunque in arrivo.")}</p>`;
  }
}

/* Sposta il segnaposto del rider e aggiorna il testo dell'ETA: chiamata dal poll unico di
   router.js (niente timer proprio qui, per restare sincronizzata con l'animazione dei pallini
   della fase — un'unica fonte di tempo invece di due timer scoordinati). Non fa nulla se la
   mappa non è (ancora) attiva per questo ordine. */
function tickDeliveryMap(order){
  if(!dmState || dmState.orderNum !== order.num) return;
  const progress = orderRouteProgress(order);
  dmState.marker.setLatLng(pointAlongRoute(dmState.route, progress));
  const w = orderStageWindow(order);
  const etaEl = document.getElementById('delivery-map-eta');
  if(etaEl) etaEl.textContent = progress > 0.85
    ? uiT('tracker.almostThere','Il rider è quasi arrivato')
    : uiT('tracker.arrivingIn','Arriva tra ~') + Math.ceil(w.remainingMin) + ' ' + uiT('common.minutesShort','min');
  const wrapEl = document.getElementById('delivery-map-wrap');
  if(wrapEl) wrapEl.classList.toggle('dmap-close', progress > 0.85);
}

/* Salvataggio online (Supabase): account, dati sincronizzati tra dispositivi, ordini sul server */

/* ---------------- SALVATAGGIO ONLINE ----------------
   Finché CLOUD_CONFIG è vuoto l'app funziona come sempre: tutto resta sul dispositivo (localStorage).
   Compilandolo con i dati di un progetto Supabase (vedi server/LEGGIMI.md):
   - Accesso vero: email e password (con conferma via email e recupero password) oppure Google/Apple
     attivati nel pannello di Supabase; la sessione si rinnova da sola.
   - I dati dell'utente (profilo, diario, ordini, preferenze...) si salvano online dopo ogni modifica
     (con un breve ritardo, tutte insieme) e si ritrovano su qualsiasi dispositivo dopo l'accesso: vince
     la versione modificata per ultima. Le foto progresso restano solo sul dispositivo (troppo pesanti).
   - Ogni ordine viene registrato anche sul server (tabella orders), dove la cucina lo vede.
   - Dal Profilo si può eliminare l'account con tutti i dati online (diritto alla cancellazione, GDPR).
   Le chiavi qui sotto sono pubbliche per costruzione (la "anon key" di Supabase): a proteggere i dati
   sono le regole di sicurezza del database (ognuno vede solo i propri), in server/supabase/schema.sql.
   Peso, diario e obiettivi sono dati sulla salute: il progetto va creato nella regione UE. */
const CLOUD_CONFIG = {
  url: '',        // es. https://abcdefghijkl.supabase.co   (Supabase → Project Settings → API → Project URL)
  anonKey: '',    // la chiave "anon public" della stessa pagina
  payments: false, // true dopo aver pubblicato le funzioni Stripe (server/LEGGIMI.md, passo 5)
  vapidPublicKey: '', // chiave PUBBLICA delle notifiche push (node tools/push/vapid-keys.mjs; server/LEGGIMI.md, passo 7)
};

const CLOUD_SESSION_KEY = 'macros_cloud_session';
const CLOUD_SYNC_KEY = 'macros_cloud_sync';   // quando i dati di questo dispositivo sono stati salvati online l'ultima volta
const CLOUD_DIRTY_KEY = 'macros_cloud_dirty'; // ultima modifica locale non ancora salvata online (resiste a un ricaricamento)

function cloudEnabled(){ return !!(CLOUD_CONFIG.url && CLOUD_CONFIG.anonKey); }

function cloudReadKey(key){ try{ return JSON.parse(localStorage.getItem(key) || 'null'); }catch{ return null; } }

function cloudWriteKey(key, v){ try{ if(v == null) localStorage.removeItem(key); else localStorage.setItem(key, JSON.stringify(v)); }catch{ /* storage non disponibile */ } }

/* Sessione: {access_token, refresh_token, expires_at (secondi), user:{id, email}} */
function cloudSession(){ return cloudEnabled() ? cloudReadKey(CLOUD_SESSION_KEY) : null; }

function cloudSaveSession(s){
  if(!s || !s.access_token){ cloudWriteKey(CLOUD_SESSION_KEY, null); return null; }
  const session = {access_token: s.access_token, refresh_token: s.refresh_token,
    expires_at: s.expires_at || Math.floor(Date.now()/1000) + (s.expires_in || 3600),
    user: s.user ? {id: s.user.id, email: s.user.email} : (cloudSession() || {}).user};
  cloudWriteKey(CLOUD_SESSION_KEY, session);
  return session;
}

/* Errore leggibile dalle risposte di Supabase (i formati cambiano tra versioni) */
function cloudError(j, status){
  const code = (j && (j.error_code || j.code || j.error)) || String(status);
  const msg = (j && (j.error_description || j.msg || j.message)) || '';
  const known = {
    invalid_credentials: uiT('cloud.err.credentials','Email o password non corretti'),
    invalid_grant: uiT('cloud.err.credentials','Email o password non corretti'),
    email_not_confirmed: uiT('cloud.err.notConfirmed','Conferma prima l\'email: ti abbiamo mandato un link'),
    user_already_exists: uiT('cloud.err.exists','Esiste già un account con questa email: accedi'),
    weak_password: uiT('cloud.err.weak','Password troppo debole: usa almeno 6 caratteri'),
    over_request_rate_limit: uiT('cloud.err.rate','Troppi tentativi: riprova tra qualche minuto'),
  };
  const e = new Error(known[code] || (/already registered/i.test(msg) ? known.user_already_exists : /invalid login/i.test(msg) ? known.invalid_credentials : uiT('cloud.err.generic','Operazione non riuscita: riprova')));
  e.code = code;
  return e;
}

async function cloudRequest(path, opts={}){
  const headers = {'apikey': CLOUD_CONFIG.anonKey, 'Content-Type': 'application/json', ...(opts.headers || {})};
  if(opts.auth !== false){
    const s = await cloudFreshSession();
    headers.Authorization = 'Bearer ' + (s ? s.access_token : CLOUD_CONFIG.anonKey);
  }
  let res;
  try{ res = await fetch(CLOUD_CONFIG.url.replace(/\/$/, '') + path, {method: opts.method || 'GET', headers, body: opts.body ? JSON.stringify(opts.body) : undefined}); }
  catch{ const e = new Error(uiT('cloud.err.offline','Nessuna connessione: riprova tra poco')); e.code = 'network'; throw e; }
  const text = await res.text();
  let j = null;
  try{ j = text ? JSON.parse(text) : null; }catch{ j = null; }
  if(!res.ok) throw cloudError(j, res.status);
  return j;
}

/* Rinnova il token un minuto prima che scada */
let cloudRefreshing = null;
async function cloudFreshSession(){
  const s = cloudSession();
  if(!s) return null;
  if(s.expires_at - 60 > Date.now()/1000) return s;
  if(!cloudRefreshing){
    cloudRefreshing = cloudRequest('/auth/v1/token?grant_type=refresh_token', {method:'POST', auth:false, body:{refresh_token: s.refresh_token}})
      .then(cloudSaveSession)
      .catch(err=>{ if(err.code !== 'network') cloudSaveSession(null); return err.code === 'network' ? s : null; })   // senza rete si resta dentro
      .finally(()=>{ cloudRefreshing = null; });
  }
  return cloudRefreshing;
}

/* ---- Accesso ---- */
async function cloudSignIn(email, password){
  const s = cloudSaveSession(await cloudRequest('/auth/v1/token?grant_type=password', {method:'POST', auth:false, body:{email, password}}));
  await cloudPull();
  return s;
}

/* Registrazione: se il progetto chiede la conferma dell'email non c'è ancora una sessione (needsConfirm) */
async function cloudSignUp(email, password, name){
  const j = await cloudRequest('/auth/v1/signup?redirect_to=' + encodeURIComponent(cloudRedirectUrl()), {method:'POST', auth:false,
    body:{email, password, data: name ? {name} : {}}});
  if(j && j.access_token){ cloudSaveSession(j); await cloudPush(true); return {needsConfirm:false}; }
  return {needsConfirm:true};
}

function cloudRedirectUrl(){ return location.href.split('#')[0].split('?')[0]; }

/* Google / Apple: la pagina va da Supabase e torna qui con i token nell'indirizzo (cloudHandleRedirect) */
function cloudOAuth(provider){
  location.href = CLOUD_CONFIG.url.replace(/\/$/, '') + '/auth/v1/authorize?provider=' + encodeURIComponent(provider) + '&redirect_to=' + encodeURIComponent(cloudRedirectUrl());
}

function cloudRecover(email){
  return cloudRequest('/auth/v1/recover?redirect_to=' + encodeURIComponent(cloudRedirectUrl()), {method:'POST', auth:false, body:{email}});
}

async function cloudSignOut(){
  await pushForgetDevice();   // prima che la sessione sparisca: questo dispositivo non riceve più le notifiche dell'account
  if(cloudSession()) await cloudRequest('/auth/v1/logout', {method:'POST'}).catch(()=>{});
  cloudSaveSession(null);
  cloudWriteKey(CLOUD_SYNC_KEY, null);
  cloudWriteKey(CLOUD_DIRTY_KEY, null);
}

/* Ritorno da Google/Apple, dal link di conferma email o dal link per cambiare password:
   #access_token=...&refresh_token=...&expires_in=...&type=signup|recovery */
async function cloudHandleRedirect(){
  if(!cloudEnabled()) return false;
  const h = new URLSearchParams((location.hash || '').replace(/^#/, ''));
  // si toglie solo l'hash con i token: la query (?view, ?order, ?demo, ?pagamento) la leggono pwaHandleLaunch e il ritorno da Stripe
  if(!h.get('access_token')){
    if(h.get('error_description')){ history.replaceState(null, '', location.pathname + location.search); toast(h.get('error_description')); }
    return false;
  }
  history.replaceState(null, '', location.pathname + location.search);
  const s = cloudSaveSession({access_token:h.get('access_token'), refresh_token:h.get('refresh_token'), expires_in:+h.get('expires_in') || 3600});
  try{
    const user = await cloudRequest('/auth/v1/user');
    cloudSaveSession({...s, user});
    const meta = user.user_metadata || {};
    Object.assign(STATE.auth, {loggedIn:true, method: (user.app_metadata && user.app_metadata.provider) || 'email', email:user.email || STATE.auth.email});
    if(!STATE.auth.registered && meta.full_name && !STATE.auth.name) STATE.auth.name = meta.full_name;
    await cloudPull();
    if(h.get('type') === 'recovery') setTimeout(cloudAskNewPassword, 300);
    else toast(uiT('cloud.signedIn','Accesso effettuato'));
  }catch(err){ cloudSaveSession(null); toast(err.message); }
  render();
  return true;
}

function cloudAskNewPassword(){
  showPromptText(uiT('cloud.newPassTitle','Nuova password'), uiT('cloud.newPassMsg','Scegli la nuova password (almeno 6 caratteri).'), '', '••••••', v=>{
    if(v.length < 6){ toast(uiT('cloud.err.weak','Password troppo debole: usa almeno 6 caratteri')); return; }
    cloudRequest('/auth/v1/user', {method:'PUT', body:{password:v}}).then(()=> toast(uiT('cloud.passChanged','Password aggiornata'))).catch(e=> toast(e.message));
  });
  const input = document.getElementById('modal-input');
  if(input) input.type = 'password';
}

/* ---- Dati: un documento per utente (app_state), vince la versione modificata per ultima ---- */
let cloudPushTimer = null;
let cloudLocalChangedAt = 0;

/* Chiamata da saveState(): salva online qualche secondo dopo l'ultima modifica */
function cloudSchedulePush(){
  if(!cloudSession() || !STATE.auth.registered) return;
  cloudLocalChangedAt = Date.now();
  cloudWriteKey(CLOUD_DIRTY_KEY, cloudLocalChangedAt);
  clearTimeout(cloudPushTimer);
  cloudPushTimer = setTimeout(()=> cloudPush().catch(()=>{ /* offline: riprova alla prossima modifica */ }), 2500);
}

async function cloudPush(force){
  const s = cloudSession();
  if(!s || !s.user || (!STATE.auth.registered && !force)) return;
  const at = new Date().toISOString();
  await cloudRequest('/rest/v1/app_state', {method:'POST', headers:{Prefer:'resolution=merge-duplicates,return=minimal'},
    body:{user_id: s.user.id, data: buildSnapshot(false), updated_at: at}});
  cloudWriteKey(CLOUD_SYNC_KEY, {at, user: s.user.id});
  if((cloudReadKey(CLOUD_DIRTY_KEY) || 0) <= Date.parse(at)) cloudWriteKey(CLOUD_DIRTY_KEY, null);
}

/* All'accesso e all'avvio: se online c'è una versione più recente di quella di questo dispositivo, si usa quella */
async function cloudPull(){
  const s = cloudSession();
  if(!s || !s.user) return;
  const rows = await cloudRequest('/rest/v1/app_state?select=data,updated_at&user_id=eq.' + encodeURIComponent(s.user.id));
  const row = rows && rows[0];
  const sync = cloudReadKey(CLOUD_SYNC_KEY);
  const localAt = sync && sync.user === s.user.id ? Date.parse(sync.at) : 0;
  // vince la versione modificata per ultima: online, oppure su questo dispositivo (anche prima di un ricaricamento)
  if(row && Date.parse(row.updated_at) > Math.max(localAt, cloudLocalChangedAt, +cloudReadKey(CLOUD_DIRTY_KEY) || 0)){
    const photos = STATE.progressPhotos, photo = STATE.auth.photo;
    applySnapshot(row.data);
    if(!STATE.progressPhotos.length) STATE.progressPhotos = photos;   // le foto restano del dispositivo
    if(!STATE.auth.photo) STATE.auth.photo = photo;
    STATE.auth.loggedIn = true;
    syncUidCounter();
    cloudWriteKey(CLOUD_SYNC_KEY, {at: row.updated_at, user: s.user.id});
    saveState(true);   // solo sul dispositivo: questi dati arrivano appena da online
  } else if(STATE.auth.registered){
    await cloudPush();
  }
}

/* ---- Ordini sul server: la cucina li vede nella tabella orders ---- */
function cloudSaveOrder(order){
  const s = cloudSession();
  if(!s || !s.user || order.cloudId) return;
  cloudRequest('/rest/v1/orders', {method:'POST', headers:{Prefer:'return=representation'}, body:{
    user_id: s.user.id, num: order.num, mode: order.mode, total: Math.round(order.total*100)/100,
    items: order.cartSnapshot, address: order.address, scheduled_for: order.scheduledFor, pay: order.pay}})
    .then(rows=>{ if(rows && rows[0]){ order.cloudId = rows[0].id; saveState(); } })
    .catch(()=>{ /* offline: l'ordine resta sul dispositivo */ });
}

/* ---- Pagamento online (Stripe, tramite le funzioni in server/supabase/functions) ----
   Il server ricalcola il totale dal listino, salva l'ordine "da pagare" e crea la pagina di pagamento
   sicura di Stripe (carta, Apple Pay, Google Pay); al ritorno l'app aspetta che Stripe confermi al server
   il pagamento (paid_at) e solo allora conclude l'ordine sul dispositivo. */
const CLOUD_PAY_KEY = 'macros_cloud_payment';

function cloudPaymentsOn(){ return cloudEnabled() && CLOUD_CONFIG.payments && !!cloudSession(); }

async function cloudStartPayment(mode, cur){
  const t = orderPricing();
  toast(uiT('cloud.toPayment','Ti porto al pagamento sicuro…'));
  try{
    const r = await cloudRequest('/functions/v1/checkout', {method:'POST', body:{
      items: STATE.cart.map(({uid, ...it})=> it), mode, num: STATE.orderCounter, voucher: t.voucher ? t.voucher.code : null,
      address: mode === 'delivery' ? {...STATE.delivery} : null, scheduledFor: cur.schedule || null, pay: cur.pay || STATE.settings.payMethod || 'card',
      returnUrl: cloudRedirectUrl()}});
    // il server ricalcola il prezzo dal listino: se non coincide con il totale mostrato (un voucher personale, che il
    // server non conosce, o un listino diverso) non si va a pagare un importo diverso da quello che il cliente ha visto
    if(!r || !r.url || Math.abs((+r.total || 0) - t.price) > 0.005){
      toast(uiT('cloud.payMismatch','L\'importo da pagare non coincide con il totale mostrato: l\'ordine non è stato inviato. Riprova o paga in contanti.'));
      return;
    }
    cloudWriteKey(CLOUD_PAY_KEY, {orderId: r.orderId, total: r.total, mode, cart: STATE.cart,
      cur: {schedule: cur.schedule || null, pay: cur.pay || null, splitCount: cur.splitCount || null}});
    location.href = r.url;
  }catch{ toast(uiT('cloud.payFailed','Non è stato possibile avviare il pagamento: riprova')); }
}

/* Ritorno da Stripe: ?pagamento=ok|annullato&ordine=ID */
async function cloudHandlePaymentReturn(){
  const q = new URLSearchParams(location.search);
  const outcome = q.get('pagamento'), id = +q.get('ordine');
  if(!outcome) return false;
  history.replaceState(null, '', location.pathname);
  const pending = cloudReadKey(CLOUD_PAY_KEY);
  if(!pending || pending.orderId !== id) return false;
  if(outcome !== 'ok'){ cloudWriteKey(CLOUD_PAY_KEY, null); toast(uiT('cloud.payCancelled','Pagamento annullato: il carrello è ancora qui')); return true; }
  toast(uiT('cloud.payChecking','Stiamo verificando il pagamento…'));
  for(let i = 0; i < 10; i++){
    const rows = await cloudRequest('/rest/v1/orders?select=paid_at,total&id=eq.' + id).catch(()=> null);
    if(rows && rows[0] && rows[0].paid_at){
      cloudWriteKey(CLOUD_PAY_KEY, null);
      STATE.cart = pending.cart;
      const result = finalizeOrder(pending.mode, {schedule: pending.cur.schedule, pay: pending.cur.pay, cloudId: id, paidTotal: +rows[0].total});
      STATE.stack = [{view:'confirm', orderNum:result.orderNum, mode:result.mode, table:result.table, points:result.points,
        splitCount: pending.cur.splitCount, splitTotal: pending.cur.splitCount ? result.totalPrice : null, schedule: result.scheduledFor}];
      render();
      window.scrollTo({top:0});
      return true;
    }
    await new Promise(r=> setTimeout(r, 1500));
  }
  toast(uiT('cloud.payPending','Il pagamento non è ancora confermato: riapri l\'app tra poco'));
  return true;
}

/* ---- Eliminazione dell'account con tutti i dati online ---- */
async function cloudDeleteAccount(){
  await cloudRequest('/rest/v1/rpc/delete_my_account', {method:'POST', body:{}});
  cloudSaveSession(null);
  cloudWriteKey(CLOUD_SYNC_KEY, null);
}

/* Testo per il Profilo: dove stanno i dati */
function cloudStatusText(){
  const s = cloudSession();
  return s && s.user ? uiT('cloud.savedOnline','I tuoi dati sono salvati online ({email}).').replace('{email}', esc(s.user.email || '')) : uiT('profile.dataStaysLocal','I dati restano su questo dispositivo.');
}

/* All'avvio: ritorno da un accesso esterno, poi eventuale versione più recente online */
function cloudStart(){
  if(!cloudEnabled()) return;
  cloudHandleRedirect().then(handled=>{
    if(handled || !cloudSession()) return;
    cloudPull().then(()=> render()).catch(()=>{ /* offline: si usano i dati del dispositivo */ })
      .then(()=> cloudHandlePaymentReturn());
  });
}

/* Dati del menu MACRO'S: alimenti, bevande, dolci, integratori, famiglie e opzioni */

/* Gruppi di topping condivisi da tutti gli alimenti con un topping facoltativo (crema di riso
   proteica, yogurt greco, gelato proteico, pancake proteici): un'unica lista qui evita di doverla
   ripetere identica su ognuno. food.topping = {groups: TOPPING_GROUPS} sull'alimento che lo vuole;
   la logica di scelta/quantità è in toppingState() (js/features/detail.js). Solo gli id qui: gli
   alimenti veri e propri (f4/f9/f10/sy1-3/f2/f6) sono dichiarati più sotto in questo file, non
   serve che esistano già a questo punto.  */
const TOPPING_GROUPS = [
  {key:'detail.toppingSpreads', label:'Burri e creme', items:['f4','f9','f10']},
  {key:'detail.toppingSyrups', label:'Sciroppi zero', items:['sy1','sy2','sy3']},
  {key:'detail.toppingNuts', label:'Frutta secca', items:['f2','f6']},
];

/* Yogurt greco e crema di riso proteica: solo burri e sciroppi zero; la frutta si sceglie dal menu Frutta
   (tipo e grammatura), con il richiamo in fondo al riquadro (fruitLink) */
