function familiesFor(cat){ return FAMILIES.filter(f=>f.cat===cat); }

/* Insieme di varianti di un alimento: proprio (le uova, la cottura) oppure della sua famiglia (le polveri, il gusto).
   Con più insiemi (lo smoothie: gusto e base liquida) è il primo; tutti li dà optionSetsOf. */
function optionSetOf(food){
  if(!food) return null;
  if(food.optionSets) return OPTION_SETS[food.optionSets[0]];
  if(food.optionSet) return OPTION_SETS[food.optionSet];
  const fam = familyOfFood(food.id);
  return fam && fam.optionSet ? OPTION_SETS[fam.optionSet] : null;
}

/* Con più insiemi di varianti la scelta è una stringa sola con una parte per insieme, es. "cioccolato+acqua":
   passa così com'è in carrello, diario e ordini, che già conservano un'unica variante per alimento */
const OPT_SEP = '+';

function optionSetsOf(food){
  if(food && food.optionSets) return food.optionSets.map(k=>OPTION_SETS[k]);
  const set = optionSetOf(food);
  return set ? [set] : [];
}

/* Versione mostrabile: se ha varianti applico quella predefinita */
function displayFood(food, optId){
  if(!optionSetOf(food)) return food;
  return effectiveFood(food, optId || defaultOptFor(food));
}

function familyById(id){ return FAMILIES.find(f=>f.id===id); }

function familyOfFood(id){ return FAMILIES.find(f=>f.items.includes(id)); }

/* Applica la variante scelta (gusto delle proteine, cottura delle uova…) al nome e, se la variante li ha, ai valori dell'alimento */
function effectiveFood(food, optId){
  const set = optionSetOf(food);
  if(!set) return food;
  if(!optId) return food.prep ? {...food, name:`${tName(food)} · ${food.prep}`, _nameReady:true} : food;
  if(food.optionSets && food.optionSets.length > 1) return effectiveFoodMulti(food, optId);
  const ch = set.choices.find(x=>x.id===optId);
  if(!ch) return food;
  const baseName = tName(food);
  const choiceName = tPFlavorName(ch);
  const name = food.prep ? `${baseName} ${choiceName} · ${food.prep}` : `${baseName} · ${choiceName}`;
  // _nameReady: tName() non deve ritradurre, il nome è già composto e localizzato
  if(ch.add){   // una base liquida in proporzione all'alimento (cereali con il latte)
    const k = (set.mlPer100g || 0) / 100;
    return {...food, name, _nameReady:true, kcal: food.kcal + ch.add.kcal*k, p: food.p + ch.add.p*k, c: food.c + ch.add.c*k, f: food.f + ch.add.f*k,
      price: food.price + (ch.priceDelta||0), extraAllergens: ch.allergens || []};
  }
  if(!ch.macros) return {...food, name, _nameReady:true};
  // la preparazione aggiunge il proprio scarto rispetto alla base della famiglia
  const base = set.choices[0].macros;
  const delta = {kcal:food.kcal-base.kcal, p:food.p-base.p, c:food.c-base.c, f:food.f-base.f};
  return {...food, name, _nameReady:true,
    kcal: Math.max(0, ch.macros.kcal + delta.kcal),
    p: Math.max(0, ch.macros.p + delta.p),
    c: Math.max(0, ch.macros.c + delta.c),
    f: Math.max(0, ch.macros.f + delta.f),
    price: food.price + (ch.priceDelta||0),
  };
}

/* Smoothie: il gusto si applica come per le polveri (nome e valori), poi ogni altra parte aggiunge il suo
   nome e, per il liquido, i valori in proporzione alla polvere, il sovrapprezzo e gli allergeni */
function effectiveFoodMulti(food, optId){
  const [first, ...rest] = food.optionSets;
  const parts = String(optId).split(OPT_SEP);
  let out = effectiveFood({...food, optionSets:null, optionSet:first}, parts[0]);
  out = {...out, name: out._nameReady ? out.name : tName(food), _nameReady:true, extraAllergens:[]};
  rest.forEach((key, i)=>{
    const set = OPTION_SETS[key];
    const ch = set.choices.find(x=>x.id===parts[i+1]) || set.choices[0];
    out.name += '\u00A0· ' + tPFlavorName(ch);   // spazio unificatore: il puntino non va mai a capo da solo
    if(ch.add){
      const k = (set.mlPer100g || 0) / 100;
      out.kcal += ch.add.kcal * k; out.p += ch.add.p * k; out.c += ch.add.c * k; out.f += ch.add.f * k;
    }
    out.price += ch.priceDelta || 0;
    if(ch.allergens) out.extraAllergens.push(...ch.allergens);
  });
  return out;
}

function defaultOptFor(food){
  const sets = optionSetsOf(food);
  return sets.length ? sets.map(s=>s.choices[0].id).join(OPT_SEP) : null;
}

/* Carboidrati e proteine del menu: solo quelli che stanno in una famiglia. Crema di riso, avena e le
   proteine in polvere (tolte dal menu) restano come alimenti perché le usano la Crema di Riso Proteica,
   gli ordini già fatti e la ricerca nel diario, ma il Match non le propone più. */
const CARB_MENU = CARBS.filter(f=>FAMILIES.some(fm=>fm.items.includes(f.id)));
const PROTEIN_MENU = PROTEINS.filter(f=>FAMILIES.some(fm=>fm.items.includes(f.id)));

/* Grassi mostrati nella categoria del menu (e usati dal Match per comporre i pasti): solo questi, in
   quest'ordine. Gli altri grassi (creme spalmabili, chia, salsa yogurt) restano come alimenti, perché
   servono ancora ai topping dei piatti e agli ordini già fatti, ma non compaiono più nel menu. */
const FAT_MENU_IDS = ['f1','f3','f14','f2','f6','f11','f12','f13','f8'];
const FAT_MENU = FAT_MENU_IDS.map(id=>FATS.find(f=>f.id===id)).filter(Boolean);

/* Salse e bevande mostrate nel menu: Senape (s6) ed Estathé Zero (b4) restano solo per gli ordini già fatti */
const SAUCE_MENU = SAUCES.filter(x=>x.id!=='s6');
const DRINK_MENU = DRINKS.filter(x=>x.id!=='b4');
/* Extra selezionabili (costruisci pasto, Weekly Box): solo verdure/frutta/salse del menu */
MEALS.find(m=>m.id==='m14').topping = MEATBALL_TOPPING;
const EXTRAS_MENU = [...VEG_MENU, ...FRUIT_MENU, ...SAUCE_MENU];

const ALL_SINGLE = [...CARBS, ...PROTEINS, ...FATS];   // alimenti a grammatura libera (ricerca nel diario)

const ALL_FOODS  = [...CARBS, ...PROTEINS, ...FATS, ...MEALS, ...DRINKS, ...DESSERTS, ...SUPPLEMENTS];

/* Quello che il menu offre davvero, nell'ordine del menu: è ciò che trova la ricerca. Gli alimenti tolti
   dal menu (es. Estathé Zero) restano in ALL_FOODS solo per gli ordini già fatti e il diario. */
const MENU_FOODS = (()=>{
  const byId = new Map([...ALL_FOODS, ...EXTRAS].map(f=>[f.id, f]));
  const ids = [...FAMILIES.flatMap(fm=>fm.items), ...FAT_MENU_IDS, ...MEALS.map(m=>m.id), ...EXTRAS_MENU.map(e=>e.id),
               ...DRINK_MENU.map(d=>d.id), ...DESSERTS.map(d=>d.id), ...SUPPLEMENTS.map(s=>s.id)];
  return [...new Set(ids)].map(id=>byId.get(id)).filter(Boolean);
})();

function findFood(id){ return ALL_FOODS.find(f=>f.id===id) || EXTRAS.find(f=>f.id===id) || SYRUPS.find(f=>f.id===id) || CONDIMENTS.find(f=>f.id===id) || RETIRED_MEALS.find(f=>f.id===id) || GENERIC_FOODS.find(f=>f.id===id) || LEGACY_GENERIC_FOODS.find(f=>f.id===id) || DRINKS.find(f=>f.id===id); }

