const NUTRITION_PREF_PROTEIN = { standard:{label:'Standard'}, high:{label:'Alta'} };

const NUTRITION_PREF_CARBS   = { lower:{label:'Ridotti'}, balanced:{label:'Bilanciati'}, higher:{label:'Alti'} };

const NUTRITION_PREF_FAT     = { lower:{label:'Ridotti'}, balanced:{label:'Bilanciati'}, higher:{label:'Alti'} };

function tPrefProteinLabel(k){ const v=NUTRITION_PREF_PROTEIN[k]; return v?uiT('prefp.'+k+'.label',v.label):''; }

