function catTile(cat,label,iconType){
  const colorVar = {carb:'var(--carb)', protein:'var(--protein)', fat:'var(--fat)', meal:'var(--accent)',
                    veg:'var(--veg)', fruit:'var(--fruit)', sauce:'var(--sauce)', drink:'var(--carb)', supplement:'var(--supplement)'}[cat] || 'var(--ink)';
  const pic = CAT_ICON_IMG[cat];
  return `<button class="cat-tile" data-action="open-cat" data-cat="${cat}">
    <span class="ic${pic ? ' ic-img' : ''}" style="background:${thumbBg(cat)}">${pic ? `<img class="ic-${cat}" src="${pic}" alt="" draggable="false">` : foodIconSvg(iconType, colorVar, 28)}</span>
    <span>${label}</span>
  </button>`;
}

/* La scheda che apre un alimento, la stessa del menu: verdura, frutta, salse e bevande hanno la porzione
   fissa (scheda «porzione»), i dolci la loro scelta (gusto, coppetta), tutto il resto la grammatura */
function foodViewOf(f){
  if(f.cat==='dessert') return 'dessert';
  if(f.jar) return 'jar';
  return ['veg','fruit','sauce','drink'].includes(f.cat) && !f.condiment ? 'portion' : 'detail';
}

function foodCard(f, opt){
  const isFav = STATE.favorites.has(f.id);
  const fixed = f.fixed || f.cat==='meal';
  // Integratori: la scheda mostra la dose consigliata (def); la quantità si sceglie nella scheda alimento.
  // Alimenti a pezzi (le uova): valori e prezzo per un pezzo. Tutto il resto è per 100 g.
  const dose = f.cat==='supplement' && !fixed;
  const per = dose ? f.def/100 : f.unit ? f.unit.g/100 : 1;
  const perLabel = dose ? '' : f.unit ? `/${tUnit(f, 1)}` : '/100g';
  const priceLabel = fixed ? fmtPrice(sellPrice(f.price)) : fmtPrice(sellPrice(f.price*per))+(perLabel ? `<span style="opacity:.5;font-weight:500">${perLabel}</span>` : '');
  const amount = dose ? qtyLabel(f, f.def) : f.unit ? `1 ${tUnit(f, 1)}` : f.portionText ? tPortionText(f) : f.portion ? `${f.portion}${f.cat==='drink'?'ml':'g'}` : '';
  // Un conflitto dietetico non blocca la scelta (a differenza di Macro Match:
  // qui è una preferenza/allergia dell'utente, non un vincolo nutrizionale
  // della composizione), ma va segnalato in modo ben visibile prima che
  // l'alimento finisca nel carrello.
  const conflicts = dietConflicts(f);
  if(f.jar){   // barattolo: valori della dose, prezzo dal formato più piccolo (o da definire)
    const from = jarFromPrice(f);
    return `<div class="food-card ${conflicts.length?'diet-conflict':''}" data-action="nav" data-view="jar" data-id="${f.id}">
    <div class="food-thumb h-${f.cat}">
      <button class="heart" data-action="fav" data-id="${f.id}" style="color:${isFav?'var(--protein)':'#1c1d22'}">${heartLgIconSvg(isFav)}</button>
      <span class="fp">${foodPreview(f)}</span>
      ${premiumBadgeHtml(f, 'prem-badge')}
    </div>
    ${foodInfoHtml(f, f.packs ? null : f, f.packs ? `${jarPackLabel(f, jarPacks(f)[0])} · ${uiT('jar.perDay','{d} al giorno').replace('{d}', jarDoseText(f))}` : `${fmt(f.kcal)} kcal · ${uiT('jar.perDose','dose da {g} g').replace('{g}', f.dose)}`,
      from ? `${uiT('jar.from','da')} ${fmtPrice(from)}` : uiT('jar.priceTbd','Prezzo da definire'))}
  </div>`;
  }
  const conflictLabel = conflicts.map(c=>c.label).join(' · ');
  return `<div class="food-card ${conflicts.length?'diet-conflict':''}" data-action="nav" data-view="${foodViewOf(f)}" data-id="${f.id}"${opt?` data-opt="${opt}"`:''}>
    <div class="food-thumb h-${f.cat}">
      <button class="heart" data-action="fav" data-id="${f.id}" style="color:${isFav?'var(--protein)':'#1c1d22'}">${heartLgIconSvg(isFav)}</button>
      <span class="fp">${foodPreview(f, opt)}</span>
      ${conflicts.length ? `<span class="diet-warn" title="${conflictLabel}">${iconSvg('warn')}</span>` : ''}
    </div>
    ${foodInfoHtml(f, per !== 1 ? {p:f.p*per, c:f.c*per, f:f.f*per} : f, `${fmt(portionValues(f).kcal*per)} kcal${amount ? ` · ${amount}` : ''}`, priceLabel,
      conflicts.length ? `<div class="diet-conflict-label">${conflictLabel}</div>` : '')}
  </div>`;
}

/* Testo sotto l'anteprima di una scheda: categoria, nome, macro (proteine, carboidrati, grassi), calorie e prezzo.
   Le bevande passano macros=null: sono a zero e la riga non serve. */
function foodInfoHtml(f, macros, kcalText, priceHtml, note=''){
  return `<div class="food-info">
      ${foodTag(f.cat)}
      <div class="fname">${tName(f)}</div>
      ${macros ? `<div class="macro-mini"><span class="mm mm-p">P<b>${fmt(macros.p)}</b></span><span class="mm mm-c">C<b>${fmt(macros.c)}</b></span><span class="mm mm-f">G<b>${fmt(macros.f)}</b></span></div>` : ''}
      <div class="fmeta"><span class="kcal">${kcalText}</span><span class="price">${priceHtml}</span></div>
      ${note}
    </div>`;
}

/* Azioni dei pulsanti (data-action) */
defineActions({
  'open-cat'(el){
    // "Integratori" nella griglia categorie della Home non è una categoria
    // del Menu (renderMenu non sa gestire cat:'supplement'): la sua tile
    // apre direttamente la pagina dedicata, non il Menu.
    STATE.stack = el.dataset.cat==='supplement' ? [{view:'supplements'}] : [{view:'menu', cat:el.dataset.cat}];
    render();
    window.scrollTo({top:0});   // la Home era scorsa fino alle categorie: la nuova pagina parte dall'alto
  },
});

/* «Consigliati per te»: gli alimenti che l'utente ha ordinato più spesso. Niente lista di default:
   compare solo dopo almeno FOR_YOU_MIN_ORDERS ordini e con almeno 2 alimenti ripetuti in ordini
   diversi — prima l'app non sa ancora cosa gli piace. */
const FOR_YOU_MIN_ORDERS = 3;
function forYouFoods(){
  if(STATE.orders.length < FOR_YOU_MIN_ORDERS) return [];
  const count = {};
  STATE.orders.forEach(o=>{
    const seen = new Set();
    (o.cartSnapshot||[]).forEach(it=>{ if(it.foodId && it.kind !== 'meal') seen.add(it.foodId); });
    seen.forEach(id=>{ count[id] = (count[id]||0) + 1; });
  });
  const ids = Object.keys(count).filter(id=> count[id] >= 2 && findFood(id)).sort((a,b)=> count[b] - count[a]).slice(0, 4);
  return ids.length >= 2 ? ids.map(id=>displayFood(findFood(id))).filter(Boolean) : [];
}

/* Piatti pronti in Home: i 4 più acquistati, poi Gelato alla nocciola e Pancake proteici. Conta le porzioni di ogni piatto negli ordini fatti
   (STATE.orders — in una versione reale sarebbero le vendite di tutti i clienti); a parità, e finché
   non ci sono ordini, vale l'ordine dei best seller MACRO'S qui sotto. Tutti gli altri restano nel menu. */
const MEAL_BESTSELLERS = ['m1','m3','m2','m10','m4','m7','m12','m5','m11','m14','m15','m16','m17'];
function topMeals(n){
  const sold = {};
  STATE.orders.forEach(o=>(o.cartSnapshot||[]).forEach(it=>{
    if(it.kind==='meal' && it.foodId) sold[it.foodId] = (sold[it.foodId]||0) + itemQty(it) * (it.servings||1);
  }));
  const rank = id=>{ const i = MEAL_BESTSELLERS.indexOf(id); return i < 0 ? 99 : i; };
  return MEALS.slice().sort((a,b)=>(sold[b.id]||0) - (sold[a.id]||0) || rank(a.id) - rank(b.id)).slice(0, n);
}

/* Menu, famiglie, ricerca, integratori */

/* ---------------- RENDER: INTEGRATORI ----------------
   Pagina raggiunta dal banner in Home (non è una tab della bottom-nav):
   riusa foodCard()/renderDetail()/addSingleToCart() così com'è, perché
   ogni integratore è un "alimento" a grammatura libera con cat:'supplement'
   (la scheda mostra la dose consigliata, la quantità si sceglie nel dettaglio)
   — nessuna logica di carrello nuova da scrivere. */
function supplementTimingLabel(t){
  return {protein:uiT('supp.protein','Proteine'), vitamins:uiT('supp.vitamins','Vitamine e minerali'), wellness:uiT('supp.wellness','Benessere'), pre:uiT('supp.pre','Pre-workout'), intra:uiT('supp.intra','Intra-workout'), post:uiT('supp.post','Post-workout')}[t] || t;
}

function supplementTimingHint(t){
  return {
    pre:   uiT('supp.preHint','Prepara il corpo alla sessione: energia, focus e afflusso di sangue ai muscoli.'),
    intra: uiT('supp.intraHint',"Sostieni la performance durante l'allenamento: energia costante e idratazione."),
    post:  uiT('supp.postHint',"Favorisci il recupero dopo l'allenamento: ricostruzione muscolare ed energia."),
  }[t] || '';
}

const ELEVATE_LOGO = {light:'photos/elevate-black.7ebf8b8889.webp', dark:'photos/elevate-white.f1cf701fd0.webp'};

function renderSupplements(params){
  const timing = SUPPLEMENT_TIMINGS.includes(params.timing) ? params.timing : SUPPLEMENT_TIMINGS[0];
  const items = supplementsFor(timing);
  const icons = {protein:'dumbbell', vitamins:'pill', wellness:'leaf', pre:'bolt', intra:'drop', post:'refresh'};   // tre sezioni di prodotto, poi energia, idratazione, recupero
  return `
    <div class="brand-elevate" role="img" aria-label="Elevate Nutrition">
      <img class="be-light" src="${ELEVATE_LOGO.light}" alt="" draggable="false">
      <img class="be-dark" src="${ELEVATE_LOGO.dark}" alt="" draggable="false">
    </div>
    <div class="supp-seg">
      ${SUPPLEMENT_TIMINGS.map(t=>`<button class="supp-opt h-supplement ${timing===t?'active':''}" data-action="supptab" data-timing="${t}">
        <span class="so-ic">${iconSvg(icons[t])}</span><span class="so-l">${supplementTimingLabel(t)}</span>
      </button>`).join('')}
    </div>
    ${supplementTimingHint(timing) ? `<p class="menu-hint">${supplementTimingHint(timing)}</p>` : ''}
    ${(()=>{   // senza sottosezione in testa, poi le sottosezioni (Benessere → Benessere fegato)
      const free = items.filter(f=>!f.group);
      return (free.length ? `<div class="grid-2">${free.map(f=>foodCard(f)).join('')}</div>` : '')
        + Object.keys(SUPPLEMENT_GROUPS).map(g=>{ const list = items.filter(f=>f.group===g); return list.length ? `
        <div class="pgroup-label" style="margin-top:18px;">${uiT('suppgroup.'+g, SUPPLEMENT_GROUPS[g])}</div>
        <div class="grid-2" style="margin-top:10px;">${list.map(f=>foodCard(f)).join('')}</div>` : ''; }).join('');
    })()}
  `;
}

/* ---------------- RENDER: MENU ---------------- */
/* Card per prodotti a porzione fissa: bevande e dolci */
/* flavor: un gusto già scelto (il gelato alla nocciola in Home): foto e calorie di quel gusto, e la scheda si apre lì */
function fixedCard(f, flavor){
  const isDrink = f.cat==='drink';
  const fl = flavor && f.gelato ? GELATO_FLAVORS.find(x=>x.id===flavor) : null;
  const ph = fl ? foodPhoto(f.id, fl.id) : null;
  return `<div class="food-card" data-action="${isDrink?'add-fixed':'nav'}" ${isDrink?'':'data-view="dessert"'} data-id="${f.id}"${fl ? ` data-flavor="${fl.id}"` : ''}>
    <div class="food-thumb h-${f.cat}"><span class="fp">${ph ? `<img class="fp-img" src="${photoThumb(ph)}" alt="" draggable="false">` : foodPreview(f)}</span></div>
    ${foodInfoHtml(f, f, `${fmt(fl ? fl.kcal : f.kcal)} kcal · ${f.portion}${isDrink?'ml':'g'}`, fmtPrice(sellPrice(f.price)))}
  </div>`;
}

// Funzione (non const!) perché le etichette sono localizzate: vanno
// ricalcolate a ogni render, non congelate una sola volta al caricamento.
function menuTabsData(){
  return [['carb',uiT('cat.carb','Carboidrati')],['protein',uiT('cat.protein','Proteine')],['fat',uiT('cat.fat','Grassi')],
          ['veg',uiT('cat.veg','Verdura')],['fruit',uiT('cat.fruit','Frutta')],['sauce',uiT('cat.sauce','Salse')],
          ['drink',uiT('cat.drink','Bevande')],['meal',uiT('cat.mealPronti','Piatti Pronti')]];
}

/* Striscia delle categorie, condivisa tra menu e schermata famiglia */
function menuTabsHtml(activeCat, supplementsActive){
  // un pallino segnala che nel carrello c'è già qualcosa di quella categoria
  const inCart = new Set();
  STATE.cart.forEach(it=>{
    const f = it.foodId ? findFood(it.foodId) : null;
    if(f) inCart.add(f.cat);
    if(it.kind==='meal') inCart.add('meal');
    if(it.kind==='custom') inCart.add('meal');
  });
  // "Integratori" non è una categoria di cibo (niente slider di grammatura,
  // pagina propria con le tab pre/intra/post): non filtra il menu come le
  // altre, ma naviga alla sua pagina dedicata — per questo usa "nav" e non
  // "menutab". Lo stato "active" arriva da renderMenubar (non da activeCat,
  // che per la view 'supplements' non saprebbe risolverlo).
  return `<div class="tabs">${menuTabsData().map(([k,l])=>
    `<button class="tab ${activeCat===k?'active':''}" data-action="menutab" data-cat="${k}">${l}${inCart.has(k)?'<span class="tab-dot"></span>':''}</button>`
  ).join('')}
    <button class="tab ${supplementsActive?'active':''}" data-action="open-supplements">${uiT('viewtitle.supplements','Integratori')}</button>
  </div>`;
}


function renderMenu(params){
  const cat = params.cat || 'carb';
  const fam = params.fam || null;
  const b = STATE.build;

  setTimeout(()=>{
    const active = document.querySelector('.tabs .tab.active');
    if(active) active.scrollIntoView({inline:'center', block:'nearest'});
  }, 0);

  // --- categorie senza famiglie: elenco diretto ---
  if(['veg','fruit','sauce'].includes(cat)){
    const pool = applyDietFilter({veg:VEG_MENU, fruit:FRUIT_MENU, sauce:SAUCE_MENU}[cat]);
    return `<div class="grid-2">${pool.map(e=>{
        const on = b.extras.includes(e.id);
        return `<div class="food-card ${on?'picked':''}" data-action="toggle-extra" data-id="${e.id}">
          <div class="food-thumb h-${e.cat}"><span class="fp">${foodPreview(e)}</span>
            ${on?`<span class="picked-badge">${iconSvg('check')}</span>`:''}</div>
          ${foodInfoHtml(e, portionValues(e), `${fmt(portionValues(e).kcal)} kcal · ${e.portion}g`, fmtPrice(sellPrice(e.price)))}
        </div>`;
      }).join('')}</div>`;
  }
  if(cat==='drink'){
    return `<div class="grid-2">${applyDietFilter(DRINK_MENU).map(d=>{
        const on = (b.drinks||[]).includes(d.id);
        return `<div class="food-card ${on?'picked':''}" data-action="toggle-drink" data-id="${d.id}">
          <div class="food-thumb h-${d.cat}"><span class="fp">${foodPreview(d)}</span>
            ${on?`<span class="picked-badge">${iconSvg('check')}</span>`:''}</div>
          ${foodInfoHtml(d, null, `${fmt(portionValues(d).kcal)} kcal · ${d.portion} ml`, fmtPrice(sellPrice(d.price)))}
        </div>`;
      }).join('')}</div>`;
  }
  if(cat==='meal'){
    return `<div class="section-head" style="margin-top:6px;"><h2>${uiT('menu.savory','Salati')}</h2></div>
      <div class="grid-2">${applyDietFilter(MEALS).map(f=>foodCard(f)).join('')}</div>
      <div class="section-head" style="margin-top:26px;"><h2>${uiT('menu.desserts','Dolci')}</h2></div>
      <div class="grid-2">${applyDietFilter(DESSERTS).map(d=>fixedCard(d)).join('')}</div>`;
  }

  // --- categorie con famiglie ---
  const fams = familiesFor(cat);
  const colorVar = {carb:'var(--carb)', protein:'var(--protein)', fat:'var(--fat)'}[cat];

  if(!fams.length){
    // sezione «Frutta secca» (con i semi) sotto avocado, olio e parmigiano
    const NUTS = ['f2','f6','f11','f12','f13','f8'];
    const pool = applyDietFilter(FAT_MENU), others = pool.filter(f=>!NUTS.includes(f.id)), nuts = pool.filter(f=>NUTS.includes(f.id));
    return `${others.length ? `<div class="grid-2">${others.map(f=>foodCard(f)).join('')}</div>` : ''}
      ${nuts.length ? `<div class="pgroup-label" style="margin-top:18px;">${uiT('menu.nuts','Frutta secca')}</div>
      <div class="grid-2" style="margin-top:10px;">${nuts.map(f=>foodCard(f)).join('')}</div>` : ''}`;
  }

  if(!fam){
    return `<div class="fam-list">${fams.map(fm=>{
        const chosen = b[cat] && fm.items.includes(b[cat].foodId);
        return `<button class="fam-card ${chosen?'chosen':''}" data-action="menufam" data-cat="${cat}" data-fam="${fm.id}">
          <span class="fm-ic${FAM_ICON_IMG[fm.id] ? ' fm-ic-img' : ''}" style="background:${thumbBg(cat)}">${FAM_ICON_IMG[fm.id] ? `<img src="${FAM_ICON_IMG[fm.id]}" alt="" draggable="false">` : foodIconSvg(fm.icon, colorVar, 24)}</span>
          <span class="fm-body">
            <span class="fm-name">${tFamilyName(fm)}</span>
            <span class="fm-count">${fm.items.length} ${fm.items.length===1?uiT('menu.preparation','preparazione'):uiT('menu.preparations','preparazioni')}${fm.optionSet || fm.items.some(id=>optionSetOf(findFood(id)))?' · '+uiT('menu.moreVariants','più varianti'):''}</span>
          </span>
          <span class="fm-chev">${iconSvg('chev')}</span>
        </button>`;
      }).join('')}</div>`;
  }

  return ``;
}

/* Barra del pasto in composizione: sempre visibile mentre si sfoglia il menu,
   così Menu e Build sono la stessa cosa invece di due percorsi separati. */
/* Colonne della griglia dei gusti: righe piene che occupano tutta la larghezza del riquadro
   (fino a 4 per riga; 6 gusti = 3 + 3, 5 = 3 + 2 invece di 4 + 1) */
function flavorCols(n){ return n <= 4 ? n : n % 4 === 0 ? 4 : n % 3 === 0 || n === 5 ? 3 : 4; }

function optionSwatches(set, chosen, action, famId, photoId){
  const ch = set.choices.find(x=>x.id===chosen) || set.choices[0];
  // con photoId (la Monster): la miniatura della lattina al posto del pallino, in una griglia che riempie il riquadro
  const pic = o => photoId && foodPhoto(photoId, o.id);
  const withPics = !!(photoId && set.choices.every(pic));
  // gusti delle proteine (smoothie): la loro icona al posto del pallino colorato
  const flavorIcon = o => FLAVOR_ICON[String(o.id).split('+')[0]];   // smoothie: «gusto+liquido»
  const withIcons = !withPics && set.choices.every(flavorIcon);
  const nameOf = o => o._flavorNS === 'flavor' ? tFlavorName(o) : tPFlavorName(o);
  const subOf = o => o._flavorNS === 'flavor' ? (o.sub||'') : tPFlavorSub(o);
  return `<div class="swatch-block">
    <div class="sw-label">${set.label} <span class="sw-value">— ${nameOf(ch)}</span></div>
    <div class="flavor-grid${withPics ? ' has-pics' : ''}" style="--cols:${flavorCols(set.choices.length)}">
      ${set.choices.map(o=>`
        <button class="flavor-card ${chosen===o.id?'active':''}" data-action="${action}" ${famId?`data-fam="${famId}"`:''} data-opt="${o.id}"
                style="--sw:${o.color||'var(--surface-3)'}">
          ${withPics ? `<img class="fl-pic" src="${photoThumb(pic(o))}" alt="" draggable="false">` : withIcons ? `<img class="fl-icon" src="${flavorIcon(o)}" alt="" draggable="false">` : '<span class="fl-dot"></span>'}<span class="fl-name">${nameOf(o)}</span>
        </button>`).join('')}
    </div>
    <div class="sw-sub">${subOf(ch)}${ch.priceDelta?` · +${fmtPrice(ch.priceDelta)}`:''}</div>
  </div>`;
}

/* Scelta tra preparazioni (la cottura delle uova): un pulsante per ognuna con la sua anteprima, nello stile del blocco delle aggiunte */
function optionCards(set, chosen, action, foodId){
  const ch = set.choices.find(x=>x.id===chosen) || set.choices[0];
  return `<div class="addon-block cook-block">
    <div class="ab-head"><span class="ab-label">${uiT(set.labelKey || 'detail.cooking', set.label || 'Cottura')}</span></div>
    <div class="ab-seg${set.choices.length > 3 ? ' ab-seg-wrap' : ''}">
      ${set.choices.map(o=>`
        <button class="ab-opt cook-opt ${ch.id===o.id?'active':''}" data-action="${action}" data-opt="${o.id}">
          <span class="cook-ic">${foodArtSvg(set.artId || foodId, o._artOpt || o.id) || (foodPhoto(foodId, o.id) ? `<img src="${photoThumb(foodPhoto(foodId, o.id))}" alt="">` : foodIconSvg(foodId, 'var(--carb)', 30))}</span>
          <span class="abo-l">${tPFlavorName(o)}</span>
        </button>`).join('')}
    </div>
    <div class="ab-note">${tPFlavorSub(ch)}</div>
  </div>`;
}

/* Più insiemi di varianti nella stessa scheda (smoothie: gusto e base liquida): ogni scelta porta con sé la
   variante completa con cambiata solo la propria parte, così i selettori restano quelli di sempre.
   Mostrati in ordine inverso: nello smoothie si sceglie prima la base liquida e poi il gusto (la variante
   salvata resta "gusto+liquido", come negli ordini già fatti). */
function optionPickersMulti(food, opt, action){
  const sets = optionSetsOf(food);
  const cur = String(opt || defaultOptFor(food)).split(OPT_SEP);
  const pickers = sets.map((set, k)=>{
    const withPart = id => sets.map((s, i)=> i===k ? id : (cur[i] || s.choices[0].id)).join(OPT_SEP);
    const chosen = withPart(cur[k] || set.choices[0].id);
    const derived = {...set, choices: set.choices.map(ch=>({...ch, id: withPart(ch.id), _artOpt: ch._artOpt || ch.id, name: tPFlavorName(ch), sub: tPFlavorSub(ch)}))};
    if(set.kind === 'cards') return optionCards(derived, chosen, action, food.id);
    // gusti degli smoothie: le icone dei gusti (cartella «gusti proteini», FLAVOR_ICON) al posto dei pallini
    return optionSwatches({...derived, label: uiT('dessert.flavor', set.label)}, chosen, action);
  });
  // smoothie: prima la base liquida, poi il gusto; gli altri (Rice Krispies: gusto, poi «Con cosa?») nell'ordine dei dati
  return (food.optionSets.includes('smoothieLiquid') ? pickers.reverse() : pickers).join('');
}

function renderFamily(params){
  const fm = familyById(params.fam);
  if(!fm) return `<div class="empty-state"><p>${uiT('common.categoryNotFound','Categoria non trovata')}</p></div>`;
  const items = applyDietFilter(fm.items.map(id=>findFood(id)).filter(Boolean));
  const set = fm.optionSet ? {...OPTION_SETS[fm.optionSet], label: uiT('dessert.flavor', OPTION_SETS[fm.optionSet].label)} : null;
  const chosenOpt = params.opt || (set ? set.choices[0].id : null);

  setTimeout(()=>{
    const active = document.querySelector('.tabs .tab.active');
    if(active) active.scrollIntoView({inline:'center', block:'nearest'});
  }, 0);

  return `
    <h2 style="font-size:22px;margin-top:14px;">${tFamilyName(fm)}</h2>
    ${set ? optionSwatches(set, chosenOpt, 'pick-option', fm.id) : ''}

    ${(fm.groups || [{items: fm.items}]).map(g=>{
      // famiglie divise in sezioni (Cereali: preparazioni salate e dolci)
      const list = items.filter(f=> g.items.includes(f.id));
      if(!list.length) return '';
      return `${g.label ? `<div class="pgroup-label" style="margin-top:18px;">${uiT(g.key, g.label)}</div>` : ''}
      <div class="grid-2" style="margin-top:${g.label ? 10 : 16}px;">
        ${list.map(f=> foodCard(effectiveFood(f, chosenOpt), chosenOpt)).join('')}
      </div>`;
    }).join('')}
  `;
}

/* ---------------- RENDER: SEARCH ---------------- */
function renderSearch(params){
  const q = (params.q||'').toLowerCase();
  const results = q ? applyDietFilter(MENU_FOODS.filter(f=>tName(f).toLowerCase().includes(q))) : [];
  return `
    <div class="search-bar" style="margin-top:14px;">
      ${iconSvg('search')}
      <input id="search-input" type="text" enterkeyhint="search" autocomplete="off" placeholder="${uiT('search.placeholder','Cerca alimenti, piatti, categorie...')}" value="${esc(params.q)}" autofocus>
    </div>
    <div style="margin-top:20px;">
      ${!q ? `<div class="empty-state"><span class="glyph">${iconSvg('search')}</span><p>${uiT('search.prompt','Cerca tra oltre')} ${MENU_FOODS.length} ${uiT('search.promptSuffix','alimenti e piatti')}</p></div>` :
        results.length ? `<div class="grid-2">${results.map(f=>foodCard(f)).join('')}</div>` :
        `<div class="empty-state"><span class="glyph">${iconSvg('search')}</span><p>${uiT('search.noResults','Nessun risultato per')} "${esc(params.q)}"</p></div>`}
    </div>
  `;
}

/* Azioni dei pulsanti (data-action) */
defineActions({
  'fav'(el){
    const id = el.dataset.id;
    if(STATE.favorites.has(id)) STATE.favorites.delete(id); else STATE.favorites.add(id);
    render();
  },
  'pick-option'(el){
    replaceView('family', {...current(), fam:el.dataset.fam, opt:el.dataset.opt}, true);
  },
  'menutab'(el){
    if(current().view!=='menu'){ STATE.stack=[{view:'menu', cat:el.dataset.cat}]; render(); window.scrollTo({top:0}); return; }
    replaceView('menu', {cat:el.dataset.cat, buildSlot: current().buildSlot});
  },
  'supptab'(el){
    replaceView('supplements', {timing:el.dataset.timing});
  },
  'open-supplements'(){
    if(current().view!=='supplements') navigateTo('supplements', {});
  },
  'menufam'(el){ navigateTo('family', {fam:el.dataset.fam, buildSlot: current().buildSlot}); },
});

/* Durante la composizione di una parola (suggerimenti della tastiera, accenti) il campo non si ridisegna: si aggiorna alla fine */
const menuSearch = (field, e)=>{
  if(e && e.isComposing) return;
  replaceView('search', {q:field.value}, true);
  const inp = document.getElementById('search-input');
  if(inp){ inp.focus(); inp.selectionStart = inp.value.length; }
};
defineFieldHandlers('input', [['#search-input', menuSearch]]);
defineFieldHandlers('compositionend', [['#search-input', menuSearch]]);

/* Scheda alimento, dolci e porzioni */

/* Variante mostrata nella scheda: quella appena scelta, altrimenti quella già salvata nello slot del pasto
   per lo stesso alimento, altrimenti la prima */
function detailOpt(raw, params){
  if(params.opt) return params.opt;
  const saved = slotSavedFor(params);
  return (saved && saved.foodId === raw.id && saved.opt) || defaultOptFor(raw);
}

/* Grammi mostrati all'apertura della scheda (e confermati se non si tocca la quantità): quelli scelti, altrimenti quelli
   già nello slot del pasto per lo stesso alimento, altrimenti la dose predefinita; per gli alimenti a pezzi, pezzi interi */
function detailStartGrams(raw, food, params){
  const slotSaved = slotSavedFor(params);
  const inherited = (slotSaved && slotSaved.foodId === raw.id) ? slotSaved.grams : null;
  const wanted = params.grams || inherited || food.def || 100;
  return food.unit ? clamp(Math.round(wanted/food.unit.g)*food.unit.g, food.min, food.max) : wanted;
}

/* Cosa c'è già nello slot del pasto (carboidrato, proteina, grasso) da cui si è aperta la scheda */
function slotSavedFor(params){
  return params.slot ? (inMealBuilder() ? (STATE.mealPlanBuilder||{})[params.slot] : STATE.build[params.slot]) : null;
}

/* Composizione di un prodotto composto (l'intra workout): una riga per ingrediente con la quantità nella porzione */
function compositionHtml(food){
  if(!food.composition) return '';
  return `<div class="addon-block comp-block">
    <div class="ab-head"><span class="ab-label">${uiT('detail.composition','Composizione')}</span><span class="ab-price">${tPortionText(food)}</span></div>
    <ul class="comp-list">${food.composition.map(i=>`<li><span>${tIngredient(i)}</span><b>${doseText(i.mg)}</b></li>`).join('')}</ul>
  </div>`;
}

/* Topping facoltativo (nessuno di default): condiviso da qualunque alimento con food.topping —
   la crema di riso proteica (dentro bowlState), lo yogurt greco, il gelato e i pancake proteici
   (direttamente in renderDetail/renderDessert). Le salse a porzione fissa (cat 'sauce' con
   .portion invece di min/max/step) non hanno uno stepper: si aggiungono alla loro porzione. */
/* Riquadro esplicativo dei condimenti: la quantità si calibra da sola sui grammi di riso/pasta */
function condimentInfoHtml(food, top){
  const what = /riso/i.test(food.name) ? uiT('detail.condRice','riso')
    : /gnocchi/i.test(food.name) ? uiT('detail.condGnocchi','gnocchi')
    : food.id==='m14' ? uiT('detail.condMeatballs','polpette') : uiT('detail.condPasta','pasta');
  return `<div class="cond-info">
    <div class="cond-info-title">${uiT('detail.condInfoTitle','Il sapore perfetto, senza sprechi calorici.')}</div>
    <div class="cond-info-body">${uiT('detail.condInfoBody','La quantità di condimento viene calibrata in automatico sui grammi di {what} che hai scelto. In questo modo il tuo piatto resta avvolgente e gustoso, rispettando i tuoi obiettivi.').replace('{what}', what)}</div>
    ${top.toppingFood && top.toppingFood.kv ? `<div class="cond-info-g"><b id="topping-g">${top.toppingG} g</b> ${uiT('detail.condOf','di')} ${esc(tName(top.toppingFood))}</div>` : ''}
  </div>`;
}

/* Grammatura automatica del condimento: Q_c = Q_carb × K_v (grammi di pasta/riso a crudo × coefficiente
   di voluminizzazione del condimento), a passi di 10 g e dentro i limiti del condimento */
function condimentAutoG(cond, carbG, coefKey){
  const k = cond && ((coefKey && cond[coefKey]) || cond.kv);
  if(!k || !(carbG > 0)) return null;
  return clamp(Math.round(carbG * k / cond.step) * cond.step, cond.min, cond.max);
}

/* baseG: grammi dell'alimento principale (pasta/riso), per il condimento a grammatura automatica:
   il condimento segue sempre la pasta/il riso, i suoi grammi non si scelgono a mano. */
function toppingState(params, baseG){
  const toppingId = params.toppingId || 'none';
  const toppingFood = toppingId==='none' ? null : findFood(toppingId);
  const toppingFixed = !!(toppingFood && toppingFood.portion != null);
  // i condimenti (kv) sono SEMPRE automatici: l'utente non ne sceglie i grammi
  const auto = !!(toppingFood && toppingFood.kv);
  // la base sceglie il coefficiente: pasta/riso a crudo K_v, gnocchi K_gno (condCoef:'kgno')
  const mainFood = params.id ? findFood(params.id) : null;
  const autoG = auto ? condimentAutoG(toppingFood, baseG != null ? baseG : params.grams, mainFood && mainFood.condCoef) : null;
  const toppingG = !toppingFood ? 0 : toppingFixed ? toppingFood.portion
    : autoG != null ? autoG : clamp(params.toppingG || toppingFood.def, toppingFood.min, toppingFood.max);
  // topping «combo» (yogurt, crema di riso): burro E sciroppo insieme; lo sciroppo è a dose fissa
  const combo = !!(mainFood && mainFood.topping && mainFood.topping.combo);
  const syrupFood = combo && params.syrupId ? findFood(params.syrupId) : null;
  const syrupG = syrupFood ? (syrupFood.portion != null ? syrupFood.portion : syrupFood.def) : 0;
  const list = [toppingFood && {food:toppingFood, g:toppingG}, syrupFood && {food:syrupFood, g:syrupG}].filter(Boolean);   // tutto ciò che si aggiunge
  return {toppingId, toppingFood, toppingFixed, toppingG, auto: autoG != null, open: !!params.toppingOpen,
          combo, syrupId: syrupFood ? syrupFood.id : null, syrupFood, syrupG, list};
}

/* Riquadro del topping facoltativo: tendina chiusa di default («Vuoi aggiungere un topping? +»),
   tre gruppi (burri/creme, sciroppi zero, frutta secca), si chiude con la X finché non si sceglie
   un topping vero. Condiviso da tutti gli alimenti con food.topping. */
function toppingPickerHtml(food, top){
  if(!top) return '';
  if(!(top.open || top.toppingFood || top.syrupFood)){
    return `<button class="addon-block bowl-add-topping" data-action="topping-open">
      <span class="ab-label">${food.topping.askKey ? uiT(food.topping.askKey, food.topping.ask) : uiT('detail.addTopping','Vuoi aggiungere un topping?')}</span>
      <span class="qty-btn">${iconSvg('plus')}</span>
    </button>${fruitLinkHtml(food)}`;
  }
  return `
    <div class="addon-block cook-block">
      <div class="ab-head">
        <span class="ab-label">${food.topping.labelKey ? uiT(food.topping.labelKey, food.topping.label) : uiT('detail.topping','Topping')}</span>
        ${top.toppingId==='none' && !top.syrupFood
          ? `<button class="bowl-topping-close" data-action="topping-close" aria-label="${uiT('common.close','Chiudi')}">${iconSvg('close')}</button>`
          : ''}
      </div>
      ${food.topping.groups.map(g=>`
        <div class="bowl-topping-group-label">${uiT(g.key, g.label)}</div>
        <div class="bowl-topping-grid">
          ${g.items.map(id=>{ const t=findFood(id); const isSyrup = top.combo && SYRUPS.some(x=>x.id===id); return `
            <button class="ab-opt cook-opt ${(isSyrup ? top.syrupId===id : top.toppingId===id)?'active':''}" data-action="${isSyrup ? 'syrup-pick' : 'topping-pick'}" data-val="${id}">
              <span class="cook-ic">${foodArtSvg(t.id) || foodIcon(t,32)}</span>
              <span class="abo-l">${tName(t)}</span>
            </button>`; }).join('')}
        </div>
        ${g.items.includes(top.toppingId) ? toppingQtyHtml(top) : ''}
      `).join('')}
      ${food.topping.groups.some(g=>g.items.some(id=>(findFood(id)||{}).kv)) ? condimentInfoHtml(food, top) : ''}
      ${fruitLinkHtml(food)}
    </div>
  `;
}

/* Grammatura del topping scelto (burri, creme…), subito sotto il suo gruppo. Si apre con un'animazione
   solo quando il topping cambia: con − e + la scheda si ridisegna ma l'animazione non riparte */
let lastToppingQtyKey = '';
function toppingQtyHtml(top){
  if(!(top.toppingFood && !top.toppingFixed && !top.toppingFood.kv)) return '';
  const key = current().view + '|' + current().id + '|' + top.toppingId;
  const anim = key !== lastToppingQtyKey; lastToppingQtyKey = key;
  return `<div class="topping-qty${anim ? ' tq-in' : ''}"><div class="tq-inner">
    <span class="tq-label">${uiT('common.quantity','Quantità')} · ${esc(tName(top.toppingFood))}</span>
    <div class="qty-controls">
      <button class="qty-btn" data-action="topping-qty" data-delta="-1" ${top.toppingG<=top.toppingFood.min?'disabled':''}>${iconSvg('minus')}</button>
      <div class="qty-value"><span id="topping-g">${top.toppingG} g</span></div>
      <button class="qty-btn" data-action="topping-qty" data-delta="1" ${top.toppingG>=top.toppingFood.max?'disabled':''}>${iconSvg('plus')}</button>
    </div>
  </div></div>`;
}

/* Yogurt e crema di riso: frutta e frutta secca non sono tra i topping; due promemoria (senza collegamento)
   ricordano dove trovarle nel menu */
function fruitLinkHtml(food){
  return food.topping && food.topping.fruitLink ? `<div class="fruit-link">${uiT('detail.fruitLink','Puoi aggiungere anche della frutta: la trovi nel menu Frutta, con tipo e quantità a scelta.')}</div>
    <div class="fruit-link nuts-link">${uiT('detail.nutsLink','Puoi aggiungere anche della frutta secca: la trovi nel menu Grassi, con tipo e quantità a scelta.')}</div>` : '';
}

/* Unico piatto pronto personalizzabile (la crema di riso proteica): base e proteine sono
   alimenti veri con la propria grammatura; il topping (vedi toppingState/toppingPickerHtml
   sopra) è facoltativo. Restituisce gli alimenti/quantità scelti e il totale dei macro. */
function bowlState(food, params){
  const b = food.bowl;
  const baseFood = findFood(b.base), proteinFood = findFood(b.protein);
  const top = toppingState(params);
  const baseG = clamp(params.baseG || baseFood.def, baseFood.min, baseFood.max);
  const proteinG = clamp(params.proteinG || proteinFood.def, proteinFood.min, proteinFood.max);
  const parts = [calcForGrams(baseFood, baseG), calcForGrams(proteinFood, proteinG)];
  top.list.forEach(x=> parts.push(calcForGrams(x.food, x.g)));
  const totals = parts.reduce((a,p)=>({kcal:a.kcal+p.kcal, p:a.p+p.p, c:a.c+p.c, f:a.f+p.f, price:a.price+p.price}),
                              {kcal:0,p:0,c:0,f:0,price:0});
  return {baseFood, baseG, proteinFood, proteinG, top, totals};
}

/* Somma dei valori di più aggiunte ({food, g}) */
function sumCalc(list){
  return list.map(x=>calcForGrams(x.food, x.g)).reduce((a,p)=>({kcal:a.kcal+p.kcal, p:a.p+p.p, c:a.c+p.c, f:a.f+p.f, price:a.price+p.price}), {kcal:0,p:0,c:0,f:0,price:0});
}

/* Valori mostrati nella scheda (aggiornati anche muovendo grammatura o porzioni): li usa la card condivisibile */
let detailShare = null;

function renderDetail(params){
  const raw = findFood(params.id);
  if(!raw) return `<div class="empty-state">${uiT('common.foodNotFound','Alimento non trovato')}</div>`;
  if(raw.jar) return renderJar(params);   // proteine in barattolo (link vecchi, preferiti): la loro scheda
  // applico la variante (gusto delle proteine, cottura delle uova) se l'alimento ne ha
  const opt = detailOpt(raw, params);
  let food = effectiveFood(raw, opt);
  const isMeal = food.cat==='meal';
  const addon = ADDONS[raw.id];
  if(isMeal && addon) food = withAddon(food, params.addonQty);
  const isFixed = !!food.fixed;              // bevande e dolci: porzione non regolabile
  const isFav = STATE.favorites.has(food.id);
  const mode = params.mode || 'standalone'; // standalone | build | cart-edit
  const counted = !!food.unit;                // uova e pillole: si scelgono i pezzi
  const unitG = counted ? food.unit.g : 1;    // grammi per pezzo; 1 = si conta in grammi
  // eredito la grammatura solo se sto riaprendo lo stesso alimento, altrimenti uso il suo default
  const startGrams = detailStartGrams(raw, food, params);
  const qtyStart = startGrams / unitG;
  // Piatti pronti a taglie (es. nuggets 4/6/9 pezzi): una taglia sostituisce le porzioni,
  // non si sommano. Senza food.sizes un piatto pronto resta "porzioni" come sempre.
  const sizeChoice = isMeal && food.sizes ? (food.sizes.find(s=>s.id===params.size) || food.sizes[Math.floor(food.sizes.length/2)]) : null;
  // Unico piatto pronto con grammature libere (crema di riso proteica): tre alimenti veri,
  // tre quantità indipendenti, niente porzioni/taglie.
  const bowl = isMeal && food.bowl ? bowlState(food, params) : null;
  const sv = isMeal ? (params.servings||1) : 1;
  // Topping facoltativo su un alimento "semplice" (es. yogurt greco): la crema di riso proteica
  // lo gestisce già dentro bowl.top, qui serve solo per gli alimenti senza food.bowl.
  // (in «Crea il tuo pasto» il condimento non si aggiunge: il pasto composto non lo porterebbe nel carrello)
  // piatti a pezzi con condimento (polpette): il condimento si calibra sul peso della taglia scelta
  const topping = (!bowl && food.topping && params.mode !== 'build') ? toppingState(params, sizeChoice && sizeChoice.grams ? sizeChoice.grams : (params.grams || startGrams)) : null;
  // sui piatti pronti (porridge) il topping è per porzione: si moltiplica con le porzioni
  const toppingCalc = topping && topping.list.length ? (x=> ({kcal:x.kcal*sv, p:x.p*sv, c:x.c*sv, f:x.f*sv, price:x.price*sv}))(sumCalc(topping.list)) : null;
  const nBase = bowl ? bowl.totals
    : sizeChoice ? {kcal:sizeChoice.kcal,p:sizeChoice.p,c:sizeChoice.c,f:sizeChoice.f,fib:0,price:sizeChoice.price}
    : (isMeal || isFixed) ? {kcal:food.kcal*sv,p:food.p*sv,c:food.c*sv,f:food.f*sv,fib:0,price:food.price*sv} : calcForGrams(food, startGrams);
  const n = toppingCalc ? {kcal:nBase.kcal+toppingCalc.kcal, p:nBase.p+toppingCalc.p, c:nBase.c+toppingCalc.c, f:nBase.f+toppingCalc.f, price:nBase.price+toppingCalc.price} : nBase;

  const ctaLabel = mode==='build' ? uiT('detail.confirmInMeal','Conferma nel pasto') : params.editUid ? uiT('cart.update','Aggiorna nel carrello') : uiT('common.addToCart','Aggiungi al carrello');
  const photo = foodPhoto(food.id, opt);
  const fallbackGlyph = foodArtSvg(food.id, opt) || `<span class="glyph">${foodIcon(food,64)}</span>`;   // senza foto: il disegno dell'anteprima
  detailPhotoFallback = fallbackGlyph;
  const photoContent = photo
    ? `<img src="${photo}" alt="${esc(tName(food))}" data-fallback="detail">`
    : fallbackGlyph;
  // Per le porzioni fisse (bevande, integratori) la label deve mostrare la
  // porzione reale del prodotto (food.portion), non startGrams: quest'ultimo
  // vale 100 di default quando l'alimento non ha "def" (es. una lattina da
  // 330ml o una dose di creatina da 5g mostrerebbero erroneamente "100 g").
  const gramsLabel = bowl ? `${bowl.baseG+bowl.proteinG+bowl.top.toppingG} g`
    : sizeChoice ? (sizeChoice.count!=null ? `${sizeChoice.count} ${uiT('detail.pieces','pezzi')}` : `${sizeChoice.label} · ${sizeChoice.grams} g`)
    : isMeal ? `${params.servings||1} ${lcT((params.servings||1)===1?uiT('common.portion','Porzione'):uiT('common.portions','Porzioni'))}`
    : isFixed ? (food.portionText ? tPortionText(food) : `${food.portion}${food.cat==='drink'?' ml':' g'}`)
    : qtyLabel(food, startGrams);

  detailShare = {food, opt, n, label: gramsLabel};
  return `
    <div class="hero-arch-wrap h-${food.cat||'generic'}">
      ${heroCatChip(food.cat)}
      <button class="hero-share" data-action="share-food" aria-label="${uiT('share.send','Condividi')}">${iconSvg('share')}</button>
      <button class="heart-lg ${isFav?'active':''}" style="color:${isFav?'var(--protein)':'#1c1d22'}" data-action="fav" data-id="${food.id}">${heartLgIconSvg(isFav)}</button>
      <div class="hero-name-zone">
        <h1 class="hero-serif-name">${tName(food)}</h1>
        <div class="hero-cal-row">${flameIconSvg()}<span id="hero-cal-text">${fmt(n.kcal)} kcal · ${gramsLabel}</span></div>
      </div>
      <div class="hero-photo-circle${photo || foodArtSvg(food.id, opt) ? ' is-plate' : ''}" style="--plate-s:${plateScale(food, startGrams)}">${photoContent}</div>
      <div class="hero-price-pill" id="hero-price-pill">${fmtPrice(sellPriceOf(n.price, sv))}</div>
    </div>
    <p class="detail-desc" style="margin-top:16px;">${tDesc(food)||''}</p>
    ${compositionHtml(food)}

    ${(()=>{
      const conflicts = dietConflicts(food);
      if(!conflicts.length) return '';
      return `<div class="note-box" style="background:rgba(232,92,74,.12);color:var(--danger);font-weight:700;display:flex;align-items:center;gap:8px;">${iconSvg('warn')} <span>${uiT('diet.detailWarning','Non compatibile con le tue preferenze/allergie')}: ${conflicts.map(c=>c.label).join(' · ')}</span></div>`;
    })()}

    ${(()=>{
      const set = optionSetOf(raw);
      if(!set) return '';
      if(optionSetsOf(raw).length > 1) return optionPickersMulti(raw, opt, 'detail-option');
      if(set.kind === 'cards') return optionCards(set, opt, 'detail-option', raw.id);
      return optionSwatches({...set, label: uiT('dessert.flavor', set.label)}, opt, 'detail-option', null, raw.cat==='drink' ? raw.id : null);   // bevande (Monster): la lattina di ogni gusto
    })()}

    ${bowl ? `
      <div class="bowl-row">
        <div class="addon-block">
          <div class="ab-head"><span class="ab-label">${tName(bowl.baseFood)}</span></div>
          <div class="qty-controls">
            <button class="qty-btn" data-action="bowl-qty" data-part="base" data-delta="-1" ${bowl.baseG<=bowl.baseFood.min?'disabled':''}>${iconSvg('minus')}</button>
            <div class="qty-value"><span>${bowl.baseG} g</span></div>
            <button class="qty-btn" data-action="bowl-qty" data-part="base" data-delta="1" ${bowl.baseG>=bowl.baseFood.max?'disabled':''}>${iconSvg('plus')}</button>
          </div>
        </div>
        <div class="addon-block">
          <div class="ab-head"><span class="ab-label">${tName(bowl.proteinFood)}</span></div>
          <div class="qty-controls">
            <button class="qty-btn" data-action="bowl-qty" data-part="protein" data-delta="-1" ${bowl.proteinG<=bowl.proteinFood.min?'disabled':''}>${iconSvg('minus')}</button>
            <div class="qty-value"><span>${bowl.proteinG} g</span></div>
            <button class="qty-btn" data-action="bowl-qty" data-part="protein" data-delta="1" ${bowl.proteinG>=bowl.proteinFood.max?'disabled':''}>${iconSvg('plus')}</button>
          </div>
        </div>
      </div>
      ${toppingPickerHtml(food, bowl.top)}
    ` : isFixed ? `
      <div class="qty-block">
        <span class="qty-label">${uiT('common.portion','Porzione')}</span>
        <div class="fixed-portion">${food.portionText ? tPortionText(food) : `${food.portion}${food.cat==='drink'?' ml':' g'}`}</div>
      </div>
    ` : sizeChoice ? `
      <div class="addon-block">
        <div class="ab-head"><span class="ab-label">${uiT('common.portion','Porzione')}</span></div>
        <div class="ab-seg">
          ${food.sizes.map(s=>`
            <button class="ab-opt ${sizeChoice.id===s.id?'active':''}" data-action="meal-size" data-val="${s.id}">
              <span class="abo-n">${s.count!=null ? s.count : s.id}</span>
              <span class="abo-l">${s.count!=null ? uiT('detail.pieces','pezzi') : s.label}</span>
            </button>`).join('')}
        </div>
      </div>
    ` : isMeal ? `
      <div class="qty-block">
        <span class="qty-label">${uiT('common.portions','Porzioni')}</span>
        <div class="qty-controls">
          <button class="qty-btn" data-action="serv-dec">${iconSvg('minus')}</button>
          <div class="qty-value"><span id="serv-display">${params.servings||1}</span></div>
          <button class="qty-btn" data-action="serv-inc">${iconSvg('plus')}</button>
        </div>
      </div>
      ${addon ? (()=>{
        const cur = params.addonQty || addon.def;
        const opts = [];
        for(let n=addon.min; n<=addon.max; n++) opts.push(n);
        return `
        <div class="addon-block">
          <div class="ab-head">
            <span class="ab-label">${tAddonLabel(raw.id, addon)}</span>
            <span class="ab-price">${cur>addon.def ? '+'+fmtPrice(addon.price*(cur-addon.def)) : uiT('common.included','incluso')}</span>
          </div>
          <div class="ab-seg">
            ${opts.map(n=>`
              <button class="ab-opt ${cur===n?'active':''}" data-action="addon-set" data-val="${n}">
                <span class="abo-n">${n}</span>
                <span class="abo-l">${uiT('detail.patty','patty')}</span>
              </button>`).join('')}
          </div>
          <div class="ab-note">${tAddonNote(raw.id, addon)||''} · +${fmtPrice(addon.price)} ${uiT('detail.perExtraPatty','per patty aggiuntivo')}</div>
        </div>`;
      })() : ''}

    ` : `
      <div class="qty-block">
        <span class="qty-label">${counted ? uiT('common.quantity','Quantità') : uiT('detail.grams','Grammatura')}${food.raw ? ` <span class="qty-raw">· ${uiT('detail.rawWeight','peso a crudo')}</span>` : ''}</span>
        <div class="qty-controls">
          <button class="qty-btn" data-action="gr-dec">${iconSvg('minus')}</button>
          <div class="qty-value"><input id="gr-input" type="text" inputmode="numeric" value="${qtyStart}"><span class="unit" id="gr-unit">${counted ? tUnit(food, qtyStart) : 'g'}</span></div>
          <button class="qty-btn" data-action="gr-inc">${iconSvg('plus')}</button>
        </div>
        <input type="range" class="slider" id="gr-slider" min="${food.min/unitG}" max="${food.max/unitG}" step="${food.step/unitG}" value="${qtyStart}" style="--fill:${Math.round((qtyStart-food.min/unitG)/Math.max(1,(food.max-food.min)/unitG)*100)}%">
        <div class="range-minmax"><span>${counted ? qtyLabel(food, food.min) : food.min+'g'}</span><span>${counted ? qtyLabel(food, food.max) : food.max+'g'}</span></div>
        ${counted ? `<div class="qty-hint" id="gr-hint">≈ ${startGrams} g</div>` : ''}
      </div>
    `}
    ${toppingPickerHtml(food, topping)}

    ${foodNutriCardHtml(n)}
    ${food.crea ? `<p class="crea-source">${creaSourceHtml(food.crea)}</p>` : ''}

    ${groupForHtml()}
    <div class="detail-ctas">
      <button class="btn btn-primary btn-block" data-action="detail-confirm" data-mode="${mode}" data-slot="${params.slot||''}">${ctaLabel}</button>
    </div>
  `;
}

/* live-update handlers for detail view (no full re-render, per requisito "in tempo reale") */
/* Foto che non si carica: al suo posto l'icona vettoriale (delegato, senza onerror inline) */
let detailPhotoFallback = '';

document.addEventListener('error', (e)=>{
  const img = e.target;
  if(img && img.tagName==='IMG' && img.dataset.fallback==='detail' && detailPhotoFallback) img.outerHTML = detailPhotoFallback;
}, true);

function bindDetailControls(rawFood, mode, params){
  const food = effectiveFood(rawFood, detailOpt(rawFood, params));
  if(food.fixed) return;              // bevande e dolci: nessun controllo quantità
  const isMeal = food.cat==='meal';
  if(isMeal && food.sizes) return;    // taglie a pezzi (nuggets): un tocco su un riquadro rifà tutta la scheda, niente da legare qui
  if(isMeal && food.bowl) return;     // crema di riso proteica: ogni tocco su +/- o topping rifà tutta la scheda
  if(isMeal){
    let servings = params.servings || 1;
    const shown = withAddon(food, params.addonQty);   // include le unità extra scelte (es. patty aggiuntivi)
    const update = ()=>{
      document.getElementById('serv-display').textContent = servings;
      const top = food.topping ? toppingState(params) : null;   // topping per porzione (porridge): burro e sciroppo insieme
      const t = top && top.list.length ? sumCalc(top.list) : {kcal:0,p:0,c:0,f:0,price:0};
      const nServ = {kcal:(shown.kcal+t.kcal)*servings,p:(shown.p+t.p)*servings,c:(shown.c+t.c)*servings,f:(shown.f+t.f)*servings,price:(shown.price+t.price)*servings};
      document.getElementById('hero-cal-text').textContent = fmt(nServ.kcal)+' kcal · '+servings+' '+lcT(servings===1?uiT('common.portion','Porzione'):uiT('common.portions','Porzioni'));
      nServ.portions = servings;
      updateNutriDOM(nServ);
      params.servings = servings;
      if(detailShare) detailShare = {...detailShare, n:nServ, label:`${servings} ${lcT(servings===1?uiT('common.portion','Porzione'):uiT('common.portions','Porzioni'))}`};
    };
    document.querySelector('[data-action="serv-inc"]').onclick = ()=>{ servings = clamp(servings+1,1,5); update(); };

    document.querySelector('[data-action="serv-dec"]').onclick = ()=>{ servings = clamp(servings-1,1,5); update(); };
    return;
  }
  const slider = document.getElementById('gr-slider');
  const input = document.getElementById('gr-input');
  const k = food.unit ? food.unit.g : 1;                 // grammi per unità mostrata: 1 = grammi, 50 = uova
  const lo = food.min / k, hi = food.max / k, step = food.step / k;
  const applyQty = (q)=>{               // q è già dentro i limiti: aggiorna slider, testi, anello e valori
    const g = q * k;
    slider.value = q;
    slider.style.setProperty('--fill', Math.round((q-lo)/Math.max(1,hi-lo)*100)+'%');
    params.grams = g;
    const plate = document.querySelector('.hero-photo-circle.is-plate');
    if(plate) plate.style.setProperty('--plate-s', plateScale(food, g));
    const base = calcForGrams(food, g);
    // Topping facoltativo già scelto (es. yogurt greco + burro di arachidi): resta incluso
    // nel totale mostrato anche muovendo lo slider della sola grammatura dell'alimento.
    const top = food.topping ? toppingState(params, g) : null;
    const tCalc = top && top.list.length ? sumCalc(top.list) : null;
    // condimento automatico: i suoi grammi seguono quelli della pasta/riso
    if(top && top.auto){ const tg = document.getElementById('topping-g'); if(tg) tg.textContent = top.toppingG + ' g'; }
    const n = tCalc ? {kcal:base.kcal+tCalc.kcal, p:base.p+tCalc.p, c:base.c+tCalc.c, f:base.f+tCalc.f, price:base.price+tCalc.price} : base;
    document.getElementById('hero-cal-text').textContent = fmt(n.kcal)+' kcal · '+qtyLabel(food, g);
    if(food.unit){
      document.getElementById('gr-unit').textContent = tUnit(food, q);
      document.getElementById('gr-hint').textContent = '≈ '+g+' g';
    }
    updateNutriDOM(n);
    if(detailShare) detailShare = {...detailShare, n, label: qtyLabel(food, g)};
  };
  const setQty = (q)=>{ q = clamp(q, lo, hi); input.value = q; applyQty(q); };
  const typedQty = ()=> parseInt(input.value.replace(/[^0-9]/g,''),10);
  slider.addEventListener('input', ()=> setQty(+slider.value));
  /* Scrivendo, il campo non si riscrive: con il minimo a 50 g il «2» di «235» diventerebbe subito «50» e le cifre
     seguenti darebbero un altro numero. Anello e valori seguono ciò che è scritto, tenuto dentro i limiti;
     il campo si riallinea uscendo (blur). Sopra il massimo nessuna cifra in più lo renderebbe valido. */
  input.addEventListener('input', ()=>{
    const v = typedQty();
    if(isNaN(v)) return;
    if(v > hi) input.value = hi;
    applyQty(clamp(v, lo, hi));
  });
  input.addEventListener('blur', ()=> setQty(typedQty() || params.grams / k || food.def / k || lo));
  document.querySelector('[data-action="gr-inc"]').onclick = ()=> setQty(+slider.value + step);
  document.querySelector('[data-action="gr-dec"]').onclick = ()=> setQty(+slider.value - step);
}

function updateNutriDOM(n){
  [['n-kcal', n.kcal, 0, ''], ['n-p', n.p, 1, ' g'], ['n-c', n.c, 1, ' g'], ['n-f', n.f, 1, ' g']].forEach(([id, v, dec, suffix])=>{
    const el = document.getElementById(id);
    if(el) rollSet(el, (dec ? fmt(v,dec) : fmt(Math.round(v))) + suffix);
  });
  const pill = document.getElementById('hero-price-pill');
  if(pill) pill.textContent = fmtPrice(sellPriceOf(n.price, n.portions));   // n.portions: porzioni dei piatti pronti
  updateFoodRing(n);
}

/* Dettaglio dei prodotti configurabili: pancake (quantità) e gelato (gusto + coppetta).
   I dolci senza quantità regolabile (es. Cheesecake, Tiramisù) usano solo macro e porzione fisse. */
function dessertState(cfg){
  const d = findFood(cfg.id);
  let base;
  if(d.gelato){
    const flavor = GELATO_FLAVORS.find(f=>f.id===(cfg.flavor||GELATO_FLAVORS[0].id));
    const size = GELATO_SIZES.find(s=>s.id===(cfg.size||'100'));
    const r = size.grams/100;
    base = {food:d, name:`${tName(d)} · ${tFlavorName(flavor)}`, detail:`${size.grams} g`,
            kcal:flavor.kcal*r, p:flavor.p*r, c:flavor.c*r, f:flavor.f*r,
            price:+(d.price*r).toFixed(2), flavor, size};
  } else if(d.addon){
    const a = ADDONS[d.addon];
    const n = cfg.units || a.def;
    base = {food:d, name:tName(d), detail:`${n} ${tAddonUnit(d.addon, a, n)} · ${n*50} g`,
            kcal:a.kcal*n, p:a.p*n, c:a.c*n, f:a.f*n, price:+(a.price*n).toFixed(2), units:n, addon:a, addonKey:d.addon};
  } else {
    base = {food:d, name:tName(d), detail:`${d.portion} g`, kcal:d.kcal, p:d.p, c:d.c, f:d.f, price:d.price};
  }
  // Topping facoltativo (gelato e pancake proteici): stessi gruppi/logica della crema di riso
  // proteica (toppingState), sommato al totale e aggiunto alla descrizione della porzione.
  if(!d.topping) return base;
  const top = toppingState(cfg);
  // tutto ciò che si aggiunge: il topping e, per i pancake (come lo yogurt), anche lo sciroppo insieme al burro
  const adds = top.list.map(x=>({x, n:calcForGrams(x.food, x.g)}));
  const sum = k => adds.reduce((a, {n})=> a + n[k], 0);
  return {...base, top,
    detail: base.detail + adds.map(({x})=>` + ${tName(x.food)} ${qtyLabel(x.food, x.g)}`).join(''),
    kcal: base.kcal + sum('kcal'), p: base.p + sum('p'), c: base.c + sum('c'), f: base.f + sum('f'),
    price: +(base.price + sum('price')).toFixed(2)};
}

const GELATO_CUP_ICON = 'photos/coppetta.df546e0f4f.webp';
/* Coppetta del gelato: tre schede come quelle dei gusti, con la coppetta MACRO'S vuota in tre misure,
   grammi, calorie e prezzo di ogni formato */
function gelatoSizesHtml(d, s){
  const names = {'50':uiT('dessert.cupS','Piccola'), '100':uiT('dessert.cupM','Media'), '150':uiT('dessert.cupL','Grande')};
  return `<div class="swatch-block">
    <div class="sw-label">${uiT('dessert.cup','Coppetta')} <span class="sw-value">— ${s.size.label}</span></div>
    <div class="flavor-grid cup-grid" style="--cols:${GELATO_SIZES.length}">
      ${GELATO_SIZES.map((z, i)=>{
        const r = z.grams / 100;
        return `<button class="flavor-card ${s.size.id===z.id?'active':''}" data-action="dessert-size" data-val="${z.id}" style="--sw:var(--accent)">
          <span class="cup-pic"><img src="${GELATO_CUP_ICON}" alt="" draggable="false" style="--cup-s:${[.6,.8,1][i] || 1}"></span>
          <span class="fl-name">${names[z.id] || z.label}</span>
          <span class="cup-g">${z.label} · ${fmt(s.flavor.kcal * r)} kcal</span>
          <span class="cup-price">${fmtPrice(sellPrice(+(d.price * r).toFixed(2)))}</span>
        </button>`;
      }).join('')}
    </div>
  </div>`;
}

function renderDessert(params){
  const d = findFood(params.id);
  if(!d) return `<div class="empty-state"><p>${uiT('detail.productUnavailable','Prodotto non disponibile')}</p></div>`;
  const s = dessertState(params);

  const config = d.gelato ? `
    ${(()=>{
      const set = {label:uiT('dessert.flavor','Gusto'), choices:GELATO_FLAVORS.map(f=>({...f, sub:'', _flavorNS:'flavor'}))};
      return optionSwatches(set, s.flavor.id, 'dessert-flavor', null, d.gelato ? d.id : null);   // gelato: la coppa di ogni gusto al posto del pallino
    })()}
    ${gelatoSizesHtml(d, s)}
  ` : d.addon ? `
    <div class="qty-block">
      <span class="qty-label">${tAddonLabel(s.addonKey, s.addon)}</span>
      <div class="qty-controls">
        <button class="qty-btn" data-action="dessert-units" data-delta="-1" ${s.units<=s.addon.min?'disabled':''}>${iconSvg('minus')}</button>
        <div class="qty-value">${s.units}<span class="unit">${tAddonUnit(s.addonKey, s.addon, s.units)}</span></div>
        <button class="qty-btn" data-action="dessert-units" data-delta="1" ${s.units>=s.addon.max?'disabled':''}>${iconSvg('plus')}</button>
      </div>
      <div class="range-minmax"><span>min ${s.addon.min}</span><span>max ${s.addon.max}</span></div>
    </div>
    <div class="note-box">${tAddonNote(s.addonKey, s.addon)}</div>
  ` : '';

  return `
    <div class="hero-arch-wrap h-dessert">
      ${heroCatChip('dessert')}
      <div class="hero-name-zone">
        <h1 class="hero-serif-name">${s.name}</h1>
        <div class="hero-cal-row">${flameIconSvg()}<span>${fmt(s.kcal)} kcal · ${s.detail}</span></div>
      </div>
      ${(()=>{ const ph = foodPhoto(d.id, s.flavor && s.flavor.id); return `<div class="hero-photo-circle${ph ? ' is-plate' : ''}">${ph ? `<img src="${ph}" alt="${esc(tName(d))}">` : `<span class="glyph">${foodIconSvg(d.gelato?'porridge':d.addon?'bread':d.id,'var(--protein)',64)}</span>`}</div>`; })()}
      <div class="hero-price-pill">${fmtPrice(sellPrice(s.price))}</div>
    </div>
    <p class="detail-desc" style="margin-top:16px;">${tDesc(d)}</p>
    ${config}
    ${d.topping ? toppingPickerHtml(d, s.top) : ''}
    ${foodNutriCardHtml(s)}
    ${groupForHtml()}
    <div class="detail-ctas">
      <button class="btn btn-primary btn-block" data-action="dessert-add">${params.editUid ? uiT('cart.update','Aggiorna nel carrello') : uiT('common.addToCart','Aggiungi al carrello')}</button>
    </div>
  `;
}

function renderPortion(params){
  const f = findFood(params.id);
  if(!f) return `<div class="empty-state"><p>${uiT('common.productNotFound','Prodotto non trovato')}</p></div>`;
  const q = params.qty || 1;
  const pv = portionValues(f);
  const isDrink = f.cat==='drink';
  const v = {kcal:pv.kcal*q, p:pv.p*q, c:pv.c*q, f:pv.f*q, price:f.price*q};
  const unit = isDrink ? uiT('portion.bottle','bottiglia') : lcT(uiT('common.portion','Porzione'));
  const unitPl = isDrink ? uiT('portion.bottles','bottiglie') : lcT(uiT('common.portions','Porzioni'));

  return `
    <div class="hero-arch-wrap h-${f.cat||'generic'}">
      ${heroCatChip(f.cat)}
      <div class="hero-name-zone">
        <h1 class="hero-serif-name">${tName(f)}</h1>
        <div class="hero-cal-row">${flameIconSvg()}<span>${fmt(v.kcal)} kcal · ${q} ${q===1?unit:unitPl}</span></div>
      </div>
      ${(()=>{   // la foto se c'è (come nelle card e nella scheda alimento), altrimenti il disegno
        const ph = foodPhoto(f.id, params.opt);
        const art = foodArtSvg(f.id);
        return `<div class="hero-photo-circle${ph || art ? ' is-plate' : ''}">${ph ? `<img src="${ph}" alt="${esc(tName(f))}">` : (art || foodIcon(f,74))}</div>`;
      })()}
      <div class="hero-price-pill">${fmtPrice(sellPriceOf(v.price, q))}</div>
    </div>

    ${(()=>{   // bevanda con gusti (Monster): scelta del gusto, come nella scheda alimento
      const set = optionSetOf(f);
      return set ? optionSwatches({...set, label: uiT('dessert.flavor', set.label)}, params.opt || set.choices[0].id, 'portion-option', null, f.id) : '';
    })()}

    <div class="qty-block" style="margin-top:16px;">
      <span class="qty-label">${uiT('common.quantity','Quantità')} · ${f.portion}${isDrink?' ml':' g'} ${uiT('portion.per','a')} ${unit}</span>
      <div class="qty-controls">
        <button class="qty-btn" data-action="portion-qty" data-delta="-1" ${q<=1?'disabled':''}>${iconSvg('minus')}</button>
        <div class="qty-value"><span>${q}</span></div>
        <button class="qty-btn" data-action="portion-qty" data-delta="1" ${q>=10?'disabled':''}>${iconSvg('plus')}</button>
      </div>
      <div class="range-minmax"><span>${uiT('portion.total','totale')} ${fmt(f.portion*q)}${isDrink?' ml':' g'}</span><span>${fmtPrice(sellPrice(f.price))} ${uiT('portion.each','cad.')}</span></div>
    </div>

    ${foodNutriCardHtml(v)}
    ${f.crea ? `<p class="crea-source">${creaSourceHtml(f.crea)}</p>` : ''}

    ${groupForHtml()}
    <div class="detail-ctas">
      <button class="btn btn-primary btn-block" data-action="portion-add">${params.editUid ? uiT('cart.update','Aggiorna nel carrello') : uiT('common.addToCart','Aggiungi al carrello')}</button>
    </div>
  `;
}

/* Il piatto nella testata cresce appena con la grammatura (solo visivo): dal 94% al minimo al 104% al massimo */
function plateScale(food, g){
  if(!food || !(food.max > food.min)) return 1;
  const t = Math.min(1, Math.max(0, (g - food.min) / (food.max - food.min)));
  return (0.94 + t * 0.10).toFixed(3);
}

/* Azioni dei pulsanti (data-action) */
defineActions({
  'detail-option'(el){
    replaceView('detail', {...current(), opt:el.dataset.opt}, true);
  },
  'addon-set'(el){
    const cur = current();
    const a = ADDONS[cur.id];
    if(!a) return;
    cur.addonQty = clamp(+el.dataset.val, a.min, a.max);
    render();
  },
  'portion-qty'(el){
    const cur = current();
    cur.qty = clamp((cur.qty||1) + (+el.dataset.delta), 1, 10);
    render();
  },
  'portion-option'(el){ replaceView('portion', {...current(), opt:el.dataset.opt}, true); },
  'portion-add'(){
    const cur = current();
    const f = findFood(cur.id);
    if(!f) return;
    const q = cur.qty || 1;
    const pv = portionValues(f);
    const set = optionSetOf(f), ch = set && (set.choices.find(x=>x.id===cur.opt) || set.choices[0]);   // gusto scelto (Monster)
    const label = ch ? tPFlavorName(ch) : tName(f);
    STATE.cart.push({uid:'u'+(uidCounter++), kind:'fixed', foodId:f.id, label, opt: ch ? ch.id : undefined, qty:q,
                     kcal:pv.kcal, p:pv.p, c:pv.c, f:pv.f, price:f.price});
    toast(`${label}${q>1?' × '+q:''} ${uiT('toast.addedToCart','aggiunto al carrello')}`);
    cartAddDone(cur);
  },
  'add-fixed'(el){
    const f = findFood(el.dataset.id);
    if(!f) return;
    if(f.cat==='dessert'){ navigateTo('dessert', {id:f.id}); return; }
    if(optionSetOf(f)){ navigateTo('detail', {id:f.id}); return; }   // bevanda con gusti (Monster): si sceglie nella scheda
    const pv = portionValues(f);
    STATE.cart.push({uid:'u'+(uidCounter++), kind:'fixed', foodId:f.id, label:tName(f),
                     kcal:pv.kcal, p:pv.p, c:pv.c, f:pv.f, price:f.price});
    toast(tName(f) + ' '+uiT('toast.addedToCart','aggiunto al carrello'));
    render();
  },
  'meal-size'(el){ replaceView('detail', {...current(), size:el.dataset.val}, true); },
  'bowl-qty'(el){
    const cur = current();
    const food = findFood(cur.id);
    const part = el.dataset.part; // base | protein
    const key = part==='base' ? 'baseG' : 'proteinG';
    const refId = part==='base' ? food.bowl.base : food.bowl.protein;
    const ref = findFood(refId);
    const from = cur[key] || ref.def;
    const next = clamp(from + (+el.dataset.delta)*ref.step, ref.min, ref.max);
    replaceView('detail', {...cur, [key]:next}, true);
  },
  /* Topping facoltativo: condiviso da tutti gli alimenti con food.topping (crema di riso
     proteica, yogurt greco, gelato e pancake proteici) — funziona sia in 'detail' che in
     'dessert' restando sulla vista corrente (current().view). */
  'topping-open'(){ replaceView(current().view, {...current(), toppingOpen:true}, true); },
  'topping-close'(){ replaceView(current().view, {...current(), toppingOpen:false}, true); },
  // nuovo condimento: la grammatura riparte automatica (toppingG azzerato)
  'topping-pick'(el){
    // un secondo tocco sul topping già scelto lo toglie (lo sciroppo eventualmente scelto resta, il riquadro resta aperto)
    const entry = current();
    const again = el.dataset.val !== 'none' && entry.toppingId === el.dataset.val;
    const cur = {...entry, toppingId: again ? 'none' : el.dataset.val}; delete cur.toppingG;
    // dopo l'animazione si ridisegna solo se si è ancora su questa scheda (con «indietro» nel frattempo la schermata
    // in cima sarebbe un'altra, e verrebbe sostituita dalla scheda del dolce)
    const go = ()=>{ if(current() === entry) replaceView(cur.view, cur, true); };
    if(again) cur.toppingOpen = true;
    else if(el.dataset.val !== 'none') return go();
    else delete cur.syrupId;
    // «Nessuno» o secondo tocco: il riquadro della quantità si richiude con l'animazione inversa, poi la scheda si ridisegna
    const q = document.querySelector('.topping-qty');
    const reduced = window.matchMedia && matchMedia('(prefers-reduced-motion: reduce)').matches;
    if(!q || reduced) return go();
    q.classList.remove('tq-in'); q.classList.add('tq-out');
    setTimeout(go, 260);
  },
  // sciroppo zero insieme al burro (yogurt, crema di riso): un secondo tocco lo toglie
  'syrup-pick'(el){ const cur = {...current()}; if(cur.syrupId === el.dataset.val) delete cur.syrupId; else cur.syrupId = el.dataset.val; replaceView(cur.view, cur, true); },
  'topping-qty'(el){
    const cur = current();
    const baseFood = findFood(cur.id);
    const top = toppingState(cur, cur.grams || (baseFood && baseFood.def));
    if(!top.toppingFood || top.toppingFixed) return; // topping a porzione fissa: niente stepper
    const next = clamp((cur.toppingG || top.toppingG || top.toppingFood.def) + (+el.dataset.delta)*top.toppingFood.step, top.toppingFood.min, top.toppingFood.max);
    replaceView(cur.view, {...cur, toppingG:next}, true);
  },
  'dessert-flavor'(el){ replaceView('dessert', {...current(), flavor:el.dataset.opt}, true); },
  'dessert-size'(el){ replaceView('dessert', {...current(), size:el.dataset.val}, true); },
  'dessert-units'(el){
    const cur = current();
    const a = ADDONS[findFood(cur.id).addon];
    const n = clamp((cur.units || a.def) + (+el.dataset.delta), a.min, a.max);
    replaceView('dessert', {...cur, units:n}, true);
  },
  'dessert-add'(){
    const entry = current();
    const s = dessertState(entry);
    // dessert: le scelte (gusto, formato, pezzi, topping) per poter ricalcolare il prezzo (ordine di gruppo, pagamento online)
    const dessert = {...(s.flavor ? {flavor:s.flavor.id} : {}), ...(s.size ? {size:s.size.id} : {}), ...(s.units ? {units:s.units} : {}),
                     ...(s.top && s.top.toppingFood ? {top:{foodId:s.top.toppingFood.id, grams:s.top.toppingG}} : {}),
                     ...(s.top && s.top.syrupFood ? {syrup:{foodId:s.top.syrupFood.id, grams:s.top.syrupG}} : {})};
    STATE.cart.push({uid:'u'+(uidCounter++), kind:'fixed', foodId:s.food.id, dessert,
                     label:`${s.name} · ${s.detail}`, kcal:s.kcal, p:s.p, c:s.c, f:s.f, price:s.price});
    toast(s.name + ' '+uiT('toast.addedToCart','aggiunto al carrello'));
    cartAddDone(entry);
  },
  'detail-confirm'(){
    const c = current();
    const raw = findFood(c.id);
    const opt = detailOpt(raw, c);
    const food = effectiveFood(raw, opt);
    if(food.fixed){
      // prodotto a porzione fissa (bevanda, Intra Workout) aperto dalla ricerca o dai preferiti: stessa voce di
      // 'add-fixed' — con il codice del prodotto (il server lo deve poter prezzare) e i valori della porzione, non per 100 ml
      const pv = portionValues(food);
      const set = optionSetOf(raw), ch = set && set.choices.find(x=>x.id===opt);   // gusto scelto (Monster) nel nome della voce
      const label = ch ? tPFlavorName(ch) : tName(food);
      STATE.cart.push({uid:'u'+(uidCounter++), kind:'fixed', foodId:food.id, label, opt: ch ? ch.id : undefined,
                       kcal:pv.kcal, p:pv.p, c:pv.c, f:pv.f, price:food.price});
      toast(label + ' '+uiT('toast.addedToCart','aggiunto al carrello'));
      cartAddDone(c);
      return;
    }
    if(food.cat==='meal' && food.sizes){
      const size = food.sizes.find(s=>s.id===c.size) || food.sizes[Math.floor(food.sizes.length/2)];
      const top = food.topping ? toppingState(c, size.grams) : null;
      if(top && top.toppingFood) addSizedMealWithToppingToCart(food, size, top);
      else addSizedMealToCart(food, size);
      cartAddDone(c);
      return;
    }
    if(food.cat==='meal' && food.bowl){
      addBowlToCart(food, bowlState(food, c));
      cartAddDone(c);
      return;
    }
    if(food.cat==='meal'){
      const top = food.topping ? toppingState(c) : null;
      if(top && top.list.length) addMealWithToppingToCart(food, c.servings||1, top);
      else addMealToCart(withAddon(food, c.addonQty), c.servings||1, c.addonQty);
      cartAddDone(c);
      return;
    }
    const g = detailStartGrams(raw, food, c);   // la grammatura mostrata: quella scelta, o quella già nel pasto
    if(c.mode==='build' && c.slot && inMealBuilder()){
      // pasto della Weekly Box o del Piano pasti: stesso menu e stesso dettaglio di un ordine normale
      STATE.mealPlanBuilder = STATE.mealPlanBuilder || {carb:null, protein:null, fat:null, extras:[]};
      STATE.mealPlanBuilder[c.slot] = {foodId: food.id, grams: g, opt};
      toast(tName(food) + ' '+uiT('toast.addedToMeal','aggiunto al pasto'));
      returnToMealBuilder();
    } else if(c.mode==='build' && c.slot){
      STATE.build[c.slot] = {foodId: food.id, grams: g, opt};
      toast(tName(food) + ' '+uiT('toast.addedToMeal','aggiunto al pasto'));
      // passo successivo: la categoria ancora vuota, sempre dentro il pasto (buildSlot: la scelta va nel pasto,
      // non nel carrello come alimento singolo); con carboidrato, proteina e grasso scelti si torna al riepilogo
      const order = ['carb','protein','fat'];
      const next = order.find(k=>!STATE.build[k]);
      STATE.stack = next ? [{view:'build'}, {view:'menu', cat: next, buildSlot: next}] : [{view:'build'}];
      render();
      window.scrollTo({top:0});
    } else {
      // Topping facoltativo su un alimento semplice (es. yogurt greco): se è stato scelto un
      // topping vero la voce va nel carrello come "composta" (etichetta con l'elenco), stesso
      // pattern della crema di riso proteica; senza topping resta il flusso normale.
      const top = food.topping ? toppingState(c, g) : null;
      if(top && top.list.length) addSingleWithToppingToCart(food, g, top);
      else addSingleToCart(food, g, opt);
      cartAddDone(c);
    }
  },
});

/* Proteine in barattolo: gusto, formato (900 g / 2 kg), valori per dose, aminoacidi, brevetti */

/* Scelte della scheda (gusto e formato), sempre valide anche se arrivano da un link vecchio */
function jarState(params){
  const food = findFood(params.id);
  const flavor = food.flavors.includes(params.flavor) ? params.flavor : (food.flavors[0] || null);
  const packs = jarPacks(food);
  const size = packs.find(z=>z.id===params.size) || packs[0];
  const price = food.prices[size.id];
  return {food, flavor, size, price: price > 0 ? price : null, doses: jarDoses(food, size)};
}

/* Formati in vendita: le proteine 900 g / 2 kg (JAR_SIZES), vitamine e minerali la loro confezione (packs) */
function jarPacks(food){ return food.packs || JAR_SIZES.filter(z=>!food.jarSizes || food.jarSizes.includes(z.id)); }
function jarPackOf(food, id){ const ps = jarPacks(food); return ps.find(z=>z.id===id) || ps[0]; }
function jarDoses(food, z){ return z.doses || Math.floor(z.grams / food.dose); }

/* Unità delle confezioni (compressa, capsula...), al singolare o al plurale, nella lingua dell'app */
const PACK_UNITS = {compressa:['compressa','compresse'], capsula:['capsula','capsule'], tavoletta:['tavoletta','tavolette'],
                    bustina:['bustina','bustine'], gommosa:['caramella gommosa','caramelle gommose']};
function packUnit(unit, n){ if(unit === 'g' || unit === 'kg') return unit; const u = PACK_UNITS[unit]; return uiT('packunit.'+unit+(n===1?'.one':'.many'), n===1 ? u[0] : u[1]); }
function jarPackLabel(food, z){ return z.label || `${z.count} ${packUnit(z.unit, +z.count)}`; }
/* Icona del formato: barattolo per le polveri, pillola per compresse e capsule, bustina, caramella */
function jarPackIcon(food, z){
  const u = z.unit || 'g';
  return iconSvg(u === 'g' || u === 'kg' ? 'jarpack' : u === 'bustina' ? 'sachet' : u === 'gommosa' ? 'gummy' : 'pill');
}
/* Integratori in polvere (barattoli in grammi, proteine comprese): la dicitura «Qualità Premium» li distingue dalle capsule */
function jarIsPowder(food){ return !!food.jar && (!food.packs || food.packs.some(z=>z.unit === 'g' || z.unit === 'kg')); }
function premiumBadgeHtml(food, cls){ return jarIsPowder(food) ? `<span class="${cls}">${iconSvg('star')}${uiT('jar.premium','Qualità Premium')}</span>` : ''; }
/* La dose: «30 g» per le polveri, «2 capsule» per vitamine e minerali */
function jarDoseText(food){ return food.packs ? `${food.doseN} ${packUnit(food.doseUnit, food.doseN)}` : `${food.dose} g`; }

/* Nome dell'aminoacido nella lingua dell'app (la chiave è il nome italiano senza «L-») */
function aminoName(it){ const k = it.replace(/^L-/, '').toLowerCase().replace(/[^a-z]/g, ''); return uiT('amino.'+k, it); }

/* Nome di vitamina o minerale nella lingua dell'app («di cui …» resta come sottovoce) */
function nutrientName(n){
  const sub = /^di cui /.test(n), base = sub ? n.slice(7) : n;
  const k = base.toLowerCase().normalize('NFD').replace(/[^a-z0-9]/g, '');
  const t = /^L-[A-Za-z]+$/.test(base) ? aminoName(base) : uiT('nutr.'+k, base);
  return sub ? uiT('jar.ofWhich','di cui {x}').replace('{x}', t) : t;
}

function jarFlavorName(id){ return tPFlavorName({id, name: JAR_FLAVORS[id]}); }

/* Prezzo più basso tra i formati (per la card del menu); null se nessun formato ha ancora un prezzo */
function jarFromPrice(food){
  const ps = jarPacks(food).map(z=>food.prices[z.id]).filter(p=>p > 0);
  return ps.length ? Math.min(...ps) : null;
}

function jarLabel(food, jar){
  return [tName(food), jar.flavor ? jarFlavorName(jar.flavor) : '', jarPackLabel(food, jarPackOf(food, jar.size))].filter(Boolean).join(' · ');
}

/* Formato: schede compatte con l'icona della confezione (barattolo, pillola, bustina), peso o quantità, dosi,
   prezzo e costo a dose; sul formato più grande il risparmio a dose quando conviene */
function jarSizesHtml(f, s){
  const packs = jarPacks(f);
  const perDose = z=>{ const p = f.prices[z.id]; return p > 0 ? p / jarDoses(f, z) : null; };
  const small = perDose(packs[0]);
  return `<div class="swatch-block jar-size-block">
    <div class="sw-label">${uiT('jar.size','Formato')} <span class="sw-value">— ${jarPackLabel(f, s.size)}</span></div>
    <div class="jar-sizes${packs.length === 1 ? ' single' : ''}">
      ${packs.map((z, i)=>{
        const p = f.prices[z.id], doses = jarDoses(f, z), pd = perDose(z);
        const save = i > 0 && small && pd && pd < small ? Math.round((1 - pd / small) * 100) : 0;
        return `<button class="jar-size-opt ${s.size.id===z.id ? 'active' : ''}" data-action="jar-size" data-val="${z.id}">
          <span class="jz-ic">${jarPackIcon(f, z)}</span>
          <span class="jz-txt"><span class="jz-w">${jarPackLabel(f, z)}</span><span class="jz-doses">${uiT('jar.dosesShort','{n} dosi').replace('{n}', doses)}${pd ? ` · ${fmtPrice(pd)} ${uiT('jar.perServing','a dose')}` : ''}</span></span>
          <span class="jz-end">${save ? `<span class="jz-badge">−${save}%</span>` : ''}<span class="jz-price">${p > 0 ? fmtPrice(p) : uiT('jar.priceTbd','Prezzo da definire')}</span></span>
        </button>`;
      }).join('')}
    </div>
    <div class="sw-sub">${f.howTo ? (i18nLookup(f.id, 'howto') || f.howTo) : uiT('jar.howTo','{g} g in {ml} ml di acqua o latte').replace('{g}', f.dose).replace('{ml}', f.doseMl)}</div>
  </div>`;
}

function renderJar(params){
  const f = findFood(params.id);
  if(!f || !f.jar) return `<div class="empty-state"><p>${uiT('detail.productUnavailable','Prodotto non disponibile')}</p></div>`;
  const s = jarState(params);
  const photo = foodPhoto(f.id, s.flavor);
  const flavorSet = {label: uiT('dessert.flavor','Gusto'), choices: f.flavors.map(id=>({id, name: JAR_FLAVORS[id], sub:''}))};
  const row = (l, v, sub)=>`<div class="jar-row${sub ? ' sub' : ''}"><span>${l}</span><b>${v}</b></div>`;
  return `
    <div class="hero-arch-wrap h-supplement">
      ${heroCatChip(f.cat)}
      <div class="hero-name-zone">
        <h1 class="hero-serif-name">${tName(f)}</h1>
        ${premiumBadgeHtml(f, 'prem-pill')}
        <div class="hero-cal-row">${f.packs ? `<span>${uiT('jar.dailyDose','Dose giornaliera: {d}').replace('{d}', jarDoseText(f))}</span>` : `${flameIconSvg()}<span>${fmt(f.kcal)} kcal · ${uiT('jar.perDose','dose da {g} g').replace('{g}', f.dose)}</span>`}</div>
      </div>
      <div class="hero-photo-circle${photo ? ' is-plate' : ''}">${photo ? `<img src="${photo}" alt="${esc(tName(f))}">` : foodIcon(f, 74)}</div>
      <div class="hero-price-pill">${s.price ? fmtPrice(s.price) : uiT('jar.priceTbd','Prezzo da definire')}</div>
    </div>
    <p class="detail-desc" style="margin-top:16px;">${tDesc(f)}</p>

    ${f.flavors.length > 1 ? optionSwatches(flavorSet, s.flavor, 'jar-flavor', null, f.id) : ''}

    ${jarSizesHtml(f, s)}

    ${f.packs ? `
    <div class="jar-table">
      <div class="jar-title">${uiT('jar.perDoseTitle','Valori per dose giornaliera ({d})').replace('{d}', jarDoseText(f))}</div>
      ${f.nutrients.map(([n, v, vnr])=>`<div class="jar-row${/^di cui /.test(n) ? ' sub' : ''}"><span>${nutrientName(n)}</span><b>${v}${vnr ? ` <em class="jar-vnr">${vnr} ${uiT('jar.vnr','VNR')}</em>` : ''}</b></div>`).join('')}
    </div>` : `
    ${foodNutriCardHtml({kcal:f.kcal, p:f.p, c:f.c, f:f.f})}

    <div class="jar-table">
      <div class="jar-title">${uiT('jar.nutriTitle','Valori nutrizionali per dose ({g} g)').replace('{g}', f.dose)}</div>
      ${row(uiT('jar.energy','Energia'), `${fmt(f.kcal)} kcal`)}
      ${row(uiT('jar.fat','Grassi'), `${fmt(f.f,1)} g`)}${row(uiT('jar.sat','di cui saturi'), `${fmt(f.sat,1)} g`, true)}
      ${row(uiT('jar.carbs','Carboidrati'), `${fmt(f.c,1)} g`)}${row(uiT('jar.sugar','di cui zuccheri'), `${fmt(f.sugar,1)} g`, true)}
      ${row(uiT('jar.protein','Proteine'), `${fmt(f.p,1)} g`)}
      ${row(uiT('jar.salt','Sale'), `${fmt(f.salt,2)} g`)}
      ${f.extras.map(([l, v])=>row(l === 'Vitamina B6' ? uiT('jar.b6','Vitamina B6') : l, v)).join('')}
    </div>`}

    ${f.aminos ? `<div class="jar-table">
      <div class="jar-title">${uiT('jar.aminoTitle','Profilo amminoacidico (per 100 g)')}</div>
      <div class="jar-amino">${f.aminos.map(([n, g])=>row(aminoName(n), `${fmt(g, 2)} g`)).join('')}</div>
    </div>` : ''}

    ${f.patents.length ? `<div class="jar-table">
      <div class="jar-title">${uiT('jar.patents','Brevetti e materie prime')}</div>
      <div class="jar-patents">${f.patents.map(p=>`<span class="jar-patent">${p}</span>`).join('')}</div>
    </div>` : ''}

    ${groupForHtml()}
    <div class="detail-ctas">
      ${s.price
        ? `<button class="btn btn-primary btn-block" data-action="jar-add">${params.editUid ? uiT('cart.update','Aggiorna nel carrello') : uiT('common.addToCart','Aggiungi al carrello')}</button>`
        : `<button class="btn btn-primary btn-block" disabled>${uiT('jar.soon','Presto disponibile')}</button>`}
    </div>
  `;
}

/* Azioni dei pulsanti (data-action) */
defineActions({
  'jar-flavor'(el){ replaceView('jar', {...current(), flavor:el.dataset.opt}, true); },
  'jar-size'(el){ replaceView('jar', {...current(), size:el.dataset.val}, true); },
  'jar-add'(){
    const entry = current();
    const s = jarState(entry);
    if(!s.price) return;
    // il barattolo non si mangia tutto in una volta: niente macro nel carrello né nel diario
    const jar = {size: s.size.id, ...(s.flavor ? {flavor: s.flavor} : {})};
    STATE.cart.push({uid:'u'+(uidCounter++), kind:'fixed', foodId:s.food.id, jar, label: jarLabel(s.food, jar),
                     kcal:0, p:0, c:0, f:0, price:s.price});
    toast(tName(s.food) + ' '+uiT('toast.addedToCart','aggiunto al carrello'));
    cartAddDone(entry);
  },
});

/* Componi il tuo pasto */

function renderBuild(){
  const b = STATE.build;
  const slotInfo = (key,label)=>{
    const chosen = b[key];
    if(!chosen) return {label:uiT('build.choose','Scegli')+' '+label, val:'', empty:true};
    const f = effectiveFood(findFood(chosen.foodId), chosen.opt);
    return {label, val:`${tName(f)} · ${qtyLabel(f, chosen.grams)}`, empty:false};
  };
  const carbInfo = slotInfo('carb',uiT('build.aCarb','un carboidrato'));
  const protInfo = slotInfo('protein',uiT('build.aProtein','una proteina'));
  const fatInfo  = slotInfo('fat',uiT('build.aFat','un grasso'));
  const t = buildTotals();
  const canAdd = b.carb || b.protein || b.fat;

  return `
    <div class="section" style="margin-top:16px;">
      <h2 style="font-size:24px;">${uiT('build.title','Componi il tuo pasto')}</h2>
      <p style="color:var(--muted);font-size:13px;margin-top:4px;">${uiT('build.sub','Componi il tuo pasto, uno step alla volta.')}</p>
    </div>

    ${buildSlotRow('carb', '1 · '+uiT('build.stepCarb','Carboidrato'), carbInfo, 'rice')}
    ${buildSlotRow('protein', '2 · '+uiT('build.stepProtein','Proteina'), protInfo, 'chicken')}
    ${buildSlotRow('fat', '3 · '+uiT('build.stepFat','Grasso'), fatInfo, 'avocado')}

    <div class="build-slot">
      <div class="bs-main" data-action="menutab" data-cat="veg">
      <div class="ic" style="background:${DIMS.fat}">${foodIconSvg('salad','var(--fat)',24)}</div>
      <div class="body">
        <div class="step-lbl">4 · ${uiT('build.stepExtras','Aggiunte')}</div>
        <div class="step-val ${b.extras.length?'':'empty'}">${b.extras.length? b.extras.length+' '+(b.extras.length===1?uiT('build.oneAdded','aggiunta'):uiT('build.moreAdded','aggiunte')) : uiT('build.extrasEmpty','Verdura, frutta o salse')}</div>
        <div class="extra-chips-row">${b.extras.map(id=>{const e=EXTRAS.find(x=>x.id===id); return e?`<span class="extra-chip active">${tName(e)}</span>`:'';}).join('')}</div>
      </div>
      </div>
      ${b.extras.length
        ? `<button class="bs-clear" data-action="clear-slot" data-slot="extras" title="${uiT('common.remove','Rimuovi')}">${iconSvg('close')}</button>`
        : `<span class="chev">${iconSvg('chev')}</span>`}
    </div>

    <div class="build-slot">
      <div class="bs-main" data-action="menutab" data-cat="drink">
      <div class="ic" style="background:${DIMS.carb}">${foodIconSvg('jar','var(--carb)',24)}</div>
      <div class="body">
        <div class="step-lbl">5 · ${uiT('build.stepDrink','Bevanda')}</div>
        <div class="step-val ${(b.drinks||[]).length?'':'empty'}">${(b.drinks||[]).length? (b.drinks.length===1?uiT('build.oneDrink','1 bevanda selezionata'):b.drinks.length+' '+uiT('build.moreDrinks','bevande selezionate')) : uiT('build.drinkEmpty','Aggiungi una bevanda')}</div>
        <div class="extra-chips-row">${(b.drinks||[]).map(id=>{const d=DRINKS.find(x=>x.id===id); return d?`<span class="extra-chip active">${tName(d)}</span>`:'';}).join('')}</div>
      </div>
      </div>
      ${(b.drinks||[]).length
        ? `<button class="bs-clear" data-action="clear-slot" data-slot="drinks" title="${uiT('common.remove','Rimuovi')}">${iconSvg('close')}</button>`
        : `<span class="chev">${iconSvg('chev')}</span>`}
    </div>

    ${mealSummaryHtml(t)}
    ${(()=>{
      const pm = perMealTargets();
      const fit = evaluateMacroFit(t.kcal, t.p, t.c, t.f);
      const sugg = generateSmartSuggestions(t, b);   // utili soprattutto a pasto ancora vuoto
      return `
        <div class="fit-card" style="background:${fit.bg}">
          <div class="fit-head">
            <span class="fit-dot" style="background:${fit.color}"></span>
            <span class="fit-tag" style="color:${fit.color}">${fit.tag}</span>
          </div>
          <div class="fit-desc">${fit.desc}</div>
          ${t.kcal>0 && userHasOwnMacros() ? `<div class="fit-contrib">
            ${uiT('fit.vsTypical','Rispetto al tuo pasto tipo')} (<b>${fmt(pm.kcal)} kcal</b>): <b>${Math.round(t.kcal/Math.max(pm.kcal,1)*100)}%</b> ${uiT('fit.ofCalories','delle calorie')}, <b>${Math.round(t.p/Math.max(pm.p,1)*100)}%</b> ${uiT('fit.ofProtein','delle proteine')}
          </div>` : ''}
        </div>
        ${sugg.length ? `<div class="sugg-list">${sugg.map(s=>`
          <button class="sugg-card" data-action="apply-sugg" data-slot="${s.slot}" data-id="${s.food.id}" data-grams="${s.grams}">
            <div class="sg-ic" style="background:${thumbBg(s.food.cat)}">${foodIcon(s.food,22)}</div>
            <div class="sg-body">
              <div class="sg-title">${s.label}</div>
              <div class="sg-sub">${suggQtyText(s.food, s.grams)} · ${s.macroTxt}</div>
            </div>
            <span class="sg-plus">${iconSvg('plus')}</span>
          </button>`).join('')}</div>` : ''}
      `;
    })()}
    <button class="btn btn-primary btn-block" style="margin-top:14px;" data-action="build-add" ${canAdd?'':'disabled'}>${uiT('common.addToCart','Aggiungi al carrello')}</button>
  `;
}

function buildSlotRow(key, label, info, iconType){
  const colorVar = {carb:'var(--carb)', protein:'var(--protein)', fat:'var(--fat)'}[key] || 'var(--ink)';
  return `<div class="build-slot">
    <div class="bs-main" data-action="buildslot" data-slot="${key}">
      <div class="ic" style="background:${DIMS[key]}">${foodIconSvg(iconType, colorVar, 24)}</div>
      <div class="body">
        <div class="step-lbl">${label}</div>
        <div class="step-val ${info.empty?'empty':''}">${info.empty?info.label:info.val}</div>
      </div>
    </div>
    ${info.empty
      ? `<span class="chev">${iconSvg('chev')}</span>`
      : `<button class="bs-clear" data-action="clear-slot" data-slot="${key}" title="${uiT('common.remove','Rimuovi')}">${iconSvg('close')}</button>`}
  </div>`;
}

function renderExtras(){
  return `
    <h2 style="font-size:22px;margin-top:16px;">${uiT('extras.title','Scegli gli extra')}</h2>
    <p style="color:var(--muted);font-size:13px;margin:4px 0 18px;">${uiT('extras.hint','Tocca per aggiungere o rimuovere.')}</p>
    <div class="grid-2">
      ${EXTRAS_MENU.map(e=>{
        const active = STATE.build.extras.includes(e.id);
        return `<div class="food-card ${active?'picked':''}" data-action="toggle-extra" data-id="${e.id}">
          <div class="food-thumb h-${e.cat}">
            <span class="fp">${foodPreview(e)}</span>
            ${active?`<span class="picked-badge">${iconSvg('check')}</span>`:''}
          </div>
          ${foodInfoHtml(e, portionValues(e), `${fmt(portionValues(e).kcal)} kcal · ${e.portion}g`, fmtPrice(sellPrice(e.price)))}
        </div>`;
      }).join('')}
    </div>
    <button class="btn btn-dark btn-block" style="margin-top:20px;" data-action="tab" data-view="menu">${uiT('common.done','Fatto')}</button>
  `;
}

/* Azioni dei pulsanti (data-action) */
defineActions({
  'buildslot'(el){
    const slot = el.dataset.slot;
    navigateTo('menu', {cat: slot, buildSlot: slot});
  },
  'clear-slot'(el){
    const k = el.dataset.slot;
    if(k==='extras'){ STATE.build.extras = []; }
    else if(k==='drinks'){ STATE.build.drinks = []; }
    else { STATE.build[k] = null; }
    toast(uiT('toast.removedFromMeal','Rimosso dal pasto'));
    render();
  },
  'toggle-drink'(el){ navigateTo('portion', {id:el.dataset.id, qty:1}); },
  'toggle-extra'(el){ navigateTo('portion', {id:el.dataset.id, qty:1}); },
  'build-add'(){ addBuildToCart(); goToTab('cart'); },
});

/* Carrello, riordino, combinazioni salvate e scheda da condividere */

function reorderItems(cartSnapshot){
  if(!cartSnapshot || !cartSnapshot.length) return;
  const ok = cartSnapshot.filter(cartItemKnown);   // prodotti tolti dal menu dopo l'ordine: non si possono più ordinare
  ok.forEach(it=>{ STATE.cart.push({uid:'u'+(uidCounter++), ...it}); });
  toast(ok.length === cartSnapshot.length ? uiT('toast.reordered','Aggiunto al carrello')
    : uiT('toast.itemsUnavailable','Alcuni prodotti non sono più nel menu: abbiamo aggiunto gli altri'));
  saveState();
}

/* ---------------- COMBINAZIONI SALVATE ----------------
   A differenza di "Il tuo solito" (rilevato automaticamente dalla
   combinazione più ricorrente tra gli ordini passati), qui è l'utente a
   decidere esplicitamente cosa vale la pena salvare, con un nome a sua
   scelta — utile anche per un pasto mai ordinato prima. Stesso formato
   "snapshot" già usato per gli ordini, per riusare reorderItems() invariato. */
function saveCurrentCartAsCombo(name){
  if(!STATE.cart.length) return;
  STATE.savedCombos.push({
    id: 'combo'+(uidCounter++),
    name: name.trim(),
    items: STATE.cart.map(({uid, ...rest})=>({...rest})),
    createdAt: Date.now(),
  });
  saveState();
  toast(uiT('toast.comboSaved','Combinazione salvata'));
}

function comboTotals(combo){
  return combo.items.reduce((s,it)=>{
    const t = itemTotals(it);
    return { kcal: s.kcal+t.kcal, p: s.p+t.p, c: s.c+t.c, f: s.f+t.f, price: s.price+t.price };
  }, {kcal:0,p:0,c:0,f:0,price:0});
}

/* Uscita di una voce dal carrello (cestino): la riga svanisce scivolando appena a sinistra e si richiude, così
   le altre salgono senza scatti. La voce esce subito dallo stato; la schermata si ridisegna quando sono finite
   tutte le uscite in corso, perché con due cestini premuti di seguito un ridisegno anticipato cancellerebbe la
   riga ancora a metà. Stili in styles.css (.cart-item-out). */
const CART_EXIT_MS = 360;   // un po' più delle transizioni (60 ms di ritardo + 280 ms): la riga finisce di chiudersi prima del ridisegno
let cartExitsRunning = 0;

function animateCartRowOut(row, uid){
  removeFromCart(uid, false);
  row.style.height = row.offsetHeight + 'px';   // altezza di partenza esplicita: solo così si può animare fino a 0
  void row.offsetHeight;
  row.classList.add('cart-item-out');
  row.style.height = '0px';
  cartExitsRunning++;
  const entry = current();   // uscita finita su un'altra schermata: quella è già disegnata con il carrello aggiornato
  setTimeout(()=>{ if(--cartExitsRunning === 0 && current() === entry) render(); }, CART_EXIT_MS);
}

/* ---------------- RENDER: CART ---------------- */
function renderShareCard(){
  if(!STATE.cart.length) return `<div class="empty-state">${emptyAnimHtml('emptyCart', iconSvg('cart'))}<p>${uiT('cart.empty','Il carrello è vuoto.')}</p></div>`;
  const t = cartTotals();
  const itemNames = STATE.cart.map(it=> (it.kind==='custom'||it.kind==='fixed') ? it.label : cartItemName(it));
  const shownNames = itemNames.slice(0,4);
  const moreCount = itemNames.length - shownNames.length;
  const stat = (color, label, grams)=>`<div style="--k:${color}"><b>${fmt(grams,0)}<small>g</small></b><span>${label}</span></div>`;
  return `
    <div class="share-card-wrap">
      <div class="share-card">
        <div class="share-card-logo">${brandLogoHtml('card')}</div>
        <div class="share-card-ring">${foodRingHtml(t.p,t.c,t.f,t.kcal,{size:176,sw:14,static:true,still:true})}</div>
        <div class="share-card-macros">
          ${stat('var(--carb)', uiT('build.carb','Carbo'), t.c)}
          ${stat('var(--protein)', uiT('cat.protein','Proteine'), t.p)}
          ${stat('var(--fat)', uiT('cat.fat','Grassi'), t.f)}
        </div>
        <div class="share-card-items">
          ${shownNames.map(n=>`<div class="sci-row">${esc(n)}</div>`).join('')}
          ${moreCount>0 ? `<div class="sci-row more">+${moreCount} ${uiT('common.more','altro')}</div>` : ''}
        </div>
        <div class="share-card-tag">${uiT('share.tagline','Il mio pasto, i miei macro.')}</div>
      </div>
    </div>
    <button class="btn btn-primary btn-block share-btn" style="margin-top:20px;" data-action="share-meal">${iconSvg('share')} ${uiT('loyalty.share','Condividi')}</button>
  `;
}

function renderCart(){
  if(!STATE.cart.length){
    return `${(STATE.group || STATE.groupJoin) ? groupCartHeaderHtml() : ''}<div class="empty-state">${emptyAnimHtml('emptyCart', iconSvg('cart'))}<p>${uiT('cart.empty','Il carrello è vuoto.')}<br>${uiT('cart.emptySub','Scegli gli alimenti dal menu per comporre il tuo pasto.')}</p>
      <button class="btn btn-primary" data-action="tab" data-view="menu">${uiT('cart.browseMenu','Sfoglia il menu')}</button>
      ${STATE.savedCombos.length ? `<button class="btn btn-ghost" style="margin-top:10px;" data-action="nav" data-view="saved-combos">${iconSvg('star')} ${uiT('combos.viewSaved','Le mie combinazioni')}</button>` : ''}
    </div>`;
  }
  const t = orderPricing();
  const nItems = STATE.cart.length;
  const onlySupps = STATE.cart.every(isSupplementItem);   // solo integratori: niente anello dei macro, giudizio del pasto né suggerimenti
  const atw = Math.max(1, t.p*4 + t.c*4 + t.f*9);
  const share = {p: t.p*4/atw*100, c: t.c*4/atw*100, f: t.f*9/atw*100};
  const row = (label, val, pct, color) => `
    <div class="cs-row">
      <span class="cs-dot" style="background:${color}"></span>
      <span class="cs-name">${label}</span>
      <span class="cs-val">${fmt(val,1)}<small> g</small></span>
      <span class="cs-pct">${pct.toFixed(0)}%</span>
    </div>`;
  const pm = perMealTargets();
  const fit = evaluateMacroFit(t.kcal, t.p, t.c, t.f);
  const sugg = generateSmartSuggestions(t, cartCategories(), {allowVeg:true});
  return `
    ${groupCartHeaderHtml()}
    ${groupCartListHtml()}

    <div class="nutri-panel cart-sum">
      <div class="cs-head">
        <div class="cs-titles">
          <div class="np-label">${uiT('cart.nutriTotal','Totale dell\'ordine')}</div>
          <div class="np-items">${nItems} ${nItems===1?uiT('cart.oneItem','voce'):uiT('cart.moreItems','voci')}</div>
          ${t.voucher ? `<div class="cs-voucher">${uiT('toast.voucher','Voucher')} ${esc(t.voucher.code)} · −${fmtPrice(t.discount)}</div>` : ''}
        </div>
        <div class="cs-price">${fmtPrice(t.price)}</div>
      </div>
      ${onlySupps ? '' : `<div class="cs-body">
        <div class="ring-wrap">${foodRingHtml(t.p, t.c, t.f, t.kcal, {size:88, sw:9, static:true, still:true})}</div>
        <div class="cs-rows">
          ${row(uiT('cat.carb','Carboidrati'), t.c, share.c, 'var(--carb)')}
          ${row(uiT('cat.protein','Proteine'), t.p, share.p, 'var(--protein)')}
          ${row(uiT('cat.fat','Grassi'), t.f, share.f, 'var(--fat)')}
        </div>
      </div>`}
    </div>

    ${onlySupps ? '' : `<div class="fit-card" style="background:${fit.bg}">
      <div class="fit-head">
        <span class="fit-dot" style="background:${fit.color}"></span>
        <span class="fit-tag" style="color:${fit.color}">${fit.tag}</span>
      </div>
      <div class="fit-desc">${fit.desc}</div>
      ${t.kcal>0 && userHasOwnMacros() ? `<div class="fit-contrib">
        ${uiT('fit.vsTypical','Rispetto al tuo pasto tipo')} (<b>${fmt(pm.kcal)} kcal</b>): <b>${Math.round(t.kcal/Math.max(pm.kcal,1)*100)}%</b> ${uiT('fit.ofCalories','delle calorie')}, <b>${Math.round(t.p/Math.max(pm.p,1)*100)}%</b> ${uiT('fit.ofProtein','delle proteine')}
      </div>` : ''}
    </div>`}
    ${sugg.length && !onlySupps ? `<div class="sugg-list">${sugg.map(g=>`
      <button class="sugg-card" data-action="sugg-to-cart" data-id="${g.food.id}" data-grams="${g.grams}">
        <div class="sg-ic" style="background:${thumbBg(g.food.cat)}">${foodIcon(g.food,22)}</div>
        <div class="sg-body">
          <div class="sg-title">${g.label}</div>
          <div class="sg-sub">${suggQtyText(g.food, g.grams)} · ${g.macroTxt}</div>
        </div>
        <span class="sg-plus">${iconSvg('plus')}</span>
      </button>`).join('')}</div>` : ''}

    ${STATE.groupJoin
      ? `<button class="btn btn-primary btn-block cart-go share-btn" data-action="group-send">${iconSvg('send')} ${uiT('group.sendTo','Invia il mio pasto a {name}').replace('{name}', esc(STATE.groupJoin.from || uiT('group.organizer','chi organizza')))}</button>`
      : `<button class="btn btn-primary btn-block cart-go" data-action="tab" data-view="checkout">${uiT('cart.proceedToCheckout','Procedi al checkout')}</button>`}
    <div class="cart-links">
      <button data-action="nav" data-view="share-card">${iconSvg('share')} ${uiT('share.viewShareCard','Condividi il tuo pasto')}</button>
      <button data-action="save-combo">${iconSvg('star')} ${uiT('combos.saveThis','Salva questa combinazione')}</button>
    </div>
    <button class="cart-clear" data-action="clear-cart">${uiT('cart.emptyCart','Svuota il carrello')}</button>
  `;
}

/* Miniatura di una voce del carrello/ordine: la foto del prodotto se c'è, altrimenti il suo disegno,
   altrimenti l'icona piatta di prima */
function cartThumbHtml(food, opt, size){
  if(!food) return foodIconSvg('bowl','var(--accent)',size);
  const photo = foodPhoto(food.id, opt);
  if(photo) return `<img class="thumb-img" src="${photoThumb(photo)}" alt="" draggable="false">`;
  return foodArtSvg(food.id, opt) || foodIcon(food, size);
}

/* Nome, dettaglio (grammi/porzioni/taglia), categoria e icona di una voce del carrello o di un
   ordine passato (cartSnapshot): usato dal carrello e dal riepilogo in "Ordini effettuati". */
function cartItemInfo(item){
  let name, meta, cat, iconHtml;
  // ordine vecchio con un prodotto non più nel menu: si mostra la sua etichetta (o un nome generico), senza dettagli
  if((item.kind==='single' || item.kind==='meal' || item.kind==='fixed') && !findFood(item.foodId)){
    return {name: item.label ? esc(item.label) : uiT('diary.orderSource',"Ordine MACRO'S"), meta:'', cat:'meal', iconHtml: foodIconSvg('bowl','var(--accent)',24)};
  }
  if(item.kind==='single'){
    const f=findFood(item.foodId); name=cartItemName(item); meta=qtyLabel(f, item.grams);
    cat=f.cat; iconHtml=cartThumbHtml(f, item.opt, 24);
  } else if(item.kind==='meal'){
    const f=findFood(item.foodId); name=tName(f);
    // le porzioni sono la quantità della voce (riquadro + / −): qui solo la taglia, se c'è
    meta = item.sizeId ? item.sizeDetail : (item.servings > 1 ? item.servings+' '+lcT(uiT('common.portions','Porzioni')) : '');
    // piatto con unità aggiuntive (hamburger: i patty): quante ce ne sono, compresa quella inclusa
    const a = ADDONS[item.foodId];
    if(a && a.key === 'patty') meta = [meta, uiT('cart.patties','{n} patty').replace('{n}', clamp(item.addonQty || a.def, a.min, a.max))].filter(Boolean).join(' · ');
    cat=f.cat; iconHtml=cartThumbHtml(f, item.opt, 24);
  } else if(item.kind==='fixed' && item.jar){
    const f=findFood(item.foodId);
    name = f ? tName(f) : item.label;
    meta = [item.jar.flavor ? jarFlavorName(item.jar.flavor) : '', f ? jarPackLabel(f, jarPackOf(f, item.jar.size)) : ''].filter(Boolean).join(' · ');
    cat = 'supplement'; iconHtml = cartThumbHtml(f, item.jar.flavor, 24);
  } else if(item.kind==='fixed'){
    const f=findFood(item.foodId);
    name=item.label;
    const isDrink = f && f.cat==='drink';
    meta = f && f.portion ? `${f.portion}${isDrink?' ml':' g'}` : uiT('cart.singlePortion','Porzione singola');
    cat = f ? f.cat : 'meal';
    iconHtml = cartThumbHtml(f, item.opt, 24);
  } else {
    name=item.label; meta=uiT('cart.customMeal','Pasto personalizzato');
    // piatto composto a partire da un alimento (yogurt + topping, porridge + sciroppo): la sua foto
    const base = item.mealId ? findFood(item.mealId) : null;
    cat = base ? base.cat : 'meal'; iconHtml = cartThumbHtml(base, null, 24);
  }
  return {name, meta, cat, iconHtml};
}

function cartItemRow(item){
  const {name, meta, cat, iconHtml} = cartItemInfo(item);
  const q = itemQty(item);
  const composed = cartIsComposed(item), open = composed && STATE.uiCartOpen === item.uid;
  const t = itemTotals(item);
  return `<div class="cart-item">
    <div class="thumb" style="background:${thumbBg(cat)}">${iconHtml}</div>
    <div class="info">
      <div class="nm">${name}</div>
      <div class="gm">${[meta, q>1 ? `${q} ${lcT(uiT('common.portions','Porzioni'))}` : (item.kind==='meal' && !item.sizeId && !meta ? `1 ${lcT(uiT('common.portion','Porzione'))}` : ''), item.jar ? '' : `${fmt(t.kcal)} kcal`].filter(Boolean).join(' · ')}</div>
      ${item.jar ? '' : `<div class="macros">${macroLineHtml(t.c, t.p, t.f)}</div>`}
      ${groupAssignHtml(item)}
      <div class="qty-row">
        <button class="qty-mini" data-action="cart-qty" data-uid="${item.uid}" data-delta="-1" ${q<=1?'disabled':''}>${iconSvg('minus')}</button>
        <span class="qty-n">${q}</span>
        <button class="qty-mini" data-action="cart-qty" data-uid="${item.uid}" data-delta="1">${iconSvg('plus')}</button>
        ${composed || cartEditTarget(item) ? `<button class="cart-edit" data-action="cart-edit" data-uid="${item.uid}"${composed ? ` aria-expanded="${open}"` : ''}>${iconSvg('edit')}${uiT('cart.edit','Modifica')}</button>` : ''}
      </div>
    </div>
    <div class="right">
      <span class="pr">${fmtPrice(t.price)}</span>
      ${q>1?`<span class="pr-unit">${fmtPrice(itemUnitPrice(item))} ${uiT('portion.each','cad.')}</span>`:''}
      <button class="remove-line" data-action="remove-cart" data-uid="${item.uid}" aria-label="${uiT('common.remove','Rimuovi')}" title="${uiT('common.remove','Rimuovi')}">${iconSvg('trash')}</button>
    </div>
    ${open ? cartPartsHtml(item) : ''}
  </div>`;
}

/* Pasto composto aperto nel carrello: ogni alimento con la sua quantità e − / + (le aggiunte a porzione fissa senza) */
function cartPartsHtml(item){
  return `<div class="cart-parts">${item.parts.map((part, i)=>{
    const raw = findFood(part.foodId);
    if(part.fixed) return `<div class="cp-row"><span class="cp-name">${esc(tName(raw))}</span><span class="cp-fixed">${uiT('common.portion','Porzione')}</span></div>`;
    const food = effectiveFood(raw, part.opt);
    return `<div class="cp-row">
      <span class="cp-name">${esc(tName(food))}</span>
      <button class="qty-mini" data-action="cart-part" data-uid="${item.uid}" data-i="${i}" data-delta="-1" ${part.grams <= food.min ? 'disabled' : ''} aria-label="${uiT('a11y.less','Diminuisci')} ${esc(tName(food))}">${iconSvg('minus')}</button>
      <span class="cp-qty">${qtyLabel(food, part.grams)}</span>
      <button class="qty-mini" data-action="cart-part" data-uid="${item.uid}" data-i="${i}" data-delta="1" ${part.grams >= food.max ? 'disabled' : ''} aria-label="${uiT('a11y.more','Aumenta')} ${esc(tName(food))}">${iconSvg('plus')}</button>
    </div>`;
  }).join('')}</div>`;
}

/* ---------------- COMBINAZIONI SALVATE (pagina) ---------------- */
function renderSavedCombosPage(){
  const combos = STATE.savedCombos.slice().sort((a,b)=>b.createdAt-a.createdAt);
  if(!combos.length){
    return `<div class="empty-state" style="margin-top:24px;"><span class="glyph">⭐</span><p>${uiT('combos.empty','Non hai ancora salvato nessuna combinazione. Componi un pasto e salvalo dal Carrello con un nome a tua scelta.')}</p>
      <button class="btn btn-primary" data-action="tab" data-view="menu">${uiT('cart.browseMenu','Sfoglia il menu')}</button></div>`;
  }
  return `
    <p class="menu-hint" style="margin-top:2px;">${uiT('combos.hint','Le tue combinazioni preferite, pronte da riaggiungere al carrello in un tocco.')}</p>
    <div style="margin-top:14px;display:flex;flex-direction:column;gap:12px;">
      ${combos.map(combo=>{
        const t = comboTotals(combo);
        return `<div class="challenge-card">
          <div class="chal-top">
            <span class="chal-title">${esc(combo.name)}</span>
            <button class="bs-clear" data-action="combo-delete" data-id="${combo.id}" title="${uiT('common.remove','Rimuovi')}">${iconSvg('trash')}</button>
          </div>
          <div class="menu-hint" style="margin:2px 0 10px;">${combo.items.length} ${combo.items.length===1?uiT('cart.oneItem','voce'):uiT('cart.moreItems','voci')} · ${fmt(t.kcal)} kcal · C${fmt(t.c,0)} P${fmt(t.p,0)} G${fmt(t.f,0)} · ${fmtPrice(t.price)}</div>
          <button class="btn btn-dark" style="padding:8px 16px;font-size:12px;" data-action="combo-apply" data-id="${combo.id}">${iconSvg('cart')} ${uiT('combos.addToCart','Aggiungi al carrello')}</button>
        </div>`;
      }).join('')}
    </div>
  `;
}

/* Azioni dei pulsanti (data-action) */
defineActions({
  'sugg-to-cart'(el){
    const food = findFood(el.dataset.id);
    const grams = parseInt(el.dataset.grams,10);
    if(!food) return;
    addSingleToCart(food, grams);
    render();
  },
  'apply-sugg'(el){
    const food = findFood(el.dataset.id);
    const grams = parseInt(el.dataset.grams,10);
    const slot = el.dataset.slot;
    if(!food) return;
    const existing = STATE.build[slot];
    // se lo slot ha già quell'alimento sommo la grammatura, altrimenti lo imposto
    if(existing && existing.foodId === food.id){
      STATE.build[slot] = {foodId:food.id, grams: clamp(existing.grams + grams, food.min, food.max)};
    } else {
      STATE.build[slot] = {foodId:food.id, grams};
    }
    toast(tName(food) + ' '+uiT('toast.addedToMeal','aggiunto al pasto'));
    render();
  },
  'clear-cart'(){
    showConfirm(uiT('cart.clearTitle','Svuotare il carrello?'),
      uiT('cart.clearBody',"Tutte le voci dell'ordine verranno rimosse."),
      uiT('common.empty','Svuota'), ()=>{ STATE.cart = []; toast(uiT('toast.cartCleared','Carrello svuotato')); render(); return true; });
  },
  'remove-cart'(el){
    const row = el.closest('.cart-item');
    if(row && row.classList.contains('cart-item-out')) return;   // la riga sta già uscendo
    if(row && !matchMedia('(prefers-reduced-motion: reduce)').matches) animateCartRowOut(row, el.dataset.uid);
    else removeFromCart(el.dataset.uid);
    toast(uiT('toast.itemRemoved','Voce rimossa'));
  },
  'cart-qty'(el){ setCartQty(el.dataset.uid, +el.dataset.delta); },
  /* Modifica di una voce: un pasto composto si apre qui sotto, alimento per alimento; il resto nella sua scheda, con
     le stesse scelte, e «Aggiorna nel carrello» rimette la voce al suo posto (cartAddDone in cart-logic.js) */
  'cart-edit'(el){
    const it = STATE.cart.find(x=> x.uid === el.dataset.uid);
    if(!it) return;
    if(cartIsComposed(it)){ STATE.uiCartOpen = STATE.uiCartOpen === it.uid ? null : it.uid; render(); return; }
    const target = cartEditTarget(it);
    if(!target) return;
    const {view, ...params} = target;
    navigateTo(view, {...params, editUid: it.uid});
  },
  'cart-part'(el){ cartPartGrams(el.dataset.uid, +el.dataset.i, +el.dataset.delta); },
  /* Il pasto nel carrello diventa la card in formato storia (share-card.js): immagine vera, non solo testo */
  'share-meal'(){
    if(!STATE.cart.length) return;
    const items = shareItemsFromCart(STATE.cart);
    const title = items.length === 1 && items[0].food ? tName(effectiveFood(items[0].food, items[0].opt)) : uiT('share.myMeal',"Il mio pasto MACRO'S");
    openShareCard({items, totals: cartTotals(), title, eyebrow: uiT('share.tagline','Il mio pasto, i miei macro.')});
  },
  'save-combo'(){
    if(!STATE.cart.length) return;
    showPromptText(uiT('combos.saveTitle','Salva combinazione'), uiT('combos.saveMsg','Dai un nome a questa combinazione per ritrovarla facilmente.'),
      '', uiT('combos.namePlaceholder','Es. Post allenamento'), (name)=>{ saveCurrentCartAsCombo(name); render(); });
  },
  'combo-apply'(el){
    const combo = STATE.savedCombos.find(c=>c.id===el.dataset.id);
    if(!combo) return;
    reorderItems(combo.items);
    goToTab('cart');
  },
  'combo-delete'(el){
    const id = el.dataset.id;
    showConfirm(uiT('combos.deleteTitle','Eliminare questa combinazione?'), uiT('combos.deleteBody','Potrai sempre ricomporla e salvarla di nuovo.'),
      uiT('common.remove','Rimuovi'), ()=>{
        STATE.savedCombos = STATE.savedCombos.filter(c=>c.id!==id);
        saveState(); render();
        return true;
      });
  },
});

/* Animazioni della timeline dell'ordine: una scena per fase, solo quella IN CORSO. Tutte le scene
   (ricevuto, in preparazione, in consegna, consegnato) sono Lottie forniti dal cliente (js/data/anim-*.js),
   riprodotti da lottie-web caricato solo quando serve; finché non è pronto (o offline) resta il
   disegno SVG piatto come segnaposto. */

function stageAnimHtml(key){
  const scenes = {
    received: ()=>`<span class="ot-lottie ot-lottie-received" data-anim="received">${otAnimReceived()}</span>`,
    preparing: otAnimPreparing,
    onWay: ()=>`<span class="ot-lottie ot-lottie-onway" data-anim="onWay">${otAnimOnWay()}</span>`,   // Lottie del cliente, con lo scooter SVG come segnaposto
    delivered: ()=>`<span class="ot-lottie ot-lottie-delivered" data-anim="delivered">${otAnimDelivered()}</span>`,
  };
  const fn = scenes[key];
  return fn ? `<span class="ot-anim">${fn()}</span>` : '';
}

/* "Ordine ricevuto": uno scontrino esce dal terminale POS con il logo e la scritta ACCEPTED,
   con un rimbalzo finale. È il segnaposto SVG della Lottie "ricevuto". */
function otAnimReceived(){
  return `
    <svg viewBox="0 0 72 72" width="64" height="64">
      <rect x="14" y="36" width="44" height="26" rx="6" fill="var(--ink)"/>
      <rect x="21" y="42" width="30" height="10" rx="2" fill="#fff" opacity=".14"/>
      <circle cx="25" cy="56" r="2" fill="#fff" opacity=".35"/>
      <circle cx="36" cy="56" r="2" fill="#fff" opacity=".35"/>
      <circle cx="47" cy="56" r="2" fill="#fff" opacity=".35"/>
      <rect x="20" y="34" width="32" height="4" rx="2" fill="#14151A"/>
      <g class="ot-ticket">
        <rect x="17" y="6" width="38" height="32" rx="3" fill="#fff"/>
        <path d="M17 38 l3.8 3.4 3.8-3.4 3.8 3.4 3.8-3.4 3.8 3.4 3.8-3.4 3.8 3.4 3.8-3.4 3.8 3.4v-3.4z" fill="#fff"/>
        <circle cx="36" cy="15" r="5.4" fill="var(--accent)"/>
        <path d="M33.2 15.2 l2 2 3.6-4" stroke="#fff" stroke-width="1.7" fill="none" stroke-linecap="round" stroke-linejoin="round"/>
        <text x="36" y="29" text-anchor="middle" font-family="Poppins,sans-serif" font-weight="700" font-size="7.5" fill="var(--ink)" letter-spacing=".5">ACCEPTED</text>
      </g>
    </svg>`;
}

/* "In preparazione": tre atti in loop continuo (8s) sulla stessa scena —
   1) la bilancia pesa gli ingredienti (cadono dall'alto, il display si accende)
   2) si inclina e versa nel wok
   3) il wok sfrigola sul fornello con vapore che sale — poi si torna al punto 1. */
/* "In preparazione": animazione Lottie della padella (js/data/anim-preparing.js). Il disegno SVG qui sotto
   resta come segnaposto finché lottie-web non è caricato (o se la rete non c'è). */
function otAnimPreparing(){
  return `<span class="ot-lottie" data-anim="preparing">${otAnimPreparingFallback()}</span>`;
}

/* lottie-web (versione "light": solo rendering SVG) si carica una volta sola e solo quando serve */
const LOTTIE_SRC = 'https://cdnjs.cloudflare.com/ajax/libs/lottie-web/5.12.2/lottie_light.min.js';
let lottieLoading = null;
function loadLottie(){
  if(window.lottie) return Promise.resolve(window.lottie);
  if(!lottieLoading) lottieLoading = new Promise((resolve, reject)=>{
    const sc = document.createElement('script');
    cdnAttrs(sc, LOTTIE_SRC);
    sc.src = LOTTIE_SRC; sc.async = true;
    sc.onload = ()=> window.lottie ? resolve(window.lottie) : reject();
    sc.onerror = ()=>{ lottieLoading = null; reject(); };
    document.head.appendChild(sc);
  });
  return lottieLoading;
}

/* Scena Lottie per fase, tutte in loop finché la fase è in corso. view = inquadratura (viewBox) sul
   disegno vero, misurata sui pixel di tutti i fotogrammi: le tele dei file hanno tanto vuoto attorno
   (e non centrato), così invece la scena riempie il riquadro ed è centrata. still = fotogramma
   mostrato con "riduci movimento". */
const LOTTIE_ANIMS = {
  received:  {data: ()=>JSON.parse(ANIM_RECEIVED),  view: '58 38 694 652',  still: 54},
  preparing: {data: ()=>JSON.parse(ANIM_PREPARING), view: '128 8 544 554',  still: 100},
  onWay:     {data: ()=>JSON.parse(ANIM_ONWAY),     view: '150 42 606 428', still: 250},
  delivered: {data: ()=>JSON.parse(ANIM_DELIVERED), view: '83 192 320 252', still: 74},   // sul sacchetto: le braccia escono ai lati (sfumate in CSS)
  // stati vuoti: il sacchetto che si capovolge e si rattrista (carrello), il sacchetto che ondeggia (ordini), la padella (diario)
  emptyCart:  {data: ()=>JSON.parse(ANIM_SAD_BAG),   view: '318 300 444 520', still: 80},   // inquadrato da fermo: il capovolgimento esce un poco (vedi CSS)
  noOrders:   {data: ()=>JSON.parse(ANIM_BAG),       view: '142 186 220 266', still: 45},
  emptyDiary: {data: ()=>JSON.parse(ANIM_PREPARING), view: '128 8 544 554',   still: 100},
};

/* Illustrazione animata al posto dell'icona di uno stato vuoto (carrello, ordini, diario) */
function emptyAnimHtml(kind, glyph){
  return `<span class="ot-lottie empty-lottie" data-anim="${kind}" aria-hidden="true"><span class="glyph">${glyph}</span></span>`;
}

/* Animazioni montate: quelle la cui scena non è più nella pagina (la schermata è stata ridisegnata) si distruggono,
   altrimenti lottie le terrebbe in vita e in loop per sempre (CPU, batteria e memoria che crescono a ogni visita) */
const lottieMounted = [];
function sweepLotties(){
  for(let i = lottieMounted.length - 1; i >= 0; i--){
    const m = lottieMounted[i];
    if(m.box.isConnected) continue;
    try{ m.anim.destroy(); }catch{}
    lottieMounted.splice(i, 1);
  }
}

/* Sostituisce i segnaposto .ot-lottie con l'animazione vera (chiamata dopo ogni render della conferma) */
function mountLotties(){
  sweepLotties();
  const boxes = [...document.querySelectorAll('.ot-lottie:not(.ot-lottie-on)')];
  if(!boxes.length) return;
  const reduced = window.matchMedia && matchMedia('(prefers-reduced-motion: reduce)').matches;
  loadLottie().then(lib=>{
    boxes.forEach(box=>{
      if(!box.isConnected || box.classList.contains('ot-lottie-on')) return;
      box.classList.add('ot-lottie-on');
      box.innerHTML = '';
      const conf = LOTTIE_ANIMS[box.dataset.anim] || LOTTIE_ANIMS.preparing;
      const [, , vw, vh] = conf.view.split(' ').map(Number);
      // il riquadro prende le proporzioni dell'inquadratura: la scena è sempre intera, centrata e il più
      // grande possibile nell'area dell'animazione (cqw/cqh = larghezza/altezza di .ot-hero); negli stati
      // vuoti la larghezza la dà il CSS (.empty-lottie)
      if(box.closest('.ot-hero')) box.style.width = `min(100cqw, ${(vw/vh*100).toFixed(2)}cqh)`;
      box.style.height = 'auto';
      box.style.aspectRatio = `${vw} / ${vh}`;
      const anim = lib.loadAnimation({container:box, renderer:'svg', loop:true, autoplay:!reduced,
        rendererSettings:{viewBoxSize: conf.view, preserveAspectRatio:'xMidYMid meet'},
        animationData: conf.data()});   // ogni lettura del JSON è già una copia nuova
      lottieMounted.push({box, anim});
      if(reduced) anim.goToAndStop(conf.still, true);   // "riduci movimento": un fotogramma fermo e significativo
    });
  }).catch(()=>{ boxes.forEach(b=> b.classList.add('ot-lottie-off')); /* offline: resta il disegno SVG */ });
}

