/* Geolocalizzazione: posizione dal dispositivo, poi indirizzo tramite
   Nominatim (OpenStreetMap, gratuito e senza chiave). */
async function useGeolocation(){
  const set = (t)=>{ const el = document.getElementById('geo-status'); if(el) el.textContent = t; };
  if(!navigator.geolocation){ set(uiT('geo.unsupported','Geolocalizzazione non supportata dal browser')); return; }
  set(uiT('geo.locating','Rilevo la posizione...'));
  const entry = current();   // la risposta ridisegna solo se si è ancora su questa schermata
  navigator.geolocation.getCurrentPosition(async (pos)=>{
    const {latitude:lat, longitude:lng} = pos.coords;
    STATE.delivery.lat = lat; STATE.delivery.lng = lng;
    set(uiT('geo.searching',"Cerco l'indirizzo..."));
    try{
      const res = await fetch(`https://nominatim.openstreetmap.org/reverse?format=jsonv2&lat=${lat}&lon=${lng}&addressdetails=1`, {headers:{'Accept':'application/json'}});
      if(!res.ok) throw new Error('reverse ' + res.status);   // limite di richieste (429), servizio non disponibile
      const data = await res.json();
      const a = (data && data.address) || {};
      if(!(a.road || a.pedestrian || a.footway)) throw new Error('indirizzo non trovato');
      STATE.delivery.street = a.road || a.pedestrian || a.footway || STATE.delivery.street;
      STATE.delivery.civic  = a.house_number || STATE.delivery.civic;
      STATE.delivery.city   = a.city || a.town || a.village || a.municipality || STATE.delivery.city;
      STATE.delivery.zip    = a.postcode || STATE.delivery.zip;
      saveState();
      toast(uiT('geo.addressFilled','Indirizzo compilato'));
      if(current() === entry) render();
    }catch{
      set(netOffline() ? uiT('net.geoOffline',"Posizione rilevata, ma senza internet non si trova l'indirizzo: completalo a mano")
                       : uiT('geo.notFound','Posizione rilevata, ma indirizzo non trovato: completalo a mano'));
    }
  }, (err)=>{
    set(err.code===1 ? uiT('geo.denied',"Permesso negato: inserisci l'indirizzo a mano") : uiT('geo.unavailable',"Posizione non disponibile: inserisci a mano"));
  }, {enableHighAccuracy:true, timeout:10000});
}

