/* ---------------- CHAT CON IL PROFESSIONISTA ----------------
   Non esiste un backend: i messaggi dell'utente restano su questo dispositivo e le
   risposte sono automatiche (la pagina lo dichiara). Le risposte si salvano come
   chiave e si traducono al momento di mostrarle, così seguono la lingua scelta. */
const CHAT_IT = {
  reply1t:'Grazie del messaggio! Ho dato un\'occhiata al tuo profilo e ai tuoi obiettivi. Ti rispondo nel dettaglio appena possibile.',
  reply2t:'Ricevuto! Intanto annota come ti senti dopo gli allenamenti: mi aiuta a costruire la scheda giusta.',
  q1t:'Quanti giorni a settimana dovrei allenarmi?',
  q2t:'Posso allenarmi anche a casa?',
  greet:'Ciao{hello}! Sono {pro}, {role}. Scrivimi pure: come posso aiutarti con i tuoi obiettivi?',
  reply1:'Grazie del messaggio! Ho dato un\'occhiata ai tuoi obiettivi: {kcal} kcal al giorno. Ti rispondo nel dettaglio appena possibile.',
  reply1b:'Grazie del messaggio! Per darti un consiglio preciso mi servono i tuoi dati: imposta il tuo profilo da «I miei macro» e ne parliamo.',
  reply2:'Ricevuto! Intanto tieni il diario aggiornato: mi aiuta a capire cosa funziona per te.',
  reply3:'Su questo conviene ragionare insieme con calma: puoi prenotare una consulenza, in sede o in video.',
  reply4:'Perfetto, annoto tutto! Se preferisci parlarne a voce, trovi gli orari liberi nella prenotazione.',
  reply5:'Grazie, tengo presente anche questo. Continua pure a scrivermi quando vuoi.',
  q1:'Posso sostituire alcuni alimenti del piano?',
  q2:'Come imposto i macro per il mio obiettivo?',
  q3:'Vorrei prenotare una consulenza',
};

function chatOf(id){ return STATE.chats[id] || (STATE.chats[id] = []); }

function chatEnsureGreeting(id){ const c = chatOf(id); if(!c.length) c.push({f:'pro', k:'greet', ts:Date.now()}); }

function chatProText(k, n){
  const first = (STATE.delivery.firstName || (STATE.auth.name||'').split(' ')[0] || '').trim();
  return esc(uiT('chat.'+k, CHAT_IT[k]||'')
    .replace('{hello}', first ? ' '+first : '').replace('{pro}', tNutriName(n)).replace('{role}', lcT(tNutriRole(n)))
    .replace('{kcal}', userHasOwnMacros() ? fmt(STATE.profile.kcal) : ''));
}

function chatThreadHtml(id){
  const n = proById(id);
  let lastDay = '';
  const rows = chatOf(id).map(m=>{
    const dk = todayKey(new Date(m.ts));
    const sep = dk!==lastDay ? `<div class="chat-day">${prettyDate(dk)}</div>` : '';
    lastDay = dk;
    const time = `<span class="chat-time">${new Date(m.ts).toLocaleTimeString(langLocale(), {hour:'2-digit', minute:'2-digit'})}</span>`;
    if(m.f==='me') return `${sep}<div class="chat-row me"><div class="chat-bubble">${esc(m.t)}${time}</div></div>`;
    const cta = m.k==='reply3' && !bookingOf(consultKind(n))
      ? `<button class="btn btn-ghost btn-sm chat-cta" data-action="consult-start" data-id="${id}">${iconSvg('diary')} ${uiT('chat.bookCta','Prenota una consulenza')}</button>` : '';
    return `${sep}<div class="chat-row"><div class="chat-bubble">${chatProText(m.k, n)}${time}</div>${cta}</div>`;
  }).join('');
  const typing = STATE.uiChatTyping===id
    ? `<div class="chat-row"><div class="chat-bubble typing" role="status" aria-label="${uiT('chat.typing','sta scrivendo…')}"><i></i><i></i><i></i></div></div>` : '';
  return rows + typing;
}

function chatRefresh(id){
  const th = document.getElementById('chat-thread');
  if(!th) return;
  th.innerHTML = chatThreadHtml(id);
  const q = document.getElementById('chat-quick');
  if(q) q.classList.toggle('gone', chatOf(id).some(m=>m.f==='me'));
  window.scrollTo({top:document.documentElement.scrollHeight, behavior:'smooth'});
}

function chatSend(text){
  const c = current();
  if(c.view!=='nutri-chat') return;
  const input = document.getElementById('chat-input');
  const t = String(text!==undefined ? text : (input ? input.value : '')).trim().slice(0,500);
  if(!t) return;
  const id = c.id;
  chatOf(id).push({f:'me', t, ts:Date.now()});
  if(input){ input.value = ''; input.focus(); }
  STATE.uiChatTyping = id;
  saveState();
  chatRefresh(id);
  clearTimeout(chatSend.timer);
  chatSend.timer = setTimeout(()=>chatReply(id), 1400);
}

function chatReply(id){
  STATE.uiChatTyping = null;
  const mine = chatOf(id).filter(m=>m.f==='me').length;
  const tr = consultKind(proById(id))==='train';
  const k = mine<=1 ? (tr ? 'reply1t' : (userHasOwnMacros() ? 'reply1' : 'reply1b')) : (mine===2 ? (tr ? 'reply2t' : 'reply2') : (mine===3 ? 'reply3' : (mine%2 ? 'reply5' : 'reply4')));
  chatOf(id).push({f:'pro', k, ts:Date.now()});
  saveState();
  const c = current();
  if(c.view==='nutri-chat' && c.id===id) chatRefresh(id);
}

function renderNutriChat(params){
  const n = proById(params.id);
  if(!n) return `<div class="empty-state"><p>${uiT('detail.productUnavailable','Prodotto non disponibile')}</p></div>`;
  const started = chatOf(n.id).some(m=>m.f==='me');
  return `
    <div class="chat-head">
      ${proAvatar(n)}
      <div class="pro-id"><div class="pro-name">${tNutriName(n)}</div><div class="pro-role">${tNutriRole(n)} · ${uiT('chat.replyTime','di solito risponde entro poche ore')}</div></div>
      ${bookingOf(consultKind(n)) ? '' : `<button class="btn btn-ghost btn-sm" data-action="consult-start" data-id="${n.id}">${uiT('consult.bookShort','Prenota')}</button>`}
    </div>
    <div class="chat-note">${uiT('chat.demoNote','Versione demo: le risposte sono automatiche, non arrivano da un professionista reale.')}</div>
    <div class="chat-thread" id="chat-thread">${chatThreadHtml(n.id)}</div>
    <div class="chat-quick ${started?'gone':''}" id="chat-quick">
      ${(consultKind(n)==='train' ? ['q1t','q2t','q3'] : ['q1','q2','q3']).map(q=>`<button class="chat-chip" data-action="chat-quick" data-q="${q}">${uiT('chat.'+q, CHAT_IT[q])}</button>`).join('')}
    </div>
    <div class="chat-composer">
      <div class="cc-inner">
        <input class="text-input" id="chat-input" type="text" maxlength="500" autocomplete="off" placeholder="${uiT('chat.placeholder','Scrivi un messaggio…')}">
        <button class="chat-send" data-action="chat-send" aria-label="${uiT('chat.send','Invia')}">${iconSvg('send')}</button>
      </div>
    </div>
  `;
}

/* Azioni dei pulsanti (data-action) */
defineActions({
  'consult-start'(el){
    STATE.consultDraft = {nutriId: el.dataset.id, mode:'studio', date:null, time:null, prefs:{}};
    STATE.uiConsultTab = consultKind(proById(el.dataset.id));
    navigateTo('nutri-book', {});
  },
  'nutri-chat'(el){
    const id = el.dataset.id;
    chatEnsureGreeting(id);
    saveState();
    navigateTo('nutri-chat', {id});
  },
  'chat-send'(){ chatSend(); },
  'chat-quick'(el){ chatSend(uiT('chat.'+el.dataset.q, CHAT_IT[el.dataset.q])); },
  'consult-tab'(el){ STATE.uiConsultTab = el.dataset.val==='train' ? 'train' : 'nutri'; render(); },
  'consult-pref'(el){
    const d = STATE.consultDraft;
    if(!d) return;
    d.prefs = d.prefs || {};
    const key = el.dataset.key, v = el.dataset.val;
    if(d.prefs[key]===v) delete d.prefs[key]; else d.prefs[key] = v;   // secondo tocco: si toglie la scelta
    render();
  },
  'consult-mode'(el){ STATE.consultDraft.mode = el.dataset.val; render(); },
  'consult-day'(el){ STATE.consultDraft.date = el.dataset.val; STATE.consultDraft.time = null; render(); },
  'consult-time'(el){ STATE.consultDraft.time = el.dataset.val; render(); },
  'consult-confirm'(){
    const d = STATE.consultDraft;
    if(!d || !d.date || !d.time) return;
    const id = 'c'+(uidCounter++);
    const kind = consultKind(proById(d.nutriId));
    setBooking(kind, {id, nutriId:d.nutriId, mode:d.mode, date:d.date, time:d.time,
                     price:consultPrice(d), createdAt:todayKey(),
                     ...(kind==='train' ? {prefs:{...(d.prefs||{})}} : {}),
                     zoom: null});   // il link della videochiamata lo manda il professionista: nessun link inventato
    STATE.consultDraft = null;
    STATE.uiConsultTab = kind;
    toast(uiT('toast.apptConfirmed','Appuntamento confermato'));
    STATE.stack = [{view:'profile'}];
    navigateTo('nutri', {});
  },
  'consult-cancel'(el){
    showConfirm(uiT('consult.cancelTitle',"Annullare l'appuntamento?"), uiT('consult.cancelBody','Lo slot tornerà disponibile per altri clienti.'),
      uiT('consult.cancelAppt','Annulla appuntamento'), ()=>{
        setBooking(el.dataset.kind==='train' ? 'train' : 'nutri', null);
        toast(uiT('toast.apptCancelled','Appuntamento annullato'));
        render();
        return true;
      });
  },
});

/* invio con Enter nel campo della chat */
defineFieldHandlers('keydown', [
  ['#chat-input', (field, e)=>{
    if(e.key==='Enter' && !e.isComposing){ e.preventDefault(); chatSend(); }
  }],
]);

/* Weekly Box: piano settimanale e composizione dei pasti */

/* ---------------- ABBONAMENTO SETTIMANALE ----------------
   Piani a pasti fissi con rinnovo settimanale. Il cut-off serve alla
   cucina per organizzare batch cooking e spesa: dopo quell'ora la
   settimana successiva è chiusa alle modifiche. */
const SUB_PLANS = {
  5:  {meals:5,  label:'5 pasti',  sub:'Pranzi dal lunedì al venerdì',        discount:0},
  10: {meals:10, label:'10 pasti', sub:'Pranzo e cena dal lunedì al venerdì', discount:0.08},
  14: {meals:14, label:'14 pasti', sub:'Pranzo e cena, 7 giorni su 7',        discount:0.12, recommended:true},
};


const WEEK_DAYS = ['Lunedì','Martedì','Mercoledì','Giovedì','Venerdì','Sabato','Domenica'];

const WEEK_DAY_KEYS = ['mon','tue','wed','thu','fri','sat','sun'];

function weekDayName(idx){ return uiT('weekday.'+WEEK_DAY_KEYS[idx], WEEK_DAYS[idx]); }

const CUTOFF_DAY = 4;                  // venerdì (lun=0 ... dom=6)

/* Cut-off scaglionato per zona: evita che tutta la produzione arrivi in
   cucina nello stesso istante. La zona deriva dal CAP di consegna. */
const CUTOFF_ZONES = {
  A: {label:'Zona A · centro',    hour:20, min:0},
  B: {label:'Zona B · semicentro',hour:21, min:30},
  C: {label:'Zona C · periferia', hour:23, min:59},
};

function deliveryZone(){
  const zip = (STATE.delivery.zip||'').replace(/\D/g,'');
  if(!zip) return 'C';
  const n = parseInt(zip.slice(-2),10) || 0;
  return n < 33 ? 'A' : (n < 66 ? 'B' : 'C');
}

function subSlots(planKey){
  const p = SUB_PLANS[planKey];
  const slots = [];
  const days = p.meals===14 ? 7 : 5;
  for(let d=0; d<days; d++){
    slots.push({day:d, meal:'lunch'});
    if(p.meals>=10) slots.push({day:d, meal:'dinner'});
  }
  return slots;
}

/* Prezzo del piano: la somma dei pasti scelti (ognuno al suo prezzo di vendita, lo stesso del menu) meno lo
   sconto del piano — così l'abbonamento conviene sempre rispetto all'ordine singolo. Senza settimana (scelta del
   piano, prima di comporre i pasti) è una stima sul prezzo medio dei piatti pronti: estimate:true. */
function subPrice(planKey, week){
  const p = SUB_PLANS[planKey];
  let full;
  const estimate = !week;
  if(estimate){
    const avg = MEALS.reduce((s, m)=> s + sellPrice(m.price), 0) / MEALS.length;
    full = avg * p.meals;
  } else {
    full = subSlots(planKey).reduce((s, x)=>{ const m = subSlotInfo(week[`${x.day}-${x.meal}`]); return s + (m ? m.price : 0); }, 0);
  }
  full = Math.round(full * 100) / 100;
  const price = sellPrice(full * (1 - p.discount));   // prezzo pulito: vedi sellPrice in core/util.js
  return {full, price, saved: Math.max(0, Math.round((full - price) * 100) / 100), estimate};
}

/* Un pasto della Weekly Box è un piatto pronto ({kind:'meal', id}) oppure una composizione
   scelta dall'utente alimento per alimento, con le sue grammature ({kind:'build', b:{carb,protein,fat,extras}}).
   Le settimane salvate in precedenza contengono direttamente l'id del piatto. */
function subSlotInfo(v){
  if(!v) return null;
  if(typeof v==='string') v = {kind:'meal', id:v};
  if(v.kind==='build'){
    const t = mealPlanMealTotals(v.b);
    return {name: mealCompositionParts(v.b).join(' + '), kcal:t.kcal, p:t.p, c:t.c, f:t.f, price:sellPrice(t.price), custom:true};
  }
  const m = findFood(v.id);
  return m ? {name:tName(m), kcal:m.kcal, p:m.p, c:m.c, f:m.f, price:sellPrice(m.price), meal:m} : null;
}

/* La settimana su cui si sta lavorando: quella dell'abbonamento attivo o la bozza in configurazione */
function subWeekRef(){ return STATE.subscription ? STATE.subscription.week : STATE.subDraft.week; }

function subSlotLabel(meal){ return meal==='lunch' ? uiT('common.lunch','Pranzo') : uiT('common.dinner','Cena'); }

function subWeekTotals(plan){
  let kcal=0,p=0,c=0,f=0,n=0;
  Object.values(plan||{}).forEach(v=>{
    const m = subSlotInfo(v);
    if(!m) return;
    kcal+=m.kcal; p+=m.p; c+=m.c; f+=m.f; n++;
  });
  return {kcal,p,c,f,n};
}

/* Prossimo cut-off: venerdì 23:59 */
function nextCutoff(){
  const z = CUTOFF_ZONES[deliveryZone()];
  const now = new Date();
  const d = new Date(now);
  const diff = (CUTOFF_DAY + 7 - ((now.getDay()+6)%7)) % 7;   // lun=0 ... dom=6
  d.setDate(now.getDate() + diff);
  d.setHours(z.hour, z.min, 0, 0);
  if(d <= now) d.setDate(d.getDate()+7);
  return d;
}

function cutoffLabel(){
  const z = CUTOFF_ZONES[deliveryZone()];
  const t = String(z.hour).padStart(2,'0')+':'+String(z.min).padStart(2,'0');
  return `${uiT('sub.cutoffLabel','venerdì alle {t}').replace('{t}', t)} · ${z.label}`;
}

/* Confronto tra i macro con cui è stata generata la settimana e quelli attuali */
function macroSnapshot(){
  const p = STATE.profile;
  return {kcal:p.kcal, p:p.p, c:p.c, f:p.f};
}

function macrosChanged(){
  const s = STATE.subscription;
  if(!s || !s.macroSnap) return false;
  const now = macroSnapshot();
  const diff = (a,b)=> b>0 ? Math.abs(a-b)/b : 0;
  return diff(now.kcal,s.macroSnap.kcal) > 0.05
      || diff(now.p, s.macroSnap.p) > 0.05
      || diff(now.c, s.macroSnap.c) > 0.05
      || diff(now.f, s.macroSnap.f) > 0.05;
}

/* Etichetta: date di produzione e consumo. I pasti abbattuti si consumano
   entro 3 giorni dalla preparazione. */
const SHELF_LIFE_DAYS = 3;

function labelDates(dayIndex, deliveryMode){
  const monday = new Date();
  monday.setDate(monday.getDate() + ((8 - ((monday.getDay()+6)%7 + 1)) % 7 || 7));
  const consume = new Date(monday); consume.setDate(monday.getDate() + dayIndex);
  const prod = new Date(consume);
  // consegna raggruppata: prodotto il giorno prima del blocco di consegna
  prod.setDate(consume.getDate() - (deliveryMode==='batch' ? (dayIndex%3===0?1:(dayIndex%3)) : 0) - 1);
  const expiry = new Date(prod); expiry.setDate(prod.getDate() + SHELF_LIFE_DAYS);
  const f = (d)=> `${String(d.getDate()).padStart(2,'0')}/${String(d.getMonth()+1).padStart(2,'0')}`;
  return {prod:f(prod), expiry:f(expiry), consume:f(consume)};
}

function cutoffCountdown(){
  const ms = nextCutoff() - new Date();
  const h = Math.floor(ms/3600000), m = Math.floor(ms%3600000/60000);
  const days = Math.floor(h/24), hours = h%24;
  return {ms, days, hours, mins:m,
    text: days>0 ? `${days}${uiT('time.dayShort','g')} ${hours}h ${m}min` : `${hours}h ${m}min`};
}

/* Banner del conto alla rovescia sulla dashboard della Weekly Box: tre tessere (giorni · ore · minuti),
   barra del tempo rimasto e un'etichetta d'allerta nelle ultime 24 ore (rossa nelle ultime 3). */
function cutoffBannerHtml(){
  const cd = cutoffCountdown();
  const level = cd.ms < 3*3600000 ? 'urgent' : (cd.ms < 24*3600000 ? 'soon' : '');
  const left = clamp(Math.round(cd.ms/(7*24*3600000)*100), 0, 100);
  const unit = (v, label)=>`<div class="cb-unit"><b>${String(v).padStart(2,'0')}</b><span>${label}</span></div>`;
  return `<div class="cutoff-card ${level}" id="cutoff-banner">
    <div class="cb-top">
      <span class="cb-ic">${iconSvg('clock')}</span>
      <div class="cb-heads">
        <div class="cb-label">${uiT('sub.editsOpenFor','Modifiche aperte ancora per')}</div>
        <div class="cb-when">${uiT('sub.cutoffPart1','Chiusura')} ${cutoffLabel()}</div>
      </div>
      ${level ? `<span class="cb-flag">${level==='urgent' ? uiT('sub.lastHours','Ultime ore') : uiT('sub.lastDay','Ultime 24 ore')}</span>` : ''}
    </div>
    <div class="cb-clock" role="timer" aria-label="${cd.text}">
      ${unit(cd.days, uiT('time.days','giorni'))}${unit(cd.hours, uiT('time.hours','ore'))}${unit(cd.mins, uiT('time.minutes','min'))}
    </div>
    <div class="banner-bar" aria-hidden="true"><i style="width:${left}%"></i></div>
    <div class="cb-note">${uiT('sub.cutoffPart2','Dopo quell\'ora la settimana successiva va in cucina: se non modifichi nulla, confermiamo il piano attuale.')}</div>
  </div>`;
}

