/* Passo 2 — composizione della settimana */
function renderSubBuilder(){
  const d = STATE.subDraft;
  const slots = subSlots(d.plan);
  const tot = subWeekTotals(d.week);
  const pm = perMealTargets();
  const filled = Object.keys(d.week||{}).length;
  const pct = slots.length ? Math.round(filled/slots.length*100) : 0;
  const avg = filled ? {kcal:tot.kcal/filled, p:tot.p/filled, c:tot.c/filled, f:tot.f/filled} : {kcal:0,p:0,c:0,f:0};
  // righe dei macro nello stile condiviso (macroRowHtml in core/food-ring.js)
  const bar = (k,label,val,goal)=>{ const pc = goal>0 ? Math.round(val/goal*100) : 0;
    return macroRowHtml(k, label, val, goal, pc, `<span class="md md-share">${pc}%</span>`); };

  const dayCount = SUB_PLANS[d.plan].meals===14 ? 7 : 5;
  const grid = Array.from({length:dayCount}, (_,day)=>{
    const meals = slots.filter(s=>s.day===day);
    return `<div class="sub-day">
      <div class="sd-name">${weekDayName(day)}</div>
      ${meals.map(s=>{
        const key = `${s.day}-${s.meal}`;
        const m = subSlotInfo(d.week[key]);
        return `<button class="sd-slot ${m?'filled':''}" data-action="sub-pick" data-key="${key}">
          <span class="sds-label">${subSlotLabel(s.meal)}</span>
          <span class="sds-name">${m?esc(m.name):uiT('sub.chooseDish','Scegli un pasto')}</span>
          ${m?`<span class="sds-macros">${fmt(m.kcal)} kcal · C${fmt(m.c)} P${fmt(m.p)} G${fmt(m.f)}</span>`:''}
        </button>`;
      }).join('')}
    </div>`;
  }).join('');

  return `
    <div class="sub-steps">${[1,2,3].map(n=>`<div class="ss-dot ${n<=2?'on':''}"></div>`).join('')}</div>
    <div class="sub-steplbl">${uiT('sub.step','Passo')} 2 ${uiT('sub.of3','di 3')}</div>
    <h2 class="onb-q">${uiT('sub.composeWeek','Componi la settimana')}</h2>
    ${ownMacrosNoteHtml()}

    <div class="week-summary">
      <div class="ws-top">
        <div><div class="ws-big">${filled}/${slots.length}</div><div class="ws-lbl">${uiT('sub.mealsAssigned','pasti assegnati')}</div></div>
        <div style="text-align:right;"><div class="ws-big">${fmt(avg.kcal)}</div><div class="ws-lbl">${uiT('sub.avgKcalMeal','kcal medie a pasto')}</div></div>
      </div>
      <div class="dq-track" style="margin:12px 0 14px;"><div class="dq-fill" style="width:${pct}%;background:var(--accent)"></div></div>
      ${filled ? (()=>{ const pr = subPrice(d.plan, d.week); return `<div class="ws-price">${uiT('sub.weekSoFar','Settimana finora')}: <b>${fmtPrice(pr.price)}</b>${pr.saved ? ` <span>(${uiT('sub.youSave','risparmi')} ${fmtPrice(pr.saved)})</span>` : ''}</div>`; })() : ''}
      <div class="mms-macros ds-macros">
        ${bar('c', uiT('sub.avgCarb','Carboidrati medi'), avg.c, pm.c)}
        ${bar('p', uiT('sub.avgProtein','Proteine medie'), avg.p, pm.p)}
        ${bar('f', uiT('sub.avgFat','Grassi medi'), avg.f, pm.f)}
      </div>
    </div>

    <p class="onb-hint">${uiT('sub.composeHint','Scegli ogni pasto, con alimenti e grammature, come faresti in un ordine normale.')}</p>
    ${filled ? `<div class="sub-modes"><button class="btn btn-ghost" style="flex:1;" data-action="sub-clear">${uiT('sub.clear','Svuota')}</button></div>` : ''}

    <div class="sub-week">${grid}</div>
    <button class="btn btn-primary btn-block" style="margin-top:18px;" data-action="sub-step3" ${filled===slots.length?'':'disabled'}>
      ${filled===slots.length ? uiT('common.continue','Continua') : (slots.length-filled === 1 ? uiT('sub.oneMealMissing','Manca 1 pasto') : `${uiT('sub.mealsMissing','Mancano')} ${slots.length-filled} ${uiT('sub.mealsWord','pasti')}`)}
    </button>
  `;
}

/* Selettore piatto per un singolo slot */
