/* Azioni dei pulsanti (data-action) */
defineActions({
  'business-lead-submit'(){
    const company = (document.getElementById('biz-company').value||'').trim();
    const email = (document.getElementById('biz-email').value||'').trim();
    const people = (document.getElementById('biz-people').value||'').trim();
    if(!company || !email || !people){ toast(uiT('toast.missing','Mancano')+': '+[!company&&uiT('business.companyName','Nome azienda / palestra'), !email&&'Email', !people&&uiT('business.peopleCount','Numero indicativo di persone')].filter(Boolean).join(', ')); return; }
    if(!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)){ toast(uiT('toast.invalidEmail','Email non valida')); return; }
    STATE.businessLead = { company, email, people, submittedAt: Date.now() };
    saveState();
    toast(uiT('business.requestSentToast','Richiesta inviata'));
    render();
  },
  'business-lead-reset'(){
    STATE.businessLead = null;
    saveState(); render();
  },
});

