  macros:'I miei macro', personal:'Dati personali',
  dessert:'Dolce', jar:'Integratore', portion:'Alimento', nutri:'Consulenze', 'nutri-book':'Prenota', 'nutri-chat':'Chat', 'diary-history':'Storico', weight:'Peso e progressi', sub:"Weekly Box", 'sub-plan':"Weekly Box", 'sub-builder':'La tua settimana',
  'sub-pick':'Scegli il piatto', 'sub-logistics':'Consegna', favorites:'Preferiti', orders:'Ordini effettuati', 'order-detail':'Dettaglio ordine', payments:'Metodi di pagamento',
  vouchers:'Voucher', appearance:'Aspetto', language:'Lingua', notifications:'Notifiche', about:'Info e supporto', disclaimer:'Avvertenza', family:'Menu',
